window.__X_NEWS__ = {"updated_at": "2026-10-22 04:22 Asia/Shanghai", "updated_at_iso": "2026-10-21T20:22:41Z", "count": 91, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112994544845472129", "domain": "科技", "url": "https://x.com/i/trending/2112994544845472129", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:58:47.000Z", "title_en": "Early Tests Praise Gemini 4 Carbon's 3D Generation Leap", "title_zh": "早期测试赞美Gemini 4 Carbon的3D一代飞跃", "hook_en": "Early testers are sharing stunning voxel landscapes and reflective water scenes from Gemini 4 Carbon, calling its 3D visuals a clear step up from previous models.", "hook_zh": "早期的测试人员正在分享Gemini 4 Carbon令人惊叹的体素景观和反光水景，称其3D视觉效果明显优于以前的模型。", "summary_en": "Google's Gemini 4 Carbon, now in early access for partners and tested on LMArena, stands out for polished 3D outputs like detailed environments and better geometry handling, even if it's slower than Gemini 4 Argon. Users note huge improvements in visual consistency on complex prompts, with one saying the quality jump feels totally justified. This follows Argon's late September launch as a reasoning model for tasks like coding, amid Google's push to compete in AI with rapid iterations and a discounted Pro plan at $4.99 monthly.", "summary_zh": "谷歌的Gemini 4 Carbon现在可供合作伙伴抢先体验，并在LMArena上进行了测试，即使比Gemini 4 Argon慢，它在细致的环境和更好的几何处理等抛光3D输出方面也脱颖而出。用户注意到复杂提示在视觉一致性方面的巨大改进，其中一位用户表示，质量跳跃感觉完全合理。 在此之前， Argon于9月下旬推出，作为编码等任务的推理模型，谷歌正努力通过快速迭代和每月$ 4.99的折扣Pro计划在人工智能领域展开竞争。", "body_en": "Early Tests Praise Gemini 4 Carbon's 3D Generation Leap.\n\nEarly testers are sharing stunning voxel landscapes and reflective water scenes from Gemini 4 Carbon, calling its 3D visuals a clear step up from previous models.\n\nGoogle's Gemini 4 Carbon, now in early access for partners and tested on LMArena, stands out for polished 3D outputs like detailed environments and better geometry handling, even if it's slower than Gemini 4 Argon.\n\nUsers note huge improvements in visual consistency on complex prompts, with one saying the quality jump feels totally justified. This follows Argon's late September launch as a reasoning model for tasks like coding, amid Google's push to compete in AI with rapid iterations and a discounted Pro plan at $4.99 monthly.", "body_zh": "早期的测试人员正在分享Gemini 4 Carbon令人惊叹的体素景观和反光水景，称其3D视觉效果明显优于以前的模型。\n\n谷歌的Gemini 4 Carbon现在可供合作伙伴抢先体验，并在LMArena上进行了测试，即使比Gemini 4 Argon慢，它在细致的环境和更好的几何处理等抛光3D输出方面也脱颖而出。\n\n用户注意到复杂提示在视觉一致性方面的巨大改进，其中一位用户表示，质量跳跃感觉完全合理。在此之前， Argon于9月下旬推出，作为编码等任务的推理模型，谷歌正努力通过快速迭代和每月$ 4.99的折扣Pro计划在人工智能领域展开竞争。"}, {"id": "2112833224569237819", "domain": "科技", "url": "https://x.com/i/trending/2112833224569237819", "category": "News", "topics": ["Business & Finance", "Technology", "AI"], "updated_at": "2026-10-21T19:57:01.000Z", "title_en": "Eternal Reports 78% Revenue Jump, Unveils Privacy AI Dark.ai", "title_zh": "Eternal Reports 78%的收入增长，推出隐私AI Dark.ai", "hook_en": "Deepinder Goyal shared a sleek teaser for Dark.ai on X, promising an AI tool where even the company can't peek at your chats. It arrived alongside blockbuster growth in Blinkit's quick deliveries.", "hook_zh": "Deepinder Goyal在X上为Dark.ai分享了一个时尚的预告片，承诺提供一种AI工具，即使公司也无法窥视您的聊天。它与Blinkit的快速交付大幅增长并驾齐驱。", "summary_en": "Eternal Ltd, behind Zomato and Blinkit, posted Q2 FY27 revenue of ₹24,138 crore, up 78% year-over-year, driven by Blinkit's 79.3% NOV surge to ₹20,940 crore and expansion to 2,751 dark stores. The company introduced Dark.ai, a privacy-focused AI on encrypted infrastructure for power users like founders and researchers, emphasizing truth-seeking models with user-controlled memory. While revenue beat estimates, net profit of ₹125 crore missed expectations, sending shares down 4.4% to ₹306 as investors eye the AI pivot.", "summary_zh": "在Zomato和Blinkit之后的Eternal Ltd公布的27财年第二季度收入为24,138千万卢比，同比增长78% ，这得益于Blinkit 11月份的79.3%激增至20,940千万卢比，并扩展到2,751家黑店。该公司推出了Dark.ai ，这是一种专注于隐私的人工智能，为创始人和研究人员等高级用户提供加密基础设施，强调具有用户控制内存的真相寻求模型。 虽然收入高于预期，但净利润12.5亿₹低于预期，导致股价下跌4.4%至306 ₹ ，因为投资者关注人工智能支点。", "body_en": "Eternal Reports 78% Revenue Jump, Unveils Privacy AI Dark.ai.\n\nDeepinder Goyal shared a sleek teaser for Dark.ai on X, promising an AI tool where even the company can't peek at your chats. It arrived alongside blockbuster growth in Blinkit's quick deliveries.\n\nEternal Ltd, behind Zomato and Blinkit, posted Q2 FY27 revenue of ₹24,138 crore, up 78% year-over-year, driven by Blinkit's 79.3% NOV surge to ₹20,940 crore and expansion to 2,751 dark stores.\n\nThe company introduced Dark.ai, a privacy-focused AI on encrypted infrastructure for power users like founders and researchers, emphasizing truth-seeking models with user-controlled memory. While revenue beat estimates, net profit of ₹125 crore missed expectations, sending shares down 4.4% to ₹306 as investors eye the AI pivot.", "body_zh": "Deepinder Goyal在X上为Dark.ai分享了一个时尚的预告片，承诺提供一种AI工具，即使公司也无法窥视您的聊天。它与Blinkit的快速交付大幅增长并驾齐驱。\n\n在Zomato和Blinkit之后的Eternal Ltd公布的27财年第二季度收入为24,138千万卢比，同比增长78% ，这得益于Blinkit 11月份的79.3%激增至20,940千万卢比，并扩展到2,751家黑店。\n\n该公司推出了Dark.ai ，这是一种专注于隐私的人工智能，为创始人和研究人员等高级用户提供加密基础设施，强调具有用户控制内存的真相寻求模型。虽然收入高于预期，但净利润12.5亿₹低于预期，导致股价下跌4.4%至306 ₹ ，因为投资者关注人工智能支点。"}, {"id": "2112883740699480270", "domain": "科技", "url": "https://x.com/i/trending/2112883740699480270", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:43:33.000Z", "title_en": "OpenAI Brings Frontier Models to Google Cloud Platform", "title_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden", "hook_en": "OpenAI is expanding beyond Microsoft, teaming up with Google Cloud to make its cutting-edge AI models easily available right where enterprises already run their operations.", "hook_zh": "GPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。", "summary_en": "The new partnership lets customers access OpenAI's GPT-6 Astra, GPT-6.1 Sol, GPT-6 Luna, and Codex workflows directly through Google Cloud's Model Garden and Marketplace. Enterprises can use their existing Google Cloud commitments to purchase these models, simplifying how they build complex AI agents at scale. Google Cloud now offers Gemini, Claude, and GPT models alongside over 200 others on one platform, following OpenAI's recent moves to AWS after ending its Microsoft exclusivity. This deal highlights growing customer choice across major cloud providers for top AI technology.", "summary_zh": "谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "body_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden.\n\nOpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.\n\nGoogle Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling.\n\nThis expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "body_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden。\n\nGPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。\n\n谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。\n\n此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。"}, {"id": "2112984437868675094", "domain": "科技", "url": "https://x.com/i/trending/2112984437868675094", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:16:33.000Z", "title_en": "Anthropic Details Safety Efforts in Public Benefit Report", "title_zh": "《公益报告》中的人性化细节安全措施", "hook_en": "Anthropic's CEO Dario Amodei stepped into the spotlight to defend his company's safety-first push amid rising scrutiny on AI development.", "hook_zh": "Anthropic的首席执行官Dario Amodei站在聚光灯下，在人工智能开发受到越来越多审查的情况下，捍卫公司的安全第一。", "summary_en": "Anthropic released its annual Public Benefit Report, outlining five pillars for responsibly advancing AI to benefit humanity long-term. CEO Dario Amodei highlighted nine costly actions from the past year, like delaying model releases for better cyber defenses, blocking bioweapon misuse attempts, and restricting sales to PRC-linked entities. The report also announced a new public benefit fund backed by 5% of shares, building on prior pledges totaling about 20% of equity. While Amodei frames it as a 'race to the top' that lifts industry standards, some critics question the timing near a potential IPO and policy choices.", "summary_zh": "Anthropic发布了年度《公共福利报告》，概述了负责任地推进人工智能以造福人类的五大支柱。首席执行官Dario Amodei强调了过去一年采取的九项代价高昂的行动，例如推迟模型发布以改善网络防御，阻止生物武器滥用企图，以及限制向与中国相关的实体销售。 该报告还宣布了一项新的公益基金，由5 ％的股份支持，以先前总计约20 ％的股权为基础。虽然Amodei将其描述为提升行业标准的“向顶级竞赛” ，但一些批评者质疑潜在的IPO和政策选择的时机。", "body_en": "Anthropic Details Safety Efforts in Public Benefit Report.\n\nAnthropic's CEO Dario Amodei stepped into the spotlight to defend his company's safety-first push amid rising scrutiny on AI development.\n\nAnthropic released its annual Public Benefit Report, outlining five pillars for responsibly advancing AI to benefit humanity long-term. CEO Dario Amodei highlighted nine costly actions from the past year, like delaying model releases for better cyber defenses, blocking bioweapon misuse attempts, and restricting sales to PRC-linked entities.\n\nThe report also announced a new public benefit fund backed by 5% of shares, building on prior pledges totaling about 20% of equity. While Amodei frames it as a 'race to the top' that lifts industry standards, some critics question the timing near a potential IPO and policy choices.", "body_zh": "Anthropic的首席执行官Dario Amodei站在聚光灯下，在人工智能开发受到越来越多审查的情况下，捍卫公司的安全第一。\n\nAnthropic发布了年度《公共福利报告》，概述了负责任地推进人工智能以造福人类的五大支柱。首席执行官Dario Amodei强调了过去一年采取的九项代价高昂的行动，例如推迟模型发布以改善网络防御，阻止生物武器滥用企图，以及限制向与中国相关的实体销售。\n\n该报告还宣布了一项新的公益基金，由5 ％的股份支持，以先前总计约20 ％的股权为基础。虽然Amodei将其描述为提升行业标准的“向顶级竞赛” ，但一些批评者质疑潜在的IPO和政策选择的时机。"}, {"id": "2112299444591116780", "domain": "科技", "url": "https://x.com/i/trending/2112299444591116780", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:15:44.000Z", "title_en": "Amazon and Google Launch PyTorch Tools for Custom AI Chips", "title_zh": "亚马逊和谷歌推出用于定制AI芯片的PyTorch工具", "hook_en": "Developers can now run PyTorch code on Amazon and Google's AI chips with just a single tweak, easing the switch from Nvidia hardware.", "hook_zh": "开发人员现在可以在亚马逊和谷歌的人工智能芯片上运行PyTorch代码，只需一次调整，就可以轻松切换Nvidia硬件。", "summary_en": "Amazon released TorchNeuron for its Trainium chips, while Google unveiled TorchTPU for TPUs, both open-source backends that support eager execution and fast inference on large models like Llama 3 405B. Amazon CEO Andy Jassy noted that one configuration change replaces hours of code rewriting, and Google engineer Adam Mainz celebrated the milestone. These tools, announced at the PyTorch Conference North America, boost hardware options amid PyTorch's growth, with Intel and AMD also unifying CPU support to cut developer fragmentation.", "summary_zh": "亚马逊为其Trainium芯片发布了TorchNeuron ，而谷歌则推出了用于TPU的TorchTPU ，这两个开源后端都支持Llama 3 405B等大型模型的急切执行和快速推理。亚马逊首席执行官安迪·贾西（ Andy Jassy ）指出，一次配置更改取代了数小时的代码重写，谷歌工程师亚当·美因茨（ Adam Mainz ）庆祝了这一里程碑。 在PyTorch北美大会上宣布的这些工具在PyTorch的增长中增加了硬件选择，英特尔和AMD也统一了对CPU的支持，以减少开发人员的碎片化。", "body_en": "Amazon and Google Launch PyTorch Tools for Custom AI Chips.\n\nDevelopers can now run PyTorch code on Amazon and Google's AI chips with just a single tweak, easing the switch from Nvidia hardware.\n\nAmazon released TorchNeuron for its Trainium chips, while Google unveiled TorchTPU for TPUs, both open-source backends that support eager execution and fast inference on large models like Llama 3 405B.\n\nAmazon CEO Andy Jassy noted that one configuration change replaces hours of code rewriting, and Google engineer Adam Mainz celebrated the milestone. These tools, announced at the PyTorch Conference North America, boost hardware options amid PyTorch's growth, with Intel and AMD also unifying CPU support to cut developer fragmentation.", "body_zh": "开发人员现在可以在亚马逊和谷歌的人工智能芯片上运行PyTorch代码，只需一次调整，就可以轻松切换Nvidia硬件。\n\n亚马逊为其Trainium芯片发布了TorchNeuron ，而谷歌则推出了用于TPU的TorchTPU ，这两个开源后端都支持Llama 3 405B等大型模型的急切执行和快速推理。\n\n亚马逊首席执行官安迪·贾西（ Andy Jassy ）指出，一次配置更改取代了数小时的代码重写，谷歌工程师亚当·美因茨（ Adam Mainz ）庆祝了这一里程碑。在PyTorch北美大会上宣布的这些工具在PyTorch的增长中增加了硬件选择，英特尔和AMD也统一了对CPU的支持，以减少开发人员的碎片化。"}, {"id": "2112905933601063227", "domain": "科技", "url": "https://x.com/i/trending/2112905933601063227", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T19:04:30.000Z", "title_en": "iPhone Duo Reviews Praise Foldable Fun but Flag Key Drawbacks", "title_zh": "iPhone Duo评论赞美可折叠的乐趣，但标志关键缺点", "hook_en": "Reviewers unboxing Apple's first foldable iPhone can't stop smiling at its clever hinge and big inner screen, but the joy fades when apps glitch and cameras underperform.", "hook_zh": "拆箱苹果首款可折叠iPhone的评论家们不能停止对它巧妙的铰链和大屏幕的微笑，但当应用程序出现故障和相机表现不佳时，这种喜悦就会消失。", "summary_en": "The $1,999 iPhone Duo unfolds from a 5.4-inch outer display to a 7.6-inch inner one, powered by the A20 Pro chip and a battery that lasts over 13 hours in tests. Testers like Marques Brownlee call it 'first generation fun' with premium build and strong performance, yet criticize its 254-gram weight, weaker cameras without a telephoto lens, Touch ID instead of Face ID, and apps that scale poorly or show black bars. Many advise waiting for developer updates, as early reviews echo growing pains from past innovations like the original Galaxy Fold.", "summary_zh": "$ 1,999的iPhone Duo从5.4英寸的外部显示屏展开到7.6英寸的内部显示屏，由A20 Pro芯片和持续13小时以上的电池供电。像Marques Brownlee这样的测试人员称其为“第一代乐趣” ，具有优质的构建和强大的性能，但批评其254克的重量，没有长焦镜头的较弱相机， Touch ID而不是Face ID ，以及扩展性差或显示黑条的应用程序。 许多人建议等待开发人员更新，因为早期的评论与原始Galaxy Fold等过去创新的成长痛苦相呼应。", "body_en": "iPhone Duo Reviews Praise Foldable Fun but Flag Key Drawbacks.\n\nReviewers unboxing Apple's first foldable iPhone can't stop smiling at its clever hinge and big inner screen, but the joy fades when apps glitch and cameras underperform.\n\nThe $1,999 iPhone Duo unfolds from a 5.4-inch outer display to a 7.6-inch inner one, powered by the A20 Pro chip and a battery that lasts over 13 hours in tests.\n\nTesters like Marques Brownlee call it 'first generation fun' with premium build and strong performance, yet criticize its 254-gram weight, weaker cameras without a telephoto lens, Touch ID instead of Face ID, and apps that scale poorly or show black bars. Many advise waiting for developer updates, as early reviews echo growing pains from past innovations like the original Galaxy Fold.", "body_zh": "拆箱苹果首款可折叠iPhone的评论家们不能停止对它巧妙的铰链和大屏幕的微笑，但当应用程序出现故障和相机表现不佳时，这种喜悦就会消失。\n\n$ 1,999的iPhone Duo从5.4英寸的外部显示屏展开到7.6英寸的内部显示屏，由A20 Pro芯片和持续13小时以上的电池供电。\n\n像Marques Brownlee这样的测试人员称其为“第一代乐趣” ，具有优质的构建和强大的性能，但批评其254克的重量，没有长焦镜头的较弱相机， Touch ID而不是Face ID ，以及扩展性差或显示黑条的应用程序。许多人建议等待开发人员更新，因为早期的评论与原始Galaxy Fold等过去创新的成长痛苦相呼应。"}, {"id": "2112620331987062878", "domain": "科技", "url": "https://x.com/i/trending/2112620331987062878", "category": "News", "topics": ["Business & Finance", "Technology", "AI"], "updated_at": "2026-10-21T19:04:21.000Z", "title_en": "Investors Buy Record CDS to Hedge AI Firm Debt Risks", "title_zh": "投资者创纪录买入 CDS，对冲 AI 企业债务风险", "hook_en": "As AI companies borrow billions for data centers, investors are snapping up credit default swaps at unprecedented levels to guard against defaults.", "hook_zh": "AI 公司为数据中心与芯片大举举债之际，投资者正以前所未有的规模买入信用违约互换，防范违约。", "summary_en": "Trading in CDS contracts on debt from Oracle, SpaceX, Alphabet, Amazon, Meta, Broadcom, and Nvidia jumped to over $9 billion weekly in September, up from under $2 billion in July, with spreads hitting records like Meta's 108 basis points and Nvidia's 101. This surge follows AI-linked U.S. corporate bond issuance reaching $419 billion year-to-date to fund infrastructure. A report from Americans for Financial Reform and the Open Markets Institute warns the repackaging of this debt to pension funds echoes the subprime bubble, though some see the hedging as smart caution amid strong tech earnings.", "summary_zh": "与 AI 相关企业在 2026 年累计发行约 4660 亿美元债务，超过去年四倍，支撑大规模数据中心与芯片投资。9 月针对甲骨文、英伟达、Meta 等债券的 CDS 周交易额达 90 亿美元，保护成本飙升——Meta 约 108 个基点、英伟达约 101，CoreWeave 则超过 1000、进入困境区间。分析人士如穆罕默德·埃里安对借贷潮表示不安，亦有报告警示再包装债务卖给养老金等资金或带有类似次贷的风险；也有观点以强劲盈利增长作为对冲论据。", "body_en": "Investors Buy Record CDS to Hedge AI Company Debt Risks.\n\nAs AI firms borrow billions for data centers and chips, investors are snapping up credit default swaps at unprecedented levels to guard against defaults.\n\nAI-linked companies issued $466 billion in debt through 2026, more than quadrupling last year's pace, fueling massive data center and chip investments.\n\nWeekly CDS trading on bonds from Oracle, Nvidia, Meta, and others hit $9 billion in September, with protection costs soaring—Meta at 108 basis points, Nvidia at 101, and CoreWeave over 1,000 in distressed levels. Analysts like Mohamed El-Erian flag unease over the borrowing surge, while reports warn of subprime-like risks in repackaged debt sold to pensions, though some point to strong earnings growth as a counterbalance.", "body_zh": "投资者创纪录买入 CDS，对冲 AI 企业债务风险。\n\nAI 公司为数据中心与芯片大举举债之际，投资者正以前所未有的规模买入信用违约互换，防范违约。\n\n与 AI 相关企业在 2026 年累计发行约 4660 亿美元债务，超过去年四倍，支撑大规模数据中心与芯片投资。\n\n9 月针对甲骨文、英伟达、Meta 等债券的 CDS 周交易额达 90 亿美元，保护成本飙升——Meta 约 108 个基点、英伟达约 101，CoreWeave 则超过 1000、进入困境区间。分析人士如穆罕默德·埃里安对借贷潮表示不安，亦有报告警示再包装债务卖给养老金等资金或带有类似次贷的风险；也有观点以强劲盈利增长作为对冲论据。"}, {"id": "2112891431501390231", "domain": "科技", "url": "https://x.com/i/trending/2112891431501390231", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T19:02:53.000Z", "title_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents", "title_zh": "NVIDIA推出OpenShell以保护企业AI代理", "hook_en": "At GTC Berlin, NVIDIA CEO Jensen Huang showed how businesses can now run AI agents freely—yet safely—by setting strict boundaries that stop them cold if crossed.", "hook_zh": "在GTC柏林， NVIDIA首席执行官Jensen Huang展示了企业现在如何通过设置严格的界限，在跨越界限时阻止他们自由运行AI代理，从而安全地运行AI代理。", "summary_en": "The OpenShell Reference Architecture pairs NVIDIA's Vera Rubin systems, Vera CPUs, and BlueField-4 DPUs with Sentry software for real-time monitoring, quarantining rogue agents in milliseconds. It builds on prior safety work, enforces zero-trust policies where permissions are denied by default, and is open source under Apache 2.0. Over 100 partners like Anthropic, AWS, Microsoft, and OpenAI are adopting it, with banks and firms like SAP integrating for edge and enterprise use. Huang emphasized accelerating AI safety alongside capability to deploy billions of agents responsibly.", "summary_zh": "OpenShell参考架构将NVIDIA的Vera Rubin系统、Vera CPU和BlueField-4 DPU与Sentry软件配对，用于实时监控，在毫秒内隔离流氓代理。它建立在先前的安全工作的基础上，在默认情况下拒绝权限的情况下执行零信任策略，并且在Apache 2.0下是开源的。 Anthropic、AWS、Microsoft和OpenAI等100多个合作伙伴正在采用它， SAP等银行和公司整合了边缘和企业用途。Huang强调了加速人工智能安全以及负责任地部署数十亿代理的能力。", "body_en": "NVIDIA Unveils OpenShell to Secure Enterprise AI Agents.\n\nAt GTC Berlin, NVIDIA CEO Jensen Huang showed how businesses can now run AI agents freely—yet safely—by setting strict boundaries that stop them cold if crossed.\n\nThe OpenShell Reference Architecture pairs NVIDIA's Vera Rubin systems, Vera CPUs, and BlueField-4 DPUs with Sentry software for real-time monitoring, quarantining rogue agents in milliseconds. It builds on prior safety work, enforces zero-trust policies where permissions are denied by default, and is open source under Apache 2.0.\n\nOver 100 partners like Anthropic, AWS, Microsoft, and OpenAI are adopting it, with banks and firms like SAP integrating for edge and enterprise use. Huang emphasized accelerating AI safety alongside capability to deploy billions of agents responsibly.", "body_zh": "在GTC柏林， NVIDIA首席执行官Jensen Huang展示了企业现在如何通过设置严格的界限，在跨越界限时阻止他们自由运行AI代理，从而安全地运行AI代理。\n\nOpenShell参考架构将NVIDIA的Vera Rubin系统、Vera CPU和BlueField-4 DPU与Sentry软件配对，用于实时监控，在毫秒内隔离流氓代理。它建立在先前的安全工作的基础上，在默认情况下拒绝权限的情况下执行零信任策略，并且在Apache 2.0下是开源的。\n\nAnthropic、AWS、Microsoft和OpenAI等100多个合作伙伴正在采用它， SAP等银行和公司整合了边缘和企业用途。Huang强调了加速人工智能安全以及负责任地部署数十亿代理的能力。"}, {"id": "2112905935199125989", "domain": "科技", "url": "https://x.com/i/trending/2112905935199125989", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T18:52:21.000Z", "title_en": "DeepSeek Open-Sources High-Performance AI Inference Engine Amid Google TPU Push", "title_zh": "Google TPU推送中的DeepSeek开源高性能AI推理引擎", "hook_en": "DeepSeek just released the code behind its powerhouse AI services, letting developers run massive models at blazing speeds on everyday hardware.", "hook_zh": "DeepSeek刚刚发布了其强大的人工智能服务背后的代码，允许开发人员在日常硬件上以惊人的速度运行大量模型。", "summary_en": "Chinese firm DeepSeek unveiled DeepSeek-V4.1-Flash, a large multimodal model, and open-sourced DeepInfer, its optimized inference framework under Apache-2.0 license. It supports NVIDIA Blackwell, Huawei Ascend, and delivers impressive local speeds like 410 tokens per second on four RTX PRO 6000 GPUs. Meanwhile, Google open-sourced TorchTPU at the PyTorch Conference, enabling PyTorch code to run seamlessly on Cloud TPUs. These steps boost AI accessibility despite U.S. federal restrictions on DeepSeek products over data risks.", "summary_zh": "中国公司DeepSeek推出了大型多模态模型DeepSeek-V4.1-Flash和开源的DeepInfer ，后者是Apache-2.0许可下的优化推理框架。它支持NVIDIA Blackwell、华为Ascend ，并在四个RTX PRO 6000 GPU上提供令人印象深刻的本地速度，如每秒410个令牌。同时，谷歌在PyTorch大会上开源了TorchTPU ，使PyTorch代码能够在云TPU上无缝运行。 这些步骤提高了人工智能的可访问性，尽管美国联邦政府对DeepSeek产品的数据风险进行了限制。", "body_en": "DeepSeek Open-Sources High-Performance AI Inference Engine Amid Google TPU Push.\n\nDeepSeek just released the code behind its powerhouse AI services, letting developers run massive models at blazing speeds on everyday hardware.\n\nChinese firm DeepSeek unveiled DeepSeek-V4.1-Flash, a large multimodal model, and open-sourced DeepInfer, its optimized inference framework under Apache-2.0 license. It supports NVIDIA Blackwell, Huawei Ascend, and delivers impressive local speeds like 410 tokens per second on four RTX PRO 6000 GPUs.\n\nMeanwhile, Google open-sourced TorchTPU at the PyTorch Conference, enabling PyTorch code to run seamlessly on Cloud TPUs. These steps boost AI accessibility despite U.S. federal restrictions on DeepSeek products over data risks.", "body_zh": "DeepSeek刚刚发布了其强大的人工智能服务背后的代码，允许开发人员在日常硬件上以惊人的速度运行大量模型。\n\n中国公司DeepSeek推出了大型多模态模型DeepSeek-V4.1-Flash和开源的DeepInfer ，后者是Apache-2.0许可下的优化推理框架。它支持NVIDIA Blackwell、华为Ascend ，并在四个RTX PRO 6000 GPU上提供令人印象深刻的本地速度，如每秒410个令牌。\n\n同时，谷歌在PyTorch大会上开源了TorchTPU ，使PyTorch代码能够在云TPU上无缝运行。这些步骤提高了人工智能的可访问性，尽管美国联邦政府对DeepSeek产品的数据风险进行了限制。"}, {"id": "2112891431543275870", "domain": "科技", "url": "https://x.com/i/trending/2112891431543275870", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:58:40.000Z", "title_en": "NVIDIA Unveils DSX POD for Rapid AI Factory Deployment", "title_zh": "英伟达 DSX POD：两周内搭起 AI 工厂", "hook_en": "NVIDIA just made building massive AI factories way faster—cutting setup from six months to just 14 days with ready-to-ship containers.", "hook_zh": "过去数月才能建起的巨型 AI 工厂，英伟达新设计宣称最快约 14 天就能交付。", "summary_en": "At GTC Berlin, NVIDIA introduced the DSX POD, a shipping container packed with seven Vera Rubin racks, pre-integrated with cabling, power, and liquid cooling for quick worldwide delivery starting early 2027. CEO Jensen Huang pointed out assembly now takes under five minutes per node—a 24x speedup over before—unlocking billions in revenue by slashing delays on gigawatt-scale projects that cost $50 billion but generate $40 billion yearly. Google Cloud jumped in with A5X instances using Vera Rubin NVL72 systems, aiming for 960,000 GPUs, while partners like Dell and HPE build out the ecosystem to speed AI infrastructure worldwide.", "summary_zh": "在柏林 GTC 上，英伟达发布 DSX POD：把 Vera Rubin AI 工厂做成可由戴尔、HPE、联想等伙伴预装测试的集装箱式模块。在电力、冷却与网络就绪后，部署可压缩到约 14 天，以缓解吉瓦级机房因延期损失的收入。设计还采用闭环液冷，据称可大幅减少用水并降低约 30% 功耗。伙伴计划自 2027 年初起全球交付。", "body_en": "NVIDIA's DSX POD Speeds AI Factories to 14 Days.\n\nImagine spinning up a massive AI factory in just two weeks instead of months. NVIDIA's new design makes that real, easing the rush for builders racing to capture billions in revenue.\n\nAt its GTC conference in Berlin, NVIDIA unveiled the DSX POD, a modular system that packages Vera Rubin AI factories into shippable containers built and tested by partners like Dell, HPE, and Lenovo. These units cut deployment time to as little as 14 days once power, cooling, and networking are ready, addressing delays that cost billions in lost revenue for 1-gigawatt facilities.\n\nThe design also boosts efficiency with closed-loop liquid cooling that slashes water use by up to 100 percent and power needs by 30 percent, helping operators generate output while permanent data centers are built. Partners will deliver the PODs worldwide starting early 2027.", "body_zh": "英伟达 DSX POD：两周内搭起 AI 工厂。\n\n过去数月才能建起的巨型 AI 工厂，英伟达新设计宣称最快约 14 天就能交付。\n\n在柏林 GTC 上，英伟达发布 DSX POD：把 Vera Rubin AI 工厂做成可由戴尔、HPE、联想等伙伴预装测试的集装箱式模块。在电力、冷却与网络就绪后，部署可压缩到约 14 天，以缓解吉瓦级机房因延期损失的收入。\n\n设计还采用闭环液冷，据称可大幅减少用水并降低约 30% 功耗。伙伴计划自 2027 年初起全球交付。"}, {"id": "2112598856852488607", "domain": "科技", "url": "https://x.com/i/trending/2112598856852488607", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:58:04.000Z", "title_en": "Perplexity's AI Agent Now Runs Fully Local on Macs", "title_zh": "Perplexity的AI代理现在在Mac上完全本地运行", "hook_en": "Imagine firing up your AI assistant on your Mac without any internet—everything from reasoning to file handling stays right on your device. Perplexity just made that a reality for privacy-focused users.", "hook_zh": "想象一下，在没有任何互联网的情况下在Mac上启动人工智能助手--从推理到文件处理，一切都留在您的设备上。对于注重隐私的用户来说，困惑使之成为现实。", "summary_en": "Perplexity updated its Computer AI agent to operate entirely offline on Apple Silicon Macs, processing tasks with native apps like Notes and Mail while keeping data local and private. CEO Aravind Srinivas announced it works without cloud inference or WiFi, using models like Qwen 3.6, and it's available now for Pro, Max, and Enterprise subscribers—no credits needed for local tasks. A hybrid mode blends local and cloud for tougher jobs, though smooth performance requires at least 36GB of unified memory. This shift highlights growing on-device AI capabilities, with users excited about the privacy and control it brings.", "summary_zh": "Perplexity更新了其计算机AI代理，使其在Apple Silicon Mac上完全离线运行，使用Notes和Mail等本机应用程序处理任务，同时保持数据的本地和私有性。首席执行官Aravind Srinivas宣布，它无需云推断或WiFi ，使用Qwen 3.6等型号，现在可供Pro、Max和Enterprise订阅者使用，无需本地任务积分。 混合模式将本地和云混合在一起，以应对更艰巨的工作，尽管平稳的性能需要至少36GB的统一内存。这一转变凸显了不断增长的设备上人工智能功能，用户对其带来的隐私和控制感到兴奋。", "body_en": "Imagine firing up your AI assistant on your Mac without any internet—everything from reasoning to file handling stays right on your device. Perplexity just made that a reality for privacy-focused users.\n\nPerplexity updated its Computer AI agent to operate entirely offline on Apple Silicon Macs, processing tasks with native apps like Notes and Mail while keeping data local and private. CEO Aravind Srinivas announced it works without cloud inference or WiFi, using models like Qwen 3.6, and it's available now for Pro, Max, and Enterprise subscribers—no credits needed for local tasks.\n\nA hybrid mode blends local and cloud for tougher jobs, though smooth performance requires at least 36GB of unified memory. This shift highlights growing on-device AI capabilities, with users excited about the privacy and control it brings.", "body_zh": "想象一下，在没有任何互联网的情况下在Mac上启动人工智能助手--从推理到文件处理，一切都留在您的设备上。对于注重隐私的用户来说，困惑使之成为现实。\n\nPerplexity更新了其计算机AI代理，使其在Apple Silicon Mac上完全离线运行，使用Notes和Mail等本机应用程序处理任务，同时保持数据的本地和私有性。首席执行官Aravind Srinivas宣布，它无需云推断或WiFi ，使用Qwen 3.6等型号，现在可供Pro、Max和Enterprise订阅者使用，无需本地任务积分。\n\n混合模式将本地和云混合在一起，以应对更艰巨的工作，尽管平稳的性能需要至少36GB的统一内存。这一转变凸显了不断增长的设备上人工智能功能，用户对其带来的隐私和控制感到兴奋。"}, {"id": "2112958298765119976", "domain": "科技", "url": "https://x.com/i/trending/2112958298765119976", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:32:37.000Z", "title_en": "Micron Details AI-Driven Memory Demand Surge in Webinar", "title_zh": "美光在网络研讨会中详细介绍人工智能驱动的内存需求激增", "hook_en": "Scott DeBoer kicked off Micron's webinar with slides that had one viewer hooked from the start. The talk laid out how each new AI wave piles on fresh memory needs.", "hook_zh": "Scott DeBoer以幻灯片开始了美光的网络研讨会，从一开始就吸引了一名观众。演讲阐述了每一个新的人工智能浪潮是如何堆积在新鲜记忆需求上的。", "summary_en": "During the October 21 webinar, Micron's President and Chief Technology Officer Scott DeBoer explained rising memory demands across AI training, inference, agents, and physical systems like robotaxis. Key highlights included first public looks at upcoming DRAM nodes, next-gen HBM for data centers and edge AI, and AI-optimized NAND, with training now needing 3.6 times more HBM per GPU and agentic AI pushing context lengths up 30 times yearly. The company plans custom HBM4E by 2027 and 3D-stacked memory on processors by 2028, amid optimism that supply constraints will keep demand strong as AI expands beyond data centers.", "summary_zh": "在10月21日的网络研讨会上，美光总裁兼首席技术官Scott DeBoer解释了人工智能培训、推理、代理和机器人出租车等物理系统中不断增长的内存需求。主要亮点包括首次公开关注即将推出的DRAM节点、用于数据中心和边缘AI的下一代HBM以及AI优化的NAND ，现在每个GPU的培训需要3.6倍的HBM ，而代理AI每年需要将上下文长度提高30倍。 该公司计划在2027年之前定制HBM4E ，并在2028年之前在处理器上堆叠3D内存，因为人们乐观地认为，随着人工智能扩展到数据中心之外，供应限制将保持强劲的需求。", "body_en": "Scott DeBoer kicked off Micron's webinar with slides that had one viewer hooked from the start. The talk laid out how each new AI wave piles on fresh memory needs.\n\nDuring the October 21 webinar, Micron's President and Chief Technology Officer Scott DeBoer explained rising memory demands across AI training, inference, agents, and physical systems like robotaxis.\n\nKey highlights included first public looks at upcoming DRAM nodes, next-gen HBM for data centers and edge AI, and AI-optimized NAND, with training now needing 3.6 times more HBM per GPU and agentic AI pushing context lengths up 30 times yearly. The company plans custom HBM4E by 2027 and 3D-stacked memory on processors by 2028, amid optimism that supply constraints will keep demand strong as AI expands beyond data centers.", "body_zh": "Scott DeBoer以幻灯片开始了美光的网络研讨会，从一开始就吸引了一名观众。演讲阐述了每一个新的人工智能浪潮是如何堆积在新鲜记忆需求上的。\n\n在10月21日的网络研讨会上，美光总裁兼首席技术官Scott DeBoer解释了人工智能培训、推理、代理和机器人出租车等物理系统中不断增长的内存需求。\n\n主要亮点包括首次公开关注即将推出的DRAM节点、用于数据中心和边缘AI的下一代HBM以及AI优化的NAND ，现在每个GPU的培训需要3.6倍的HBM ，而代理AI每年需要将上下文长度提高30倍。该公司计划在2027年之前定制HBM4E ，并在2028年之前在处理器上堆叠3D内存，因为人们乐观地认为，随着人工智能扩展到数据中心之外，供应限制将保持强劲的需求。"}, {"id": "2112575527206969617", "domain": "科技", "url": "https://x.com/i/trending/2112575527206969617", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:22:34.000Z", "title_en": "Google's Gemini 4 Argon Processes 25 Trillion Tokens in First 72 Hours", "title_zh": "谷歌的Gemini 4 Argon在前72小时内处理了25万亿个代币", "hook_en": "Google's new Gemini 4 Argon model hit the ground running, handling a massive 25 trillion tokens right after launch. One fun demo even built a 3D periodic table dancing to Tom Lehrer's 'The Elements' song.", "hook_zh": "谷歌的新Gemini 4 Argon型号在推出后立即投入使用，处理了25万亿个代币。一个有趣的演示甚至为Tom Lehrer的“The Elements”歌曲制作了一个3D元素周期表。", "summary_en": "Launched globally in mid-October 2026 via Gemini API, AI Studio, the app for paid users, and Google Antigravity, Argon excels in coding, finance, legal, science, and cybersecurity with its 1-million-token context window. It leads benchmarks like Isoquant's 4.38x speedup, Ramp's Accounting Bench at 61.1%, and Google's Vals Index, though T3 Code users hit 36.5 trillion tokens in the same period. Gemini 4 Carbon is already in early testing, showing gains in 3D tasks but running slower, as user feedback mixes praise for creativity with reports of crashes and quotas.", "summary_zh": "Argon于2026年10月中旬通过Gemini API、AI Studio、付费用户应用程序和Google Antigravity在全球推出，凭借其100万代币的上下文窗口， Argon在编码、金融、法律、科学和网络安全方面表现出色。它引领了Isoquant的4.38倍加速、Ramp's Accounting Bench的61.1%和谷歌的Vals Index等基准，尽管T3 Code用户在同一时期达到了36.5万亿个代币。 Gemini 4 Carbon已经处于早期测试阶段，显示3D任务有所增加，但运行速度较慢，因为用户反馈将对创造力的赞扬与崩溃和配额的报告相结合。", "body_en": "Google's new Gemini 4 Argon model hit the ground running, handling a massive 25 trillion tokens right after launch. One fun demo even built a 3D periodic table dancing to Tom Lehrer's 'The Elements' song.\n\nLaunched globally in mid-October 2026 via Gemini API, AI Studio, the app for paid users, and Google Antigravity, Argon excels in coding, finance, legal, science, and cybersecurity with its 1-million-token context window.\n\nIt leads benchmarks like Isoquant's 4.38x speedup, Ramp's Accounting Bench at 61.1%, and Google's Vals Index, though T3 Code users hit 36.5 trillion tokens in the same period. Gemini 4 Carbon is already in early testing, showing gains in 3D tasks but running slower, as user feedback mixes praise for creativity with reports of crashes and quotas.", "body_zh": "谷歌的新Gemini 4 Argon型号在推出后立即投入使用，处理了25万亿个代币。一个有趣的演示甚至为Tom Lehrer的“The Elements”歌曲制作了一个3D元素周期表。\n\nArgon于2026年10月中旬通过Gemini API、AI Studio、付费用户应用程序和Google Antigravity在全球推出，凭借其100万代币的上下文窗口， Argon在编码、金融、法律、科学和网络安全方面表现出色。\n\n它引领了Isoquant的4.38倍加速、Ramp's Accounting Bench的61.1%和谷歌的Vals Index等基准，尽管T3 Code用户在同一时期达到了36.5万亿个代币。Gemini 4 Carbon已经处于早期测试阶段，显示3D任务有所增加，但运行速度较慢，因为用户反馈将对创造力的赞扬与崩溃和配额的报告相结合。"}, {"id": "2112633705877340245", "domain": "商业", "url": "https://x.com/i/trending/2112633705877340245", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T19:58:38.000Z", "title_en": "Anthropic Reports $80.7 Billion Loss in Draft IPO Filing", "title_zh": "Anthropic报告IPO申请草稿亏损$ 807亿", "hook_en": "Anthropic's draft IPO papers revealed a staggering $80.7 billion net loss for early 2026, despite $16.3 billion in revenue—a number that has people talking about the true cost of building frontier AI.", "hook_zh": "Anthropic的IPO文件草案显示，尽管收入为163亿美元，但2026年初的净亏损达到惊人的807亿美元，这一数字让人们谈论构建前沿人工智能的真实成本。", "summary_en": "The AI company behind Claude posted $16.3 billion in revenue for the first half of 2026, up sharply from $1.1 billion a year before, but recorded an $80.7 billion net loss mostly from non-cash accounting adjustments on financing. Operating expenses included nearly $9 billion on compute and infrastructure, exceeding all of 2025, with long-term cloud deals totaling around $450 billion—including $111 billion with Google Cloud and $110 billion with AWS. The filing highlights risks like competition for compute, revenue from just two major customers, and potential liabilities from AI harms, as Anthropic eyes a public listing soon.", "summary_zh": "Claude背后的人工智能公司在2026年上半年的收入为163亿美元，比一年前的11亿美元大幅增加，但净亏损为807亿美元，主要来自融资的非现金会计调整。 运营支出包括近90亿美元的计算和基础设施支出，超过2025年全年，长期云交易总额约为4500亿美元，其中1110亿美元来自谷歌云， 1100亿美元来自AWS。该文件强调了计算竞争、仅来自两个主要客户的收入以及人工智能危害的潜在责任等风险，因为Anthropic很快就会公开上市。", "body_en": "Anthropic's draft IPO papers revealed a staggering $80.7 billion net loss for early 2026, despite $16.3 billion in revenue—a number that has people talking about the true cost of building frontier AI.\n\nThe AI company behind Claude posted $16.3 billion in revenue for the first half of 2026, up sharply from $1.1 billion a year before, but recorded an $80.7 billion net loss mostly from non-cash accounting adjustments on financing.\n\nOperating expenses included nearly $9 billion on compute and infrastructure, exceeding all of 2025, with long-term cloud deals totaling around $450 billion—including $111 billion with Google Cloud and $110 billion with AWS. The filing highlights risks like competition for compute, revenue from just two major customers, and potential liabilities from AI harms, as Anthropic eyes a public listing soon.", "body_zh": "Anthropic的IPO文件草案显示，尽管收入为163亿美元，但2026年初的净亏损达到惊人的807亿美元，这一数字让人们谈论构建前沿人工智能的真实成本。\n\nClaude背后的人工智能公司在2026年上半年的收入为163亿美元，比一年前的11亿美元大幅增加，但净亏损为807亿美元，主要来自融资的非现金会计调整。\n\n运营支出包括近90亿美元的计算和基础设施支出，超过2025年全年，长期云交易总额约为4500亿美元，其中1110亿美元来自谷歌云， 1100亿美元来自AWS。该文件强调了计算竞争、仅来自两个主要客户的收入以及人工智能危害的潜在责任等风险，因为Anthropic很快就会公开上市。"}, {"id": "2112994550260367511", "domain": "商业", "url": "https://x.com/i/trending/2112994550260367511", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T19:58:13.000Z", "title_en": "Meta and Tesla Earnings Set for Volatile Market Close", "title_zh": "Meta和特斯拉收益设定为波动性市场收盘", "hook_en": "Wall Street traders are on edge today as Meta and Tesla drop their third-quarter numbers after the bell on October 21, 2026—one of the year's busiest earnings days.", "hook_zh": "今天，随着Meta和特斯拉在2026年10月21日（今年最繁忙的盈利日之一）的钟声之后下跌第三季度数据，华尔街交易员感到不安。", "summary_en": "Meta faces scrutiny on its $63.38 billion revenue forecast, $4.98 earnings per share, ad strength, and AI spending plans, with options betting on a 7% stock swing. Tesla, trading near $387, eyes $0.45 adjusted earnings on $28.34 billion revenue after six straight misses, spotlighting auto margins, energy growth, cash flow, and robotaxi updates—deliveries hit 486,532 vehicles. Investors watch these Big Tech reports, plus IBM and others, for clues on demand in autos and ads amid AI cost pressures.", "summary_zh": "Meta面临着对其633.8亿美元收入预测、每股收益4.98美元、广告实力和人工智能支出计划的审查，期权押注7%的股票波动。特斯拉的交易价格接近387美元，在连续六次下跌后，调整后收益为283.4亿美元，关注汽车利润率、能源增长、现金流和机器人出租车更新，交付量达到486,532辆。 在人工智能成本压力下，投资者观看这些大型科技报告，以及IBM和其他公司的报告，了解汽车和广告的需求线索。", "body_en": "Meta and Tesla Earnings Set for Volatile Market Close.\n\nWall Street traders are on edge today as Meta and Tesla drop their third-quarter numbers after the bell on October 21, 2026—one of the year's busiest earnings days.\n\nMeta faces scrutiny on its $63.38 billion revenue forecast, $4.98 earnings per share, ad strength, and AI spending plans, with options betting on a 7% stock swing.\n\nTesla, trading near $387, eyes $0.45 adjusted earnings on $28.34 billion revenue after six straight misses, spotlighting auto margins, energy growth, cash flow, and robotaxi updates—deliveries hit 486,532 vehicles. Investors watch these Big Tech reports, plus IBM and others, for clues on demand in autos and ads amid AI cost pressures.", "body_zh": "今天，随着Meta和特斯拉在2026年10月21日（今年最繁忙的盈利日之一）的钟声之后下跌第三季度数据，华尔街交易员感到不安。\n\nMeta面临着对其633.8亿美元收入预测、每股收益4.98美元、广告实力和人工智能支出计划的审查，期权押注7%的股票波动。\n\n特斯拉的交易价格接近387美元，在连续六次下跌后，调整后收益为283.4亿美元，关注汽车利润率、能源增长、现金流和机器人出租车更新，交付量达到486,532辆。在人工智能成本压力下，投资者观看这些大型科技报告，以及IBM和其他公司的报告，了解汽车和广告的需求线索。"}, {"id": "2112867592407036230", "domain": "商业", "url": "https://x.com/i/trending/2112867592407036230", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T19:15:47.000Z", "title_en": "Indonesia's President Defies MSCI Downgrade Threat", "title_zh": "印尼总统抗拒MSCI降级威胁", "hook_en": "In a bold televised cabinet meeting, President Prabowo Subianto stared down global index provider MSCI, declaring his nation 'is not afraid of anyone and will not be intimidated.'", "hook_zh": "在一次大胆的电视内阁会议上，总统普拉博沃·苏比安托（ Prabowo Subianto ）盯着全球指数提供商MSCI ，宣布他的国家“不害怕任何人，也不会受到恐吓”。", "summary_en": "Prabowo's defiant words came as MSCI considers shifting Indonesia from emerging-market to standalone status due to concerns over market transparency and trading, following an October 15 announcement that sparked an 11 percent stock plunge—the worst one-day drop in nearly three decades. He framed the review as an attempt to frighten Indonesia, emphasizing the country's strength and resolve amid fears of capital outflows. Officials insist ongoing reforms for better governance and liquidity continue independently, while MSCI awaits sustained improvements before a mid-2027 decision.", "summary_zh": "由于对市场透明度和交易的担忧， MSCI考虑将印尼从新兴市场转变为独立市场，此前10月15日宣布股价暴跌11% ，这是近三十年来最大的单日跌幅。他认为这次审查是为了吓唬印度尼西亚，强调该国在担心资本外流的情况下的实力和决心。 官员们坚持认为，为改善治理和流动性而正在进行的改革将继续独立进行，而MSCI在2027年中期做出决定之前仍在等待持续改善。", "body_en": "Indonesia's President Defies MSCI Downgrade Threat.\n\nIn a bold televised cabinet meeting, President Prabowo Subianto stared down global index provider MSCI, declaring his nation 'is not afraid of anyone and will not be intimidated.'\n\nPrabowo's defiant words came as MSCI considers shifting Indonesia from emerging-market to standalone status due to concerns over market transparency and trading, following an October 15 announcement that sparked an 11 percent stock plunge—the worst one-day drop in nearly three decades.\n\nHe framed the review as an attempt to frighten Indonesia, emphasizing the country's strength and resolve amid fears of capital outflows. Officials insist ongoing reforms for better governance and liquidity continue independently, while MSCI awaits sustained improvements before a mid-2027 decision.", "body_zh": "在一次大胆的电视内阁会议上，总统普拉博沃·苏比安托（ Prabowo Subianto ）盯着全球指数提供商MSCI ，宣布他的国家“不害怕任何人，也不会受到恐吓”。\n\n由于对市场透明度和交易的担忧， MSCI考虑将印尼从新兴市场转变为独立市场，此前10月15日宣布股价暴跌11% ，这是近三十年来最大的单日跌幅。\n\n他认为这次审查是为了吓唬印度尼西亚，强调该国在担心资本外流的情况下的实力和决心。官员们坚持认为，为改善治理和流动性而正在进行的改革将继续独立进行，而MSCI在2027年中期做出决定之前仍在等待持续改善。"}, {"id": "2112936645607493653", "domain": "商业", "url": "https://x.com/i/trending/2112936645607493653", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-21T18:51:29.000Z", "title_en": "Alphabet Shares Break Key Support, Slide Below 200-Day Average", "title_zh": "Alphabet股价突破关键支持，跌破200天平均水平", "hook_en": "Alphabet's stock dipped below its 200-day moving average Tuesday, ending a 100-day triangle pattern while the broader market climbed higher.", "hook_zh": "Alphabet股价周二跌破200天移动平均线，结束了100天三角形格局，而大盘则攀升。", "summary_en": "GOOGL traded near $334, down 1.7% and extending a pullback from highs above $340, as traders noted the breakdown left bulls needing to regroup. Some saw the weakness as a buying chance, with investors like Cole starting long-term positions around $331.70 targeting $400-plus, amid mixed options activity and constructive analyst views like Truist's $420 target tied to growth in Search, YouTube, and Cloud. Earnings arrive October 28, with attention on whether the drop signals jitters or deeper issues ahead of results.", "summary_zh": "GOOGL在$ 334附近交易，下跌1.7% ，并从$ 340以上的高点回调，因为交易员注意到崩盘使得多头需要重组。一些人认为这种疲软是一个买入机会，像Cole这样的投资者在$ 331.70左右开始长期持仓，目标为$ 400 + ，其中期权活动和建设性分析师观点好坏参半，例如Truist的$ 420目标与搜索、YouTube和云的增长有关。 收入将在10月28日到账，届时会关注收入下降是否预示着在结果之前会出现紧张或更深层次的问题。", "body_en": "Alphabet Shares Break Key Support, Slide Below 200-Day Average.\n\nAlphabet's stock dipped below its 200-day moving average Tuesday, ending a 100-day triangle pattern while the broader market climbed higher.\n\nGOOGL traded near $334, down 1.7% and extending a pullback from highs above $340, as traders noted the breakdown left bulls needing to regroup.\n\nSome saw the weakness as a buying chance, with investors like Cole starting long-term positions around $331.70 targeting $400-plus, amid mixed options activity and constructive analyst views like Truist's $420 target tied to growth in Search, YouTube, and Cloud. Earnings arrive October 28, with attention on whether the drop signals jitters or deeper issues ahead of results.", "body_zh": "Alphabet股价周二跌破200天移动平均线，结束了100天三角形格局，而大盘则攀升。\n\nGOOGL在$ 334附近交易，下跌1.7% ，并从$ 340以上的高点回调，因为交易员注意到崩盘使得多头需要重组。\n\n一些人认为这种疲软是一个买入机会，像Cole这样的投资者在$ 331.70左右开始长期持仓，目标为$ 400 + ，其中期权活动和建设性分析师观点好坏参半，例如Truist的$ 420目标与搜索、YouTube和云的增长有关。收入将在10月28日到账，届时会关注收入下降是否预示着在结果之前会出现紧张或更深层次的问题。"}, {"id": "2112915461406957899", "domain": "商业", "url": "https://x.com/i/trending/2112915461406957899", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T18:35:48.000Z", "title_en": "Indian Markets Dip Despite Heavy Institutional Buying", "title_zh": "尽管机构购买量很大，但印度市场仍在下跌", "hook_en": "Institutions poured in over ₹2,600 crore, yet the Nifty and Sensex still closed lower. Traders scratched their heads, asking 'Who sold?'", "hook_zh": "机构涌入超过2600亿₹ ，但Nifty和Sensex的收盘价仍然较低。交易员挠了挠头，问道： “谁卖的？”", "summary_en": "On October 21, 2026, FIIs net bought ₹1,022 crore and DIIs added ₹1,614 crore, but the Nifty 50 fell 0.34% to 22,811.35 and Sensex dropped 0.19% to 73,709.69 after an early surge reversed into heavy selling. Market breadth turned negative across segments, with observers pointing to possible retail profit-booking, rising crude oil above $110 a barrel, or unwinding MTF positions amid the Jio Platforms IPO launch. The day highlighted how retail flows and external pressures can outweigh institutional support in a single session.", "summary_zh": "2026年10月21日， FIIS净买入₹ 1,022亿卢比， DIIS增加了₹ 1,614亿卢比，但Nifty 50下跌0.34%至22,811.35 ， Sensex下跌0.19%至73,709.69 ，此前一轮激增逆转为大幅抛售。各细分市场的市场广度转为负面，观察人士指出，在Jio Platforms首次公开募股期间，可能出现零售利润预订、原油价格上涨至每桶110 $以上，或MTF头寸平仓。 这一天突出了零售流量和外部压力如何在一次会议中超过机构支持。", "body_en": "Indian Markets Dip Despite Heavy Institutional Buying.\n\nInstitutions poured in over ₹2,600 crore, yet the Nifty and Sensex still closed lower. Traders scratched their heads, asking 'Who sold?'\n\nOn October 21, 2026, FIIs net bought ₹1,022 crore and DIIs added ₹1,614 crore, but the Nifty 50 fell 0.34% to 22,811.35 and Sensex dropped 0.19% to 73,709.69 after an early surge reversed into heavy selling.\n\nMarket breadth turned negative across segments, with observers pointing to possible retail profit-booking, rising crude oil above $110 a barrel, or unwinding MTF positions amid the Jio Platforms IPO launch. The day highlighted how retail flows and external pressures can outweigh institutional support in a single session.", "body_zh": "机构涌入超过2600亿₹ ，但Nifty和Sensex的收盘价仍然较低。交易员挠了挠头，问道： “谁卖的？”\n\n2026年10月21日， FIIS净买入₹ 1,022亿卢比， DIIS增加了₹ 1,614亿卢比，但Nifty 50下跌0.34%至22,811.35 ， Sensex下跌0.19%至73,709.69 ，此前一轮激增逆转为大幅抛售。\n\n各细分市场的市场广度转为负面，观察人士指出，在Jio Platforms首次公开募股期间，可能出现零售利润预订、原油价格上涨至每桶110 $以上，或MTF头寸平仓。这一天突出了零售流量和外部压力如何在一次会议中超过机构支持。"}, {"id": "2112948932623978868", "domain": "商业", "url": "https://x.com/i/trending/2112948932623978868", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T16:58:30.000Z", "title_en": "India's Core Industries Hit 30-Month High with 7.9% Growth in September 2026", "title_zh": "印度核心产业在2026年9月创下30个月新高，增长7.9%", "hook_en": "India's factories and mines powered up in September, delivering their strongest output in over two years.", "hook_zh": "印度的工厂和矿山在9月份上电，实现了两年来最强劲的产量。", "summary_en": "Core industries grew 7.9% year-on-year, up from a revised 5.9% in August, with the index reaching 118.3. Iron ore led with an 18.4% surge, followed by electricity at 11.4%, coal at 10.7%, refinery products at 10.3%, cement at 9.8%, and steel at 4.9%. While fertiliser dropped 11.7%, natural gas fell 4.6%, and crude oil declined 1.4%, the overall April-September growth hit 5.1%, more than double last year's pace. This rebound signals building industrial strength ahead of broader production data.", "summary_zh": "核心产业同比增长7.9% ，高于8月份修订后的5.9% ，指数达到118.3。铁矿石激增18.4% ，其次是电力11.4% ，煤炭10.7% ，炼油产品10.3% ，水泥9.8% ，钢铁4.9%。虽然化肥下降了11.7% ，天然气下降了4.6% ，原油下降了1.4% ，但4月至9月的整体增长率达到了5.1% ，是去年的两倍多。 这一反弹标志着在更广泛的生产数据之前建立了工业实力。", "body_en": "India's Core Industries Hit 30-Month High with 7.9% Growth in September 2026.\n\nIndia's factories and mines powered up in September, delivering their strongest output in over two years.\n\nCore industries grew 7.9% year-on-year, up from a revised 5.9% in August, with the index reaching 118.3. Iron ore led with an 18.4% surge, followed by electricity at 11.4%, coal at 10.7%, refinery products at 10.3%, cement at 9.8%, and steel at 4.9%.\n\nWhile fertiliser dropped 11.7%, natural gas fell 4.6%, and crude oil declined 1.4%, the overall April-September growth hit 5.1%, more than double last year's pace. This rebound signals building industrial strength ahead of broader production data.", "body_zh": "印度的工厂和矿山在9月份上电，实现了两年来最强劲的产量。\n\n核心产业同比增长7.9% ，高于8月份修订后的5.9% ，指数达到118.3。铁矿石激增18.4% ，其次是电力11.4% ，煤炭10.7% ，炼油产品10.3% ，水泥9.8% ，钢铁4.9%。\n\n虽然化肥下降了11.7% ，天然气下降了4.6% ，原油下降了1.4% ，但4月至9月的整体增长率达到了5.1% ，是去年的两倍多。这一反弹标志着在更广泛的生产数据之前建立了工业实力。"}, {"id": "2112948933332754479", "domain": "商业", "url": "https://x.com/i/trending/2112948933332754479", "category": "News", "topics": ["Business & Finance", "Cryptocurrency"], "updated_at": "2026-10-21T16:57:21.000Z", "title_en": "Tokenized Equity Products Double to Over 360 This Year", "title_zh": "今年代币化股票产品翻一番，超过360种", "hook_en": "Investors now trade stock exposure around the clock on blockchain, breaking free from traditional market hours. This surge opens equities to evenings, weekends, and holidays like never before.", "hook_zh": "投资者现在在区块链上全天候交易股票敞口，摆脱传统的市场时间。这种激增为晚上、周末和假期带来了前所未有的股票。", "summary_en": "Tokenized equity products on blockchain have more than doubled to over 360 this year, with total value hitting $3.8 billion in early October—up 483% from January. About 60% of trading volume happens outside regular sessions, fueled by platforms like Solana's Jupiter, which saw a 215% jump in trades last quarter. Ten products exceed $100 million in supply, drawing in new users via issuers like Binance’s bStocks, while enabling DeFi features such as lending and perpetual futures that brokerages lack.", "summary_zh": "今年，区块链上的代币化股票产品翻了一番多，达到360多种， 10月初的总价值达到38亿美元，比1月份增加了483%。大约60%的交易量发生在常规交易日之外，这得益于Solana的Jupiter等平台，该平台上个季度的交易量增长了215%。 十种产品的供应量超过1亿美元，通过币安的bStocks等发行商吸引了新用户，同时启用了DeFi功能，如经纪商缺乏的贷款和永续期货。", "body_en": "Tokenized Equity Products Double to Over 360 This Year.\n\nInvestors now trade stock exposure around the clock on blockchain, breaking free from traditional market hours. This surge opens equities to evenings, weekends, and holidays like never before.\n\nTokenized equity products on blockchain have more than doubled to over 360 this year, with total value hitting $3.8 billion in early October—up 483% from January.\n\nAbout 60% of trading volume happens outside regular sessions, fueled by platforms like Solana's Jupiter, which saw a 215% jump in trades last quarter. Ten products exceed $100 million in supply, drawing in new users via issuers like Binance’s bStocks, while enabling DeFi features such as lending and perpetual futures that brokerages lack.", "body_zh": "投资者现在在区块链上全天候交易股票敞口，摆脱传统的市场时间。这种激增为晚上、周末和假期带来了前所未有的股票。\n\n今年，区块链上的代币化股票产品翻了一番多，达到360多种， 10月初的总价值达到38亿美元，比1月份增加了483%。\n\n大约60%的交易量发生在常规交易日之外，这得益于Solana的Jupiter等平台，该平台上个季度的交易量增长了215%。十种产品的供应量超过1亿美元，通过币安的bStocks等发行商吸引了新用户，同时启用了DeFi功能，如经纪商缺乏的贷款和永续期货。"}, {"id": "2112908300035776814", "domain": "商业", "url": "https://x.com/i/trending/2112908300035776814", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T16:44:49.000Z", "title_en": "Micron and Nvidia Drive 36% of S&P 500 Earnings Growth", "title_zh": "美光与英伟达贡献标普 500 盈利增长的 36%", "hook_en": "Two tech giants are carrying the S&P 500's earnings on their shoulders, with the rest of the market trailing far behind.", "hook_zh": "两家科技巨头扛起标普 500 盈利增长大梁，其余公司远远落后。", "summary_en": "For Q3 2026, Micron Technology and Nvidia are projected to fuel 36% of the index's 27% year-over-year earnings growth, contributing 5.2 and 4.6 percentage points respectively. The top 15 stocks now hold 46.7% of the S&P 500's market value—far exceeding dot-com bubble levels—with Nvidia, Apple, Alphabet, and Microsoft alone making up over a quarter. Without the top 10 contributors, earnings would shrink 11% year over year, highlighting heavy reliance on AI-linked firms amid surging memory demand from training, inference, and emerging applications like robotaxis. Micron's stock has surged over 340% in the past year as investors eye its AI roadmap.", "summary_zh": "预计 2026 年三季度，美光科技与英伟达将贡献该指数同比 27% 盈利增长中的 36%，分别贡献 5.2 与 4.6 个百分点。市值最大的 15 只股票已占标普 500 总市值的 46.7%——远超互联网泡沫时期水平——仅英伟达、苹果、Alphabet 与微软就占逾四分之一。若剔除前十大贡献者，盈利将同比萎缩 11%，凸显对 AI 相关公司的高度依赖，以及训练、推理与 Robotaxi 等新兴应用带动的存储需求。过去一年美光股价已飙升逾 340%，投资者押注其 AI 路线图。", "body_en": "Micron and Nvidia Drive 36% of S&P 500 Earnings Growth.\n\nTwo tech giants are carrying the S&P 500's earnings on their shoulders, with the rest of the market trailing far behind.\n\nFor Q3 2026, Micron Technology and Nvidia are projected to fuel 36% of the index's 27% year-over-year earnings growth, contributing 5.2 and 4.6 percentage points respectively. The top 15 stocks now hold 46.7% of the S&P 500's market value—far exceeding dot-com bubble levels—with Nvidia, Apple, Alphabet, and Microsoft alone making up over a quarter.\n\nWithout the top 10 contributors, earnings would shrink 11% year over year, highlighting heavy reliance on AI-linked firms amid surging memory demand from training, inference, and emerging applications like robotaxis. Micron's stock has surged over 340% in the past year as investors eye its AI roadmap.", "body_zh": "美光与英伟达贡献标普 500 盈利增长的 36%。\n\n两家科技巨头扛起标普 500 盈利增长大梁，其余公司远远落后。\n\n预计 2026 年三季度，美光科技与英伟达将贡献该指数同比 27% 盈利增长中的 36%，分别贡献 5.2 与 4.6 个百分点。市值最大的 15 只股票已占标普 500 总市值的 46.7%——远超互联网泡沫时期水平——仅英伟达、苹果、Alphabet 与微软就占逾四分之一。\n\n若剔除前十大贡献者，盈利将同比萎缩 11%，凸显对 AI 相关公司的高度依赖，以及训练、推理与 Robotaxi 等新兴应用带动的存储需求。过去一年美光股价已飙升逾 340%，投资者押注其 AI 路线图。"}, {"id": "2112319265076367697", "domain": "商业", "url": "https://x.com/i/trending/2112319265076367697", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T16:35:07.000Z", "title_en": "Jio Platforms IPO Fully Subscribed in 100 Minutes on Opening Day", "title_zh": "Jio Platforms IPO在开幕当天100分钟内全额认购", "hook_en": "Reliance Industries' massive Jio Platforms IPO hit full subscription in just 100 minutes, with bids pouring in from institutions and employees alike.", "hook_zh": "Reliance Industries的大规模Jio Platforms IPO在短短100分钟内就达到了全额认购，机构和员工都纷纷投标。", "summary_en": "The ₹30,213 crore offering opened October 21 at ₹1,065-₹1,119 per share, aiming to repay up to ₹27,500 crore in Jio telecom debt while boosting employee morale through early salary advances for 4.2 lakh staff. Qualified institutional buyers led the charge, oversubscribing their quota early and pushing overall demand to three times by day's end. Zerodha's Nithin Kamath credited Jio's affordable data for bringing millions online and growing India's investor base from 2 crore in 2016 to over 13 crore today, marking this as the largest and fastest-subscribed IPO in recent history.", "summary_zh": "₹ 30,213亿卢比的发行于10月21日开始，每股₹ 1,065- ₹ 1,119 ，旨在偿还高达₹ 27,500亿卢比的Jio电信债务，同时通过预支420万员工的早期工资来提高员工士气。合格的机构买家带头收费，提前超额认购配额，并将总需求量推高至当天的三倍。 Zerodha的Nithin Kamath认为， Jio经济实惠的数据使数百万人上网，印度的投资者基础从2016年的2亿卢比增长到今天的逾13亿卢比，这标志着这是近期历史上规模最大、认购速度最快的IPO。", "body_en": "Jio Platforms IPO Fully Subscribed in 100 Minutes on Opening Day.\n\nReliance Industries' massive Jio Platforms IPO hit full subscription in just 100 minutes, with bids pouring in from institutions and employees alike.\n\nThe ₹30,213 crore offering opened October 21 at ₹1,065-₹1,119 per share, aiming to repay up to ₹27,500 crore in Jio telecom debt while boosting employee morale through early salary advances for 4.2 lakh staff.\n\nQualified institutional buyers led the charge, oversubscribing their quota early and pushing overall demand to three times by day's end. Zerodha's Nithin Kamath credited Jio's affordable data for bringing millions online and growing India's investor base from 2 crore in 2016 to over 13 crore today, marking this as the largest and fastest-subscribed IPO in recent history.", "body_zh": "Reliance Industries的大规模Jio Platforms IPO在短短100分钟内就达到了全额认购，机构和员工都纷纷投标。\n\n₹ 30,213亿卢比的发行于10月21日开始，每股₹ 1,065- ₹ 1,119 ，旨在偿还高达₹ 27,500亿卢比的Jio电信债务，同时通过预支420万员工的早期工资来提高员工士气。\n\n合格的机构买家带头收费，提前超额认购配额，并将总需求量推高至当天的三倍。Zerodha的Nithin Kamath认为， Jio经济实惠的数据使数百万人上网，印度的投资者基础从2016年的2亿卢比增长到今天的逾13亿卢比，这标志着这是近期历史上规模最大、认购速度最快的IPO。"}, {"id": "2112795004678676841", "domain": "商业", "url": "https://x.com/i/trending/2112795004678676841", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T13:45:53.000Z", "title_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister", "title_zh": "印度中小盘暴跌，市场怒火指向财长", "hook_en": "Investors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.", "hook_zh": "2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。", "summary_en": "The Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking. Social media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "summary_zh": "Nifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "body_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister.\n\nInvestors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.\n\nThe Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking.\n\nSocial media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "body_zh": "印度中小盘暴跌，市场怒火指向财长。\n\n2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。\n\nNifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。\n\n小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。"}, {"id": "2112781652112064634", "domain": "商业", "url": "https://x.com/i/trending/2112781652112064634", "category": "News", "topics": ["Business & Finance", "Cryptocurrency"], "updated_at": "2026-10-21T08:28:42.000Z", "title_en": "BNB Standard Rings Nasdaq Bell After Rebrand and New CEO", "title_zh": "BNB Standard在品牌重塑和新任首席执行官之后响起纳斯达克钟声", "hook_en": "On October 26, BNB Standard Corporation will ring the Nasdaq Opening Bell in Times Square, with CEO Alex Odagiu leading the ceremony alongside executives and partners. Binance co-founder CZ marked the moment with double bell emojis.", "hook_zh": "10月26日， BNB Standard Corporation将在时代广场敲响纳斯达克开盘钟，首席执行官Alex Odagiu将与高管和合作伙伴一起主持仪式。币安联合创始人CZ用双铃表情符号标志着这一时刻。", "summary_en": "The Nasdaq-listed company, ticker $BNC, shifted from CEA Industries to focus on its massive BNB treasury, the world's largest corporate holding, after community votes chose the 'BNB Standard' name with 47% support from nearly 5,800 X polls. New CEO Alex Odagiu, with Goldman Sachs background, started October 19, as BNB Chain burned 1.6 million BNB worth $1.2 billion to cut supply toward 100 million. BNB Standard plans its own validator node on BNB Chain, bridging traditional finance and crypto after raising $500 million in its 2025 pivot.", "summary_zh": "这家在纳斯达克上市的公司股票代码为$ BNC ，在社区投票选择了“BNB Standard”名称后，从CEA Industries转向专注于其庞大的BNB金库，这是全球最大的公司控股公司，该公司在近5800项X民意调查中获得了47%的支持。新任首席执行官亚历克斯·奥达吉乌（ Alex Odagiu ）拥有高盛（ Goldman Sachs ）的背景，于10月19日开始， BNB Chain烧毁了160万BNB ，价值12亿美元，将供应量削减至1亿。 BNB标准计划在BNB Chain上建立自己的验证器节点，在2025年的支点上筹集了5亿美元后，将传统金融和加密桥接起来。", "body_en": "On October 26, BNB Standard Corporation will ring the Nasdaq Opening Bell in Times Square, with CEO Alex Odagiu leading the ceremony alongside executives and partners. Binance co-founder CZ marked the moment with double bell emojis.\n\nThe Nasdaq-listed company, ticker $BNC, shifted from CEA Industries to focus on its massive BNB treasury, the world's largest corporate holding, after community votes chose the 'BNB Standard' name with 47% support from nearly 5,800 X polls.\n\nNew CEO Alex Odagiu, with Goldman Sachs background, started October 19, as BNB Chain burned 1.6 million BNB worth $1.2 billion to cut supply toward 100 million. BNB Standard plans its own validator node on BNB Chain, bridging traditional finance and crypto after raising $500 million in its 2025 pivot.", "body_zh": "10月26日， BNB Standard Corporation将在时代广场敲响纳斯达克开盘钟，首席执行官Alex Odagiu将与高管和合作伙伴一起主持仪式。币安联合创始人CZ用双铃表情符号标志着这一时刻。\n\n这家在纳斯达克上市的公司股票代码为$ BNC ，在社区投票选择了“BNB Standard”名称后，从CEA Industries转向专注于其庞大的BNB金库，这是全球最大的公司控股公司，该公司在近5800项X民意调查中获得了47%的支持。\n\n新任首席执行官亚历克斯·奥达吉乌（ Alex Odagiu ）拥有高盛（ Goldman Sachs ）的背景，于10月19日开始， BNB Chain烧毁了160万BNB ，价值12亿美元，将供应量削减至1亿。BNB标准计划在BNB Chain上建立自己的验证器节点，在2025年的支点上筹集了5亿美元后，将传统金融和加密桥接起来。"}, {"id": "2112796521959985524", "domain": "商业", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。"}, {"id": "2112795003680342391", "domain": "商业", "url": "https://x.com/i/trending/2112795003680342391", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-21T06:39:54.000Z", "title_en": "S&P 500's Top 15 Stocks Hit Record 46.7% Share", "title_zh": "标准普尔500指数前15大股票创下46.7%的份额纪录", "hook_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.", "hook_zh": "少数科技巨头现在掌控着整个标准普尔500指数，仅英伟达就占该指数价值的7.5%。广义基金的日常投资者可能没有意识到他们对这些领导者的依赖程度。", "summary_en": "The 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%. The top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "summary_zh": "15只最大的标准普尔500指数股票占该指数总市值的46.7% ，创下历史新高，远远超过2000年互联网泡沫高峰时的27.2%。英伟达以7.5%位居榜首，其次是苹果7.1% ， Alphabet 5.9% ，微软5.6% ，仅这四家就占26.1%。前五名的市值等于底部434家公司的市值，促使市场观察人士质疑热门指数基金和ETF的多元化。 虽然有些人强调了领导者的强劲现金流，但其他人则指出，任何放缓都可能对被动投资组合造成严重打击。", "body_en": "A handful of tech giants now steer the entire S&P 500, with Nvidia alone claiming 7.5% of the index's value. Everyday investors in broad funds might not realize how much they're riding on these leaders.\n\nThe 15 largest S&P 500 stocks account for a record 46.7% of the index's total market value, far exceeding the 27.2% seen at the 2000 dot-com peak. Nvidia tops the list at 7.5%, followed by Apple at 7.1%, Alphabet at 5.9%, and Microsoft at 5.6%, with these four alone making up 26.1%.\n\nThe top five equal the market cap of the bottom 434 companies, prompting market watchers to question diversification in popular index funds and ETFs. While some highlight the leaders' strong cash flows, others note that any slowdown could hit passive portfolios hard.", "body_zh": "少数科技巨头现在掌控着整个标准普尔500指数，仅英伟达就占该指数价值的7.5%。广义基金的日常投资者可能没有意识到他们对这些领导者的依赖程度。\n\n15只最大的标准普尔500指数股票占该指数总市值的46.7% ，创下历史新高，远远超过2000年互联网泡沫高峰时的27.2%。英伟达以7.5%位居榜首，其次是苹果7.1% ， Alphabet 5.9% ，微软5.6% ，仅这四家就占26.1%。\n\n前五名的市值等于底部434家公司的市值，促使市场观察人士质疑热门指数基金和ETF的多元化。虽然有些人强调了领导者的强劲现金流，但其他人则指出，任何放缓都可能对被动投资组合造成严重打击。"}, {"id": "2112188369618784335", "domain": "中国", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:44:28.000Z", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国国土安全部令联邦机构清除 DeepSeek AI 产品", "hook_en": "The U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.", "hook_zh": "美国国土安全部划下红线：以数据流向中国与潜在安全风险为由，要求联邦系统清除中国 AI 工具。", "summary_en": "Under a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services. The order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "summary_zh": "根据2026年10月20日的新联邦公报通知，国土安全部指示民事联邦机构停止从杭州DeepSeek人工智能公司采购，并删除其所有产品，包括嵌入第三方服务的产品。该命令强调了中国法律规定的敏感数据传输、个人信息收集以及模型中潜在的恶意软件等危险。 DeepSeek以高效的开放式重量级人工智能模型而闻名，这些模型在中等硬件上运行良好，但由于美国对中国技术的更广泛限制， DeepSeek现在面临这些限制，尽管国防和情报系统仍然受到单独监管。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nThe U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.\n\nUnder a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services.\n\nThe order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "body_zh": "美国国土安全部划下红线：以数据流向中国与潜在安全风险为由，要求联邦系统清除中国 AI 工具。\n\n根据2026年10月20日的新联邦公报通知，国土安全部指示民事联邦机构停止从杭州DeepSeek人工智能公司采购，并删除其所有产品，包括嵌入第三方服务的产品。\n\n该命令强调了中国法律规定的敏感数据传输、个人信息收集以及模型中潜在的恶意软件等危险。DeepSeek以高效的开放式重量级人工智能模型而闻名，这些模型在中等硬件上运行良好，但由于美国对中国技术的更广泛限制， DeepSeek现在面临这些限制，尽管国防和情报系统仍然受到单独监管。"}, {"id": "2112810342728323293", "domain": "中国", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T10:44:04.000Z", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。"}, {"id": "2112405151768100963", "domain": "中国", "url": "https://x.com/i/trending/2112405151768100963", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T10:24:16.000Z", "title_en": "Philippine Senators Push to Expel Chinese Ambassador Over Sea Threat", "title_zh": "菲律宾参议员推动驱逐中国大使", "hook_en": "Chinese Ambassador Jing Quan's words hung heavy: China could 'easily win' with force in the West Philippine Sea, though it prefers peace. Philippine senators fired back, demanding he be sent home.", "hook_zh": "中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。", "summary_en": "Senators Risa Hontiveros and Erwin Tulfo filed resolutions urging President Marcos to declare Ambassador Jing persona non grata after his remarks, seen as a veiled threat amid China's vessel harassment and illegal fishing in Philippine waters. The Department of Foreign Affairs summoned Jing to protest, while Senator Kiko Pangilinan sharply challenged Marcos to act decisively. The Chinese Embassy hit back by listing critical lawmakers online, but Malacañang favors diplomatic channels over expulsion to avoid escalation.", "summary_zh": "参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。", "body_en": "Chinese Ambassador Jing Quan boasted that China could 'easily win' any conflict with the Philippines, igniting calls from senators to send him packing.\n\nSenators Risa Hontiveros and Erwin Tulfo filed resolutions on October 20 and the day before, urging President Marcos to declare Ambassador Jing persona non grata or request his recall from Beijing. The remarks responded to Defense Secretary Gilberto Teodoro Jr.\n\nlabeling China a regional troublemaker, prompting the Chinese Embassy's taunting social media posts like 'You are now on the list' targeting critics. The Department of Foreign Affairs summoned Jing on October 19, calling his words a provocative threat amid ongoing West Philippine Sea tensions, though Marcos prefers diplomatic talks over expulsion.", "body_zh": "菲律宾参议员推动驱逐中国大使。中国大使景泉称中国可「轻松打赢」与菲冲突，引发参议员要求将其驱逐。\n\n参议员洪蒂维罗斯与图尔福于 10 月 20 日前后提交决议，敦促马科斯总统宣布大使为不受欢迎人士或要求北京召回。言论回应菲防长称中国为地区麻烦制造者，中国使馆随后在社媒发出「你已上榜」等嘲讽帖。\n\n外交部 10 月 19 日召见景泉，称其言论具挑衅性；马科斯更倾向外交沟通而非驱逐。\n\n以上内容根据公开讨论与报道梳理，详情可在 X 原文页继续跟踪进展。"}, {"id": "2112820742060495085", "domain": "中国", "url": "https://x.com/i/trending/2112820742060495085", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T08:24:00.000Z", "title_en": "Rizhao Residents Watch Rocket Launch from Home Windows", "title_zh": "日照市民在家门口「看火箭」升空", "hook_en": "People in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.", "hook_zh": "中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。", "summary_en": "On October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit. The satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "summary_zh": "2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "body_en": "Rizhao Residents Watch Rocket Launch from Home Windows.\n\nPeople in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.\n\nOn October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit.\n\nThe satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "body_zh": "日照市民在家门口「看火箭」升空。\n\n中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。\n\n2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。\n\n卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。"}, {"id": "2112653366941950015", "domain": "中国", "url": "https://x.com/i/trending/2112653366941950015", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T21:21:21.000Z", "title_en": "China's 'Fake Commuting' Hides Unemployment from Families", "title_zh": "中国出现“假装上班”：失业者用作息瞒住家人", "hook_en": "A jobless worker waves goodbye each morning, 'Bye, I'm off to work,' then heads straight to the bar. This daily pretense is spreading amid China's tough job market.", "hook_zh": "有人每天挥手说“我去上班了”，却径直去酒吧——在就业承压背景下，这类掩饰正被更多讨论。", "summary_en": "Unemployed people in China are leaving home on work-like schedules to keep families from knowing they're jobless, driven by a weak hiring environment, property crisis, automation, and AI adoption. Social platforms buzz with tips on filling the day in cafes, parks, or libraries, echoing the shame in the 2008 Japanese film Tokyo Sonata and similar habits elsewhere. The trend underscores cultural stigma around unemployment and efforts to preserve family harmony despite economic pressures.", "summary_zh": "部分失业者按上班时间出门，以免家人知晓，背后是招聘偏弱、房地产调整、自动化与 AI 应用等因素。社交平台流传在咖啡馆、公园、图书馆消磨白天的经验，令人联想到日本电影《东京奏鸣曲》中的耻辱感。现象折射失业污名与家庭体面压力，也引发对就业与社会保障的讨论。", "body_en": "China's 'Fake Commuting' Hides Unemployment from Families.\n\nA jobless worker waves goodbye each morning, 'Bye, I'm off to work,' then heads straight to the bar. This daily pretense is spreading amid China's tough job market.\n\nUnemployed people in China are leaving home on work-like schedules to keep families from knowing they're jobless, driven by a weak hiring environment, property crisis, automation, and AI adoption.\n\nSocial platforms buzz with tips on filling the day in cafes, parks, or libraries, echoing the shame in the 2008 Japanese film Tokyo Sonata and similar habits elsewhere. The trend underscores cultural stigma around unemployment and efforts to preserve family harmony despite economic pressures.", "body_zh": "中国出现“假装上班”：失业者用作息瞒住家人。\n\n有人每天挥手说“我去上班了”，却径直去酒吧——在就业承压背景下，这类掩饰正被更多讨论。\n\n部分失业者按上班时间出门，以免家人知晓，背后是招聘偏弱、房地产调整、自动化与 AI 应用等因素。\n\n社交平台流传在咖啡馆、公园、图书馆消磨白天的经验，令人联想到日本电影《东京奏鸣曲》中的耻辱感。现象折射失业污名与家庭体面压力，也引发对就业与社会保障的讨论。"}, {"id": "2112161836116132305", "domain": "中国", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。"}, {"id": "2112572571275370804", "domain": "中国", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。"}, {"id": "2112595601669919101", "domain": "中国", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。Samuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持。\n\nOpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。\n\n去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。\n\nSamuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。"}, {"id": "2112575525655081471", "domain": "中国", "url": "https://x.com/i/trending/2112575525655081471", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T16:14:33.000Z", "title_en": "Bipartisan Ex-Officials Push Energy Permitting Reform to Counter China", "title_zh": "两党前官员推动能源许可改革以对抗中国", "hook_en": "Nineteen top officials from both parties, including Janet Yellen and Mike Pompeo, joined forces in a letter warning that slow U.S. infrastructure builds risk losing ground to China.", "hook_zh": "包括珍妮特·耶伦(Janet Yellen)和迈克·蓬佩奥(Mike Pompeo)在内的19名来自两党的高级官员联手发出一封信，警告说，美国基础设施建设的缓慢可能会让中国", "summary_en": "The group, spanning Clinton to Biden administrations, sent the letter to congressional leaders urging passage of the Bipartisan American Affordability and Jobs Act to speed up energy project permitting. They highlight how U.S. power plant timelines have doubled to over four years, while China has built more high-voltage transmission in 15 years than America has in its history, and now leads in tech manufacturing. The reform would streamline transmission planning, grid connections, and litigation while keeping community input, aiming to boost sectors like AI and semiconductors amid rising electricity demand.", "summary_zh": "该组织跨越克林顿和拜登政府，向国会领导人发出信件，敦促通过两党的“美国负担能力和就业法案” ，以加快能源项目的许可。他们强调了美国发电厂的时间表在四年内翻了一番，而中国在15年内建造了比美国历史上更多的高压输电，现在在科技制造业中处于领先地位。 这项改革将简化传输规划、电网连接和诉讼，同时保持社区投入，旨在在不断增长的电力需求中促进人工智能和半导体等行业的发展。", "body_en": "Bipartisan Ex-Officials Push Energy Permitting Reform to Counter China.\n\nNineteen top officials from both parties, including Janet Yellen and Mike Pompeo, joined forces in a letter warning that slow U.S. infrastructure builds risk losing ground to China.\n\nThe group, spanning Clinton to Biden administrations, sent the letter to congressional leaders urging passage of the Bipartisan American Affordability and Jobs Act to speed up energy project permitting. They highlight how U.S.\n\npower plant timelines have doubled to over four years, while China has built more high-voltage transmission in 15 years than America has in its history, and now leads in tech manufacturing. The reform would streamline transmission planning, grid connections, and litigation while keeping community input, aiming to boost sectors like AI and semiconductors amid rising electricity demand.", "body_zh": "包括珍妮特·耶伦(Janet Yellen)和迈克·蓬佩奥(Mike Pompeo)在内的19名来自两党的高级官员联手发出一封信，警告说，美国基础设施建设的缓慢可能会让中国\n\n该组织跨越克林顿和拜登政府，向国会领导人发出信件，敦促通过两党的“美国负担能力和就业法案” ，以加快能源项目的许可。\n\n他们强调了美国发电厂的时间表在四年内翻了一番，而中国在15年内建造了比美国历史上更多的高压输电，现在在科技制造业中处于领先地位。这项改革将简化传输规划、电网连接和诉讼，同时保持社区投入，旨在在不断增长的电力需求中促进人工智能和半导体等行业的发展。"}, {"id": "2112486884211650655", "domain": "中国", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。"}, {"id": "2112533926702936100", "domain": "中国", "url": "https://x.com/i/trending/2112533926702936100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T13:25:56.000Z", "title_en": "China's Philosophers Offer Fresh Take on AI and Humanity", "title_zh": "中国学者从心性与仁爱角度讨论 AI 与人类", "hook_en": "While Western worries center on super-smart machines outpacing us, Chinese thinkers flip the script to protect what makes us truly human.", "hook_zh": "当西方担忧超级智能时，中国思想家更关注如何守护人之为人的品质。", "summary_en": "Arnaud Bertrand's Substack explores how China's philosophers, sociologists, and ethicists view AI through traditions like Confucianism, emphasizing the heart-mind and benevolence over raw intelligence. Thinkers like Liu Yongmou warn against the 'machinization of humans'—technology eroding our inner qualities—while Zhao Tingyang cautions that aligning AI with human values might backfire. Drawing from ancient texts like the Zhuangzi, these ideas challenge Western fears and highlight overlooked questions as China leads in AI development.", "summary_zh": "Arnaud Bertrand的Substack探讨了中国的哲学家、社会学家和伦理学家如何通过儒家思想等传统来看待人工智能，强调心灵和仁慈而不是原始智慧。像刘永谋这样的思想家警告不要“人类机械化” --技术侵蚀我们的内在品质--而赵廷阳则警告说，将人工智能与人类价值观结合起来可能会适得其反。 这些想法借鉴了庄子等古代文献，挑战了西方的恐惧，并强调了随着中国在人工智能发展方面的领先地位而被忽视的问题。", "body_en": "China's Philosophers Offer Fresh Take on AI and Humanity.\n\nWhile Western worries center on super-smart machines outpacing us, Chinese thinkers flip the script to protect what makes us truly human.\n\nArnaud Bertrand's Substack explores how China's philosophers, sociologists, and ethicists view AI through traditions like Confucianism, emphasizing the heart-mind and benevolence over raw intelligence.\n\nThinkers like Liu Yongmou warn against the 'machinization of humans'—technology eroding our inner qualities—while Zhao Tingyang cautions that aligning AI with human values might backfire. Drawing from ancient texts like the Zhuangzi, these ideas challenge Western fears and highlight overlooked questions as China leads in AI development.", "body_zh": "当西方担忧超级智能时，中国思想家更关注如何守护人之为人的品质。\n\nArnaud Bertrand的Substack探讨了中国的哲学家、社会学家和伦理学家如何通过儒家思想等传统来看待人工智能，强调心灵和仁慈而不是原始智慧。\n\n像刘永谋这样的思想家警告不要“人类机械化” --技术侵蚀我们的内在品质--而赵廷阳则警告说，将人工智能与人类价值观结合起来可能会适得其反。这些想法借鉴了庄子等古代文献，挑战了西方的恐惧，并强调了随着中国在人工智能发展方面的领先地位而被忽视的问题。"}, {"id": "2112003183275090362", "domain": "中国", "url": "https://x.com/i/trending/2112003183275090362", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T10:15:42.000Z", "title_en": "China's Economy Grows Faster Than Expected Amid Record Stock Slump", "title_zh": "中国经济增速超预期，股市却创最长连跌", "hook_en": "China's GDP beat forecasts in Q3, offering a bright spot even as stocks hit their longest losing streak ever.", "hook_zh": "三季度 GDP 好于预期，A 股却录得史上最长连跌。", "summary_en": "Official data showed 4.5% year-on-year growth in the third quarter, topping estimates of 4.4% and lifting the first nine months to 4.6%, within Beijing's annual target. Industrial output rose 5.5% in September, retail sales gained 1.1%, and a $133.5 billion trade surplus provided support, driven by tech exports tied to global AI demand. Yet the CSI 300 index fell for 10 straight weeks, its worst streak, as domestic demand stayed soft with property woes and weak consumer spending. Economists see the rebound easing stimulus pressure but question its staying power.", "summary_zh": "官方数据显示三季度同比增长 4.5%，高于 4.4% 预期，前九个月累计 4.6%，仍在年度目标区间。9 月工业增加值增 5.5%，零售增 1.1%，贸易顺差达 1335 亿美元，科技出口受全球 AI 需求拉动。但沪深 300 连续 10 周下跌创纪录，内需偏弱、房地产承压与消费疲软仍在。经济学家认为回暖减轻刺激压力，但持续性仍存疑。", "body_en": "China's Economy Grows Faster Than Expected Amid Record Stock Slump.\n\nChina's GDP beat forecasts in Q3, offering a bright spot even as stocks hit their longest losing streak ever.\n\nOfficial data showed 4.5% year-on-year growth in the third quarter, topping estimates of 4.4% and lifting the first nine months to 4.6%, within Beijing's annual target. Industrial output rose 5.5% in September, retail sales gained 1.1%, and a $133.5 billion trade surplus provided support, driven by tech exports tied to global AI demand.\n\nYet the CSI 300 index fell for 10 straight weeks, its worst streak, as domestic demand stayed soft with property woes and weak consumer spending. Economists see the rebound easing stimulus pressure but question its staying power.", "body_zh": "中国经济增速超预期，股市却创最长连跌。\n\n三季度 GDP 好于预期，A 股却录得史上最长连跌。\n\n官方数据显示三季度同比增长 4.5%，高于 4.4% 预期，前九个月累计 4.6%，仍在年度目标区间。9 月工业增加值增 5.5%，零售增 1.1%，贸易顺差达 1335 亿美元，科技出口受全球 AI 需求拉动。\n\n但沪深 300 连续 10 周下跌创纪录，内需偏弱、房地产承压与消费疲软仍在。经济学家认为回暖减轻刺激压力，但持续性仍存疑。"}, {"id": "2112022699237310708", "domain": "中国", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕，纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，共庆约 5000 年历史的良渚遗址。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛以「连接过去与未来」为主题，纪念入选世界遗产的良渚遗址发现 90 周年。活动包含 AI 导览与文化交流内容，吸引多国学者参与。", "body_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕，纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，共庆约 5000 年历史的良渚遗址。\n\n第四届良渚论坛以「连接过去与未来」为主题，纪念入选世界遗产的良渚遗址发现 90 周年。活动包含 AI 导览与文化交流内容，吸引多国学者参与。"}, {"id": "2112994548645540037", "domain": "国际", "url": "https://x.com/i/trending/2112994548645540037", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:58:43.000Z", "title_en": "National Security Officials Prep States for Potential Trump Midterm Interference", "title_zh": "国家安全官员为潜在的特朗普中期干预做好准备", "hook_en": "A handful of U.S. national security veterans have quietly met with governors and lawmakers in 10 states, discussing worst-case scenarios like military at polls or fraud challenges.", "hook_zh": "少数美国国家安全退伍军人悄悄会见了10个州的州长和立法者，讨论了最坏的情况，如民意调查中的军队或欺诈挑战。", "summary_en": "The Washington Post detailed how about 10 current and former officials, many from the Defense Department, advised bipartisan state and congressional leaders on handling possible federal interference in the November 3 midterms. They focused on precautionary steps amid fears for democratic norms, without partisan motives. Critics labeled it a plot against the administration, while supporters cited January 6 as justification for vigilance; no White House response has surfaced as the debate underscores election tensions.", "summary_zh": "《华盛顿邮报》详细介绍了大约10名现任和前任官员（其中许多来自国防部）如何在11月3日的中期选举中向两党州和国会领导人提出建议，以应对可能的联邦干预。他们专注于预防措施，担心民主规范，没有党派动机。 批评者称这是反对政府的阴谋，而支持者则认为1月6日是保持警惕的理由；随着辩论凸显选举紧张局势，白宫没有做出任何回应。", "body_en": "National Security Officials Prep States for Potential Trump Midterm Interference.\n\nA handful of U.S. national security veterans have quietly met with governors and lawmakers in 10 states, discussing worst-case scenarios like military at polls or fraud challenges.\n\nThe Washington Post detailed how about 10 current and former officials, many from the Defense Department, advised bipartisan state and congressional leaders on handling possible federal interference in the November 3 midterms.\n\nThey focused on precautionary steps amid fears for democratic norms, without partisan motives. Critics labeled it a plot against the administration, while supporters cited January 6 as justification for vigilance; no White House response has surfaced as the debate underscores election tensions.", "body_zh": "少数美国国家安全退伍军人悄悄会见了10个州的州长和立法者，讨论了最坏的情况，如民意调查中的军队或欺诈挑战。\n\n《华盛顿邮报》详细介绍了大约10名现任和前任官员（其中许多来自国防部）如何在11月3日的中期选举中向两党州和国会领导人提出建议，以应对可能的联邦干预。\n\n他们专注于预防措施，担心民主规范，没有党派动机。批评者称这是反对政府的阴谋，而支持者则认为1月6日是保持警惕的理由；随着辩论凸显选举紧张局势，白宫没有做出任何回应。"}, {"id": "2112918022809649254", "domain": "国际", "url": "https://x.com/i/trending/2112918022809649254", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:57:06.000Z", "title_en": "Pentagon Approves Heat Ray Testing for U.S. Border Security", "title_zh": "五角大楼批准为美国边境安全进行热射线测试", "hook_en": "Imagine a beam that feels like a hot oven blast from half a mile away, pushing people back without contact. The Pentagon just greenlit DHS to test this nonlethal device at the southern border.", "hook_zh": "想象一下，一根光束感觉像是半英里外的热炉爆炸，将人们推回去，没有任何接触。五角大楼刚刚为国土安全部开了绿灯，在南部边境测试这种非致命装置。", "summary_en": "Defense Secretary Pete Hegseth signed a memo last month allowing a seven-month loan of the Active Denial System, a directed-energy weapon that creates a burning skin sensation to disperse crowds. DHS will handle all testing and potential use starting in September, with no Pentagon operation involved. Critics like Senator Chris Coons call it troubling for civilians, while supporters see it as key for border protection amid ongoing enforcement debates.", "summary_zh": "国防部长皮特·黑格塞斯（ Pete Hegseth ）上个月签署了一份备忘录，允许主动拒绝系统（ Active Denial System ）提供为期七个月的贷款。主动拒绝系统是一种定向能武器，可产生灼热的皮肤感觉，以驱散人群。国土安全部将从9月开始处理所有测试和潜在用途，不涉及五角大楼的行动。 像参议员克里斯·库恩斯（ Chris Coons ）这样的批评者称，这对平民来说令人不安，而支持者认为，在正在进行的执法辩论中，这是边境保护的关键", "body_en": "Pentagon Approves Heat Ray Testing for U.S. Border Security.\n\nImagine a beam that feels like a hot oven blast from half a mile away, pushing people back without contact. The Pentagon just greenlit DHS to test this nonlethal device at the southern border.\n\nDefense Secretary Pete Hegseth signed a memo last month allowing a seven-month loan of the Active Denial System, a directed-energy weapon that creates a burning skin sensation to disperse crowds.\n\nDHS will handle all testing and potential use starting in September, with no Pentagon operation involved. Critics like Senator Chris Coons call it troubling for civilians, while supporters see it as key for border protection amid ongoing enforcement debates.", "body_zh": "想象一下，一根光束感觉像是半英里外的热炉爆炸，将人们推回去，没有任何接触。五角大楼刚刚为国土安全部开了绿灯，在南部边境测试这种非致命装置。\n\n国防部长皮特·黑格塞斯（ Pete Hegseth ）上个月签署了一份备忘录，允许主动拒绝系统（ Active Denial System ）提供为期七个月的贷款。主动拒绝系统是一种定向能武器，可产生灼热的皮肤感觉，以驱散人群。\n\n国土安全部将从9月开始处理所有测试和潜在用途，不涉及五角大楼的行动。像参议员克里斯·库恩斯（ Chris Coons ）这样的批评者称，这对平民来说令人不安，而支持者认为，在正在进行的执法辩论中，这是边境保护的关键"}, {"id": "2112923062106554755", "domain": "国际", "url": "https://x.com/i/trending/2112923062106554755", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:42:49.000Z", "title_en": "Ruto Announces Tax Cuts and Job Boosts to Ease Kenya's Cost of Living", "title_zh": "Ruto宣布减税和增加就业机会，以缓解肯尼亚的生活成本", "hook_en": "Amid cheers from thousands in colorful attire at Eldoret's Kipchoge Keino Stadium, President Ruto unveiled relief measures to help Kenyans keep more of their hard-earned money.", "hook_zh": "在埃尔多雷特Kipchoge Keino体育场成千上万身着五颜六色服装的欢呼声中，鲁托总统公布了救济措施，以帮助肯尼亚人保留更多辛苦赚来的钱。", "summary_en": "During the 63rd Mashujaa Day celebrations, President William Ruto proposed exempting workers earning KSh 32,333 or less monthly from income tax, scrapping stamp duty on land deals up to KSh 1 million, and dropping import duty on mobile phones to cut costs and open digital doors. He also plans to expand internships to 50,000 youth starting January 2027, while keeping fertilizer subsidies at KSh 2,000 per bag and boosting dairy farmer payments. These steps under the Mapato Zaidi agenda aim to strengthen household budgets and long-term opportunities, with Parliament set to review them next week.", "summary_zh": "在第63届Mashujaa日庆祝活动期间，总统威廉·鲁托（ William Ruto ）提议免除每月收入32,333肯尼亚先令或以下的工人的所得税，取消高达100万肯尼亚先令的土地交易印花税，并取消手机进口税，以降低成本并打开数字门。他还计划从2027年1月开始将实习机会扩大到5万名青年，同时将化肥补贴保持在每袋2,000肯尼亚先令，并提高奶农的薪酬。 Mapato Zaidi议程下的这些步骤旨在加强家庭预算和长期机会，议会将于下周对其进行审查。", "body_en": "Amid cheers from thousands in colorful attire at Eldoret's Kipchoge Keino Stadium, President Ruto unveiled relief measures to help Kenyans keep more of their hard-earned money.\n\nDuring the 63rd Mashujaa Day celebrations, President William Ruto proposed exempting workers earning KSh 32,333 or less monthly from income tax, scrapping stamp duty on land deals up to KSh 1 million, and dropping import duty on mobile phones to cut costs and open digital doors.\n\nHe also plans to expand internships to 50,000 youth starting January 2027, while keeping fertilizer subsidies at KSh 2,000 per bag and boosting dairy farmer payments. These steps under the Mapato Zaidi agenda aim to strengthen household budgets and long-term opportunities, with Parliament set to review them next week.", "body_zh": "在埃尔多雷特Kipchoge Keino体育场成千上万身着五颜六色服装的欢呼声中，鲁托总统公布了救济措施，以帮助肯尼亚人保留更多辛苦赚来的钱。\n\n在第63届Mashujaa日庆祝活动期间，总统威廉·鲁托（ William Ruto ）提议免除每月收入32,333肯尼亚先令或以下的工人的所得税，取消高达100万肯尼亚先令的土地交易印花税，并取消手机进口税，以降低成本并打开数字门。\n\n他还计划从2027年1月开始将实习机会扩大到5万名青年，同时将化肥补贴保持在每袋2,000肯尼亚先令，并提高奶农的薪酬。Mapato Zaidi议程下的这些步骤旨在加强家庭预算和长期机会，议会将于下周对其进行审查。"}, {"id": "2112968038337437761", "domain": "国际", "url": "https://x.com/i/trending/2112968038337437761", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T19:30:32.000Z", "title_en": "Pakistan's Army Chief Delivers U.S. Nuclear Ultimatum to Iran in Tehran", "title_zh": "巴基斯坦陆军参谋长在德黑兰向伊朗递交美国核最后通牒", "hook_en": "Pakistan's army chief Asim Munir walked into Tehran meetings carrying a reported U.S. warning on Iran's nuclear program, only to face a firm rejection from Iranian leaders.", "hook_zh": "巴基斯坦陆军参谋长阿西姆·穆尼尔（ Asim Munir ）带着美国对伊朗核计划的警告走进德黑兰会议，但遭到伊朗领导人的坚决反对。", "summary_en": "During his October 20 visit, Munir met top Iranian officials including President Masoud Pezeshkian and Supreme National Security Council Secretary Mohsen Rezaei, relaying a message that Iran must concede on its nuclear activities or risk attacks on the Pickaxe Mountain site near Natanz. Iran responded by insisting the U.S. first meet its seven conditions, such as lifting sanctions and allowing no enriched nuclear material to leave the country. Pakistani officials described the trip as mediation to ease U.S.-Iran tensions, but Iranian readouts and state media portrayed it as pressure tied to oil prices, with Rezaei declaring not even a gram of material would depart.", "summary_zh": "在10月20日的访问期间，穆尼尔会见了包括总统马苏德·佩泽什基安(Masoud Pezeshkian)和最高国家安全委员会秘书穆赫森·雷扎伊(Mohsen Rezaei)在内的伊朗高级官员，传达了一个信息，即伊朗必须就其核活动做出让步，否则将面临对纳坦兹附近的镐山(Pickaxe伊朗的回应是坚称美国首先满足其七个条件，例如取消制裁和不允许浓缩核材料离开该国。 巴基斯坦官员将这次访问描述为缓解美伊紧张局势的调解，但伊朗读者和官方媒体将其描述为与油价挂钩的压力， Rezaei宣布甚至没有一克材料会离开。", "body_en": "Pakistan's army chief Asim Munir walked into Tehran meetings carrying a reported U.S. warning on Iran's nuclear program, only to face a firm rejection from Iranian leaders.\n\nDuring his October 20 visit, Munir met top Iranian officials including President Masoud Pezeshkian and Supreme National Security Council Secretary Mohsen Rezaei, relaying a message that Iran must concede on its nuclear activities or risk attacks on the Pickaxe Mountain site near Natanz. Iran responded by insisting the U.S.\n\nfirst meet its seven conditions, such as lifting sanctions and allowing no enriched nuclear material to leave the country. Pakistani officials described the trip as mediation to ease U.S.-Iran tensions, but Iranian readouts and state media portrayed it as pressure tied to oil prices, with Rezaei declaring not even a gram of material would depart.", "body_zh": "巴基斯坦陆军参谋长阿西姆·穆尼尔（ Asim Munir ）带着美国对伊朗核计划的警告走进德黑兰会议，但遭到伊朗领导人的坚决反对。\n\n在10月20日的访问期间，穆尼尔会见了包括总统马苏德·佩泽什基安(Masoud Pezeshkian)和最高国家安全委员会秘书穆赫森·雷扎伊(Mohsen Rezaei)在内的伊朗高级官员，传达了一个信息，即伊朗必须就其核活动做出让步，否则将面临对纳坦兹附近的镐山(Pickaxe伊朗的回应是坚称美国首先满足其七个条件，例如取消制裁和不允许浓缩核材料离开该国。 巴基斯坦官员将这次访问描述为缓解美伊紧张局势的调解，但伊朗读者和官方媒体将其描述为与油价挂钩的压力， Rezaei宣布甚至没有一克材料会离开。"}, {"id": "2112946152077430940", "domain": "国际", "url": "https://x.com/i/trending/2112946152077430940", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T19:29:24.000Z", "title_en": "Singapore's PM Wong Visits UAE to Strengthen Trade and Tech Ties", "title_zh": "新加坡总理王岐山访问阿联酋以加强贸易和技术联系", "hook_en": "In Abu Dhabi, Prime Minister Lawrence Wong and President Sheikh Mohamed bin Zayed shared a warm welcome, discussing ways to deepen their nations' partnership amid regional challenges.", "hook_zh": "在阿布扎比，总理劳伦斯·黄（ Lawrence Wong ）和总统谢赫·穆罕默德·本·扎耶德（ Sheikh Mohamed bin Zayed ）表示热烈欢迎，讨论了在区域挑战中深化两国伙伴关系的方法。", "summary_en": "Wong's first official UAE visit as prime minister included high-level talks on expanding cooperation in trade, investment, energy, technology, and education. The leaders agreed to launch negotiations for a Comprehensive Economic Partnership Agreement, building on $6.5 billion in non-oil trade last year, and signed memorandums on energy, water management, and disease control. They also planned a joint energy task force and future meetings on AI, cybersecurity, and space, reaffirming 40 years of diplomatic relations while noting Singapore's solidarity during Middle East tensions.", "summary_zh": "Wong作为总理首次正式访问阿联酋，包括就扩大贸易、投资、能源、技术和教育合作进行高层会谈。双方领导人同意在去年65亿美元非石油贸易的基础上启动全面经济伙伴关系协定的谈判，并签署了关于能源、水资源管理和疾病控制的备忘录。 他们还计划成立一个联合能源工作组，并就人工智能、网络安全和太空举行未来会议，重申了40年的外交关系，同时指出新加坡在中东紧张局势中的团结。", "body_en": "Singapore's PM Wong Visits UAE to Strengthen Trade and Tech Ties.\n\nIn Abu Dhabi, Prime Minister Lawrence Wong and President Sheikh Mohamed bin Zayed shared a warm welcome, discussing ways to deepen their nations' partnership amid regional challenges.\n\nWong's first official UAE visit as prime minister included high-level talks on expanding cooperation in trade, investment, energy, technology, and education.\n\nThe leaders agreed to launch negotiations for a Comprehensive Economic Partnership Agreement, building on $6.5 billion in non-oil trade last year, and signed memorandums on energy, water management, and disease control. They also planned a joint energy task force and future meetings on AI, cybersecurity, and space, reaffirming 40 years of diplomatic relations while noting Singapore's solidarity during Middle East tensions.", "body_zh": "在阿布扎比，总理劳伦斯·黄（ Lawrence Wong ）和总统谢赫·穆罕默德·本·扎耶德（ Sheikh Mohamed bin Zayed ）表示热烈欢迎，讨论了在区域挑战中深化两国伙伴关系的方法。\n\nWong作为总理首次正式访问阿联酋，包括就扩大贸易、投资、能源、技术和教育合作进行高层会谈。\n\n双方领导人同意在去年65亿美元非石油贸易的基础上启动全面经济伙伴关系协定的谈判，并签署了关于能源、水资源管理和疾病控制的备忘录。他们还计划成立一个联合能源工作组，并就人工智能、网络安全和太空举行未来会议，重申了40年的外交关系，同时指出新加坡在中东紧张局势中的团结。"}, {"id": "2112331788529840225", "domain": "国际", "url": "https://x.com/i/trending/2112331788529840225", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T17:06:32.000Z", "title_en": "Trump Cuts Weather Satellite Plans, Sparking Expert Divide", "title_zh": "特朗普削减气象卫星计划，引发专家分歧", "hook_en": "Experts warn that trimming U.S. weather satellites could rewind forecasting by a decade, while supporters say it sharpens focus on what matters most.", "hook_zh": "专家警告说，削减美国气象卫星可能会使预测倒退十年，而支持者表示，这会使人们更加关注最重要的事情。", "summary_en": "The Trump administration scaled back the GeoXO satellite program from six to four spacecraft and cut three instruments, dropping costs from $19.6 billion to $13 billion. A Government Accountability Office report from October 16, 2026, raised concerns about coverage gaps until 2032 and potential shortfalls in capabilities like air quality, ocean monitoring, and lightning mapping. Critics, including Democratic lawmakers, fear weaker predictions for extreme weather, but meteorologists like Ryan Maue call media coverage misleading and praise the refocus on core forecasting.", "summary_zh": "特朗普政府将GeoXO卫星计划从6个减少到4个，并削减了3个仪器，将成本从196亿美元降至130亿美元。政府问责局2026年10月16日的一份报告对2032年之前的覆盖缺口以及空气质量、海洋监测和闪电测绘等能力的潜在短缺提出了担忧。 包括民主党议员在内的批评人士担心极端天气的预测会减弱，但Ryan Maue等气象学家称媒体报道具有误导性，并赞扬重新关注核心预测。", "body_en": "Trump Cuts Weather Satellite Plans, Sparking Expert Divide.\n\nExperts warn that trimming U.S. weather satellites could rewind forecasting by a decade, while supporters say it sharpens focus on what matters most.\n\nThe Trump administration scaled back the GeoXO satellite program from six to four spacecraft and cut three instruments, dropping costs from $19.6 billion to $13 billion.\n\nA Government Accountability Office report from October 16, 2026, raised concerns about coverage gaps until 2032 and potential shortfalls in capabilities like air quality, ocean monitoring, and lightning mapping. Critics, including Democratic lawmakers, fear weaker predictions for extreme weather, but meteorologists like Ryan Maue call media coverage misleading and praise the refocus on core forecasting.", "body_zh": "专家警告说，削减美国气象卫星可能会使预测倒退十年，而支持者表示，这会使人们更加关注最重要的事情。\n\n特朗普政府将GeoXO卫星计划从6个减少到4个，并削减了3个仪器，将成本从196亿美元降至130亿美元。\n\n政府问责局2026年10月16日的一份报告对2032年之前的覆盖缺口以及空气质量、海洋监测和闪电测绘等能力的潜在短缺提出了担忧。包括民主党议员在内的批评人士担心极端天气的预测会减弱，但Ryan Maue等气象学家称媒体报道具有误导性，并赞扬重新关注核心预测。"}, {"id": "2112488391983927699", "domain": "国际", "url": "https://x.com/i/trending/2112488391983927699", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T16:45:02.000Z", "title_en": "U.S. Envoy Tells Gulf Allies to Step Up on Defense", "title_zh": "美国特使告诉海湾盟国加强防御", "hook_en": "In Doha, U.S. special envoy Tom Barrack likened America's shifting role to raising teenagers—time for Gulf allies to handle their own security.", "hook_zh": "在多哈，美国特使汤姆·巴拉克（ Tom Barrack ）将美国的角色转变比作让海湾盟国提高青少年时间来处理自己的安全问题。", "summary_en": "At the Global Security Forum, Barrack warned that the U.S. can no longer indefinitely guarantee Gulf states' security, calling the 80-year security-for-oil deal unsustainable amid Iranian strikes and failed U.S. interventions in Iraq and Libya. He urged countries like Saudi Arabia and the UAE to build their own defenses through regional partnerships, positioning America as a supporter rather than controller. Separate comments downplaying Iran as 'not an evil regime, just very religious' drew sharp backlash, with critics demanding his resignation and Iran's foreign minister voicing distrust.", "summary_zh": "在全球安全论坛上，巴拉克警告说，美国不能再无限期地保证海湾国家的安全，称在伊朗罢工和美国对伊拉克和利比亚的干预失败的情况下， 80年的石油换安全协议是不可持续的。他敦促沙特阿拉伯和阿联酋等国家通过区域伙伴关系建立自己的防御，将美国定位为支持者而不是控制者。 单独的评论将伊朗淡化为“不是一个邪恶的政权，只是非常虔诚” ，引起了强烈反对，批评者要求他辞职，伊朗外交部长表示不信任。", "body_en": "U.S. Envoy Tells Gulf Allies to Step Up on Defense.\n\nIn Doha, U.S. special envoy Tom Barrack likened America's shifting role to raising teenagers—time for Gulf allies to handle their own security.\n\nAt the Global Security Forum, Barrack warned that the U.S. can no longer indefinitely guarantee Gulf states' security, calling the 80-year security-for-oil deal unsustainable amid Iranian strikes and failed U.S.\n\ninterventions in Iraq and Libya. He urged countries like Saudi Arabia and the UAE to build their own defenses through regional partnerships, positioning America as a supporter rather than controller. Separate comments downplaying Iran as 'not an evil regime, just very religious' drew sharp backlash, with critics demanding his resignation and Iran's foreign minister voicing distrust.", "body_zh": "在多哈，美国特使汤姆·巴拉克（ Tom Barrack ）将美国的角色转变比作让海湾盟国提高青少年时间来处理自己的安全问题。\n\n在全球安全论坛上，巴拉克警告说，美国不能再无限期地保证海湾国家的安全，称在伊朗罢工和美国对伊拉克和利比亚的干预失败的情况下， 80年的石油换安全协议是不可持续的。\n\n他敦促沙特阿拉伯和阿联酋等国家通过区域伙伴关系建立自己的防御，将美国定位为支持者而不是控制者。单独的评论将伊朗淡化为“不是一个邪恶的政权，只是非常虔诚” ，引起了强烈反对，批评者要求他辞职，伊朗外交部长表示不信任。"}, {"id": "2112793532641808742", "domain": "国际", "url": "https://x.com/i/trending/2112793532641808742", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T15:11:04.000Z", "title_en": "Netanyahu Warns of Iran Attack Before October 27 Election", "title_zh": "内塔尼亚胡警告伊朗在10月27日大选前遭到袭击", "hook_en": "With Israel's election just days away, Prime Minister Benjamin Netanyahu shared a stark intelligence alert about potential strikes from Iran and its allies.", "hook_zh": "在以色列大选几天后，总理本雅明·内塔尼亚胡（ Benjamin Netanyahu ）就伊朗及其盟友可能发动的罢工发出了严厉的情报警报。", "summary_en": "In an i24NEWS interview, Netanyahu cited Mossad and military intelligence indicating adversaries might launch operations on the eve of the October 27 vote for the 26th Knesset. His Likud party faces a tight race against opposition led by figures like Gadi Eisenkot, marking the first full-term election in decades. Reactions split sharply, with some seeing prudent preparation and others suspecting election tactics, while separate reports noted U.S. resistance to Israeli strike plans on Iran before American midterms.", "summary_zh": "在i24NEWS的一次采访中，内塔尼亚胡援引摩萨德和军事情报表明，对手可能会在10月27日投票支持第26届以色列议会的前夕发动行动。他的利库德党面临着与加迪·艾森科特（ Gadi Eisenkot ）等人物领导的反对派的激烈竞争，这是几十年来的第一次全期选举。反应急剧分裂，一些人认为谨慎的准备和其他人怀疑选举策略，而单独的报告指出美国 在美国中期选举之前抵制以色列对伊朗的打击计划。", "body_en": "Netanyahu Warns of Iran Attack Before October 27 Election.\n\nWith Israel's election just days away, Prime Minister Benjamin Netanyahu shared a stark intelligence alert about potential strikes from Iran and its allies.\n\nIn an i24NEWS interview, Netanyahu cited Mossad and military intelligence indicating adversaries might launch operations on the eve of the October 27 vote for the 26th Knesset. His Likud party faces a tight race against opposition led by figures like Gadi Eisenkot, marking the first full-term election in decades.\n\nReactions split sharply, with some seeing prudent preparation and others suspecting election tactics, while separate reports noted U.S. resistance to Israeli strike plans on Iran before American midterms.", "body_zh": "在以色列大选几天后，总理本雅明·内塔尼亚胡（ Benjamin Netanyahu ）就伊朗及其盟友可能发动的罢工发出了严厉的情报警报。\n\n在i24NEWS的一次采访中，内塔尼亚胡援引摩萨德和军事情报表明，对手可能会在10月27日投票支持第26届以色列议会的前夕发动行动。\n\n他的利库德党面临着与加迪·艾森科特（ Gadi Eisenkot ）等人物领导的反对派的激烈竞争，这是几十年来的第一次全期选举。反应急剧分裂，一些人认为谨慎的准备和其他人怀疑选举策略，而单独的报告指出美国 在美国中期选举之前抵制以色列对伊朗的打击计划。"}, {"id": "2112190707750306028", "domain": "国际", "url": "https://x.com/i/trending/2112190707750306028", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T13:54:22.000Z", "title_en": "US Defense Secretary Hegseth Visits Israel Amid Iran Strike Talks", "title_zh": "美国国防部长黑格塞斯在伊朗罢工谈判期间访问以色列", "hook_en": "Pete Hegseth landed unannounced at a southern Israeli air base to huddle with Netanyahu, just as whispers of strikes on Iran grow louder before Israel's elections.", "hook_zh": "皮特·黑格塞斯（ Pete Hegseth ）突然降落在以色列南部的一个空军基地，与内塔尼亚胡（ Netanyahu ）挤在一起，就像在以色列选举前对伊朗发动罢工的窃窃私语一样。", "summary_en": "The US Secretary of Defense met Prime Minister Benjamin Netanyahu on Monday to discuss regional threats and potential operations against Iran, eight days before Israel's October 27 parliamentary elections. Netanyahu reiterated his vow that Iran will not get nuclear weapons under his watch and told President Trump they would finish the job together, amid Israeli troops on high alert with leave canceled. While some question the timing ahead of Netanyahu's tough re-election fight, the visit underscores strong US-Israel coordination, though the White House plans no US strikes before American midterms.", "summary_zh": "美国国防部长周一在以色列10月27日议会选举前八天会见了总理本雅明·内塔尼亚胡（ Benjamin Netanyahu ） ，讨论了对伊朗的地区威胁和潜在行动。内塔尼亚胡重申他的誓言，伊朗不会在他的监督下获得核武器，并告诉特朗普总统，在以色列军队处于高度戒备状态并取消休假的情况下，他们将共同完成这项工作。 虽然有些人质疑内塔尼亚胡艰难的连任斗争之前的时机，但这次访问凸显了美以之间的强有力协调，尽管白宫计划在美国中期选举之前不会进行美国罢工。", "body_en": "US Defense Secretary Hegseth Visits Israel Amid Iran Strike Talks.\n\nPete Hegseth landed unannounced at a southern Israeli air base to huddle with Netanyahu, just as whispers of strikes on Iran grow louder before Israel's elections.\n\nThe US Secretary of Defense met Prime Minister Benjamin Netanyahu on Monday to discuss regional threats and potential operations against Iran, eight days before Israel's October 27 parliamentary elections.\n\nNetanyahu reiterated his vow that Iran will not get nuclear weapons under his watch and told President Trump they would finish the job together, amid Israeli troops on high alert with leave canceled. While some question the timing ahead of Netanyahu's tough re-election fight, the visit underscores strong US-Israel coordination, though the White House plans no US strikes before American midterms.", "body_zh": "皮特·黑格塞斯（ Pete Hegseth ）突然降落在以色列南部的一个空军基地，与内塔尼亚胡（ Netanyahu ）挤在一起，就像在以色列选举前对伊朗发动罢工的窃窃私语一样。\n\n美国国防部长周一在以色列10月27日议会选举前八天会见了总理本雅明·内塔尼亚胡（ Benjamin Netanyahu ） ，讨论了对伊朗的地区威胁和潜在行动。\n\n内塔尼亚胡重申他的誓言，伊朗不会在他的监督下获得核武器，并告诉特朗普总统，在以色列军队处于高度戒备状态并取消休假的情况下，他们将共同完成这项工作。虽然有些人质疑内塔尼亚胡艰难的连任斗争之前的时机，但这次访问凸显了美以之间的强有力协调，尽管白宫计划在美国中期选举之前不会进行美国罢工。"}, {"id": "2112783516509336062", "domain": "国际", "url": "https://x.com/i/trending/2112783516509336062", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T11:50:08.000Z", "title_en": "Posts Celebrate Pakistan's Munir as Middle East Peacemaker", "title_zh": "帖子庆祝巴基斯坦的穆尼尔成为中东和平缔造者", "hook_en": "Field Marshal Syed Asim Munir appears in striking images against Dubai skylines and flags, hailed for his steady hand in bridging divides between nations.", "hook_zh": "陆军元帅赛义德·阿西姆·穆尼尔（ Syed Asim Munir ）出现在迪拜天际线和旗帜的引人注目的图像中，他因稳步弥合国家间的分歧而受到称赞。", "summary_en": "Dozens of X posts share stylized images branding Pakistan's Chief of Army Staff and Chief of Defence Forces as the 'Peacemaker CDF,' praising his focus on dialogue, stability, and cooperation for global harmony. These tributes draw from his key role in 2026 mediation between the U.S. and Iran, where he traveled to Tehran and facilitated behind-the-scenes talks that led to a ceasefire. Pakistani officials like Interior Minister Mohsin Naqvi credit Munir's personal relationships with leaders for opening those channels, reflecting broad appreciation for his diplomatic efforts.", "summary_zh": "数十个X帖子分享了将巴基斯坦陆军参谋长和国防军参谋长称为“和平缔造者CDF”的风格化图像，称赞他专注于对话、稳定和合作以实现全球和谐。这些敬意来自他在2026年美国和伊朗之间的调解中的关键作用，在那里他前往德黑兰并促进了导致停火的幕后谈判。 巴基斯坦内政部长莫辛·纳克维（ Mohsin Naqvi ）等官员认为，穆尼尔与领导人的个人关系打开了这些渠道，这反映了他对外交努力的广泛赞赏。", "body_en": "Posts Celebrate Pakistan's Munir as Middle East Peacemaker.\n\nField Marshal Syed Asim Munir appears in striking images against Dubai skylines and flags, hailed for his steady hand in bridging divides between nations.\n\nDozens of X posts share stylized images branding Pakistan's Chief of Army Staff and Chief of Defence Forces as the 'Peacemaker CDF,' praising his focus on dialogue, stability, and cooperation for global harmony. These tributes draw from his key role in 2026 mediation between the U.S.\n\nand Iran, where he traveled to Tehran and facilitated behind-the-scenes talks that led to a ceasefire. Pakistani officials like Interior Minister Mohsin Naqvi credit Munir's personal relationships with leaders for opening those channels, reflecting broad appreciation for his diplomatic efforts.", "body_zh": "陆军元帅赛义德·阿西姆·穆尼尔（ Syed Asim Munir ）出现在迪拜天际线和旗帜的引人注目的图像中，他因稳步弥合国家间的分歧而受到称赞。\n\n数十个X帖子分享了将巴基斯坦陆军参谋长和国防军参谋长称为“和平缔造者CDF”的风格化图像，称赞他专注于对话、稳定和合作以实现全球和谐。\n\n这些敬意来自他在2026年美国和伊朗之间的调解中的关键作用，在那里他前往德黑兰并促进了导致停火的幕后谈判。巴基斯坦内政部长莫辛·纳克维（ Mohsin Naqvi ）等官员认为，穆尼尔与领导人的个人关系打开了这些渠道，这反映了他对外交努力的广泛赞赏。"}, {"id": "2112598857280327690", "domain": "国际", "url": "https://x.com/i/trending/2112598857280327690", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T11:23:20.000Z", "title_en": "NATO Bolsters Black Sea Surveillance After Drone Strikes on Ships", "title_zh": "无人机袭击船舶后，北约加强黑海监视", "hook_en": "Commercial ships near Romania and Bulgaria have faced drone attacks, leaving seafarers killed, injured, or missing. NATO ambassadors responded swiftly with a plan to ramp up protection.", "hook_zh": "罗马尼亚和保加利亚附近的商船遭到无人机袭击，造成海员死亡、受伤或失踪。北约大使迅速作出回应，计划加强保护。", "summary_en": "NATO announced additional maritime patrol aircraft, radar systems, drones, intelligence personnel, and forensic teams to enhance sea awareness, gather evidence, and safeguard trade routes following recent strikes. Romanian President Nicușor Dan highlighted the seriousness after talks with NATO's Mark Rutte and Bulgaria's Rumen Radev, stressing allied commitment to defend every inch of territory. On October 17, Romanian F-16s downed two drones over territorial waters, while a U.S. P-8A Poseidon began surveillance flights from Bulgaria. Though NATO has not attributed blame, analysts link the attacks to Russia amid its Ukraine war, which Moscow denies.", "summary_zh": "北约宣布增加海上巡逻机、雷达系统、无人机、情报人员和法医小组，以提高海上意识，收集证据，并在最近的罢工后保护贸易路线。罗马尼亚总统尼古索尔·丹（ Nicușor Dan ）在与北约的马克·吕特（ Mark Rutte ）和保加利亚的鲁门·拉德夫（ Rumen Radev ）会谈后强调了这一严肃性，并强调盟国承诺保卫每一寸领土 10月17日，罗马尼亚F-16在领海上空击落了两架无人机，而美国P-8A Poseidon开始从保加利亚进行监视飞行。尽管北约没有将责任归咎于此，但分析人士将这次袭击与俄罗斯的乌克兰战争联系起来，莫斯科对此予以否认。", "body_en": "Commercial ships near Romania and Bulgaria have faced drone attacks, leaving seafarers killed, injured, or missing. NATO ambassadors responded swiftly with a plan to ramp up protection.\n\nNATO announced additional maritime patrol aircraft, radar systems, drones, intelligence personnel, and forensic teams to enhance sea awareness, gather evidence, and safeguard trade routes following recent strikes. Romanian President Nicușor Dan highlighted the seriousness after talks with NATO's Mark Rutte and Bulgaria's Rumen Radev, stressing allied commitment to defend every inch of territory.\n\nOn October 17, Romanian F-16s downed two drones over territorial waters, while a U.S. P-8A Poseidon began surveillance flights from Bulgaria. Though NATO has not attributed blame, analysts link the attacks to Russia amid its Ukraine war, which Moscow denies.", "body_zh": "罗马尼亚和保加利亚附近的商船遭到无人机袭击，造成海员死亡、受伤或失踪。北约大使迅速作出回应，计划加强保护。\n\n北约宣布增加海上巡逻机、雷达系统、无人机、情报人员和法医小组，以提高海上意识，收集证据，并在最近的罢工后保护贸易路线。\n\n罗马尼亚总统尼古索尔·丹（ Nicușor Dan ）在与北约的马克·吕特（ Mark Rutte ）和保加利亚的鲁门·拉德夫（ Rumen Radev ）会谈后强调了这一严肃性，并强调盟国承诺保卫每一寸领土 10月17日，罗马尼亚F-16在领海上空击落了两架无人机，而美国P-8A Poseidon开始从保加利亚进行监视飞行。尽管北约没有将责任归咎于此，但分析人士将这次袭击与俄罗斯的乌克兰战争联系起来，莫斯科对此予以否认。"}, {"id": "2112684371014807632", "domain": "国际", "url": "https://x.com/i/trending/2112684371014807632", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T04:33:13.000Z", "title_en": "Trump Calls Himself Best President in Israel's History", "title_zh": "特朗普称自己是以色列历史上最好的总统", "hook_en": "In a CNBC interview, Donald Trump declared himself 'the best president in the history of Israel,' a remark that quickly divided opinions online.", "hook_zh": "在接受CNBC采访时，唐纳德·特朗普宣称自己是“以色列历史上最好的总统” ，这一言论很快在网上引起了分歧。", "summary_en": "The comment came during an exclusive sit-down with financial tickers in the background, alongside his views on Jewish voters and Iran. Critics shared clips accusing him of prioritizing Israel over U.S. interests, with one post saying he 'doesn't even try to hide it anymore.' Supporters pointed to his actions like moving the U.S. embassy and recognizing the Golan Heights, while others reminded people he is 'a human being, too.' The exchange highlights tensions around U.S.-Israel ties amid Middle East conflicts and Trump's endorsement of Netanyahu.", "summary_zh": "该评论是在一次独家静坐中发表的，背景是金融股票，以及他对犹太选民和伊朗的看法。批评人士分享了指责他将以色列置于美国利益之上的剪辑，其中一篇文章称他“甚至不再试图隐瞒它。“支持者指出了他的行动，比如推动美国 并承认戈兰高地，而其他人提醒人们，他也是一个“人”。“这次交流凸显了在中东冲突和特朗普支持内塔尼亚胡的情况下，围绕美以关系的紧张关系。", "body_en": "Trump Calls Himself Best President in Israel's History.\n\nIn a CNBC interview, Donald Trump declared himself 'the best president in the history of Israel,' a remark that quickly divided opinions online.\n\nThe comment came during an exclusive sit-down with financial tickers in the background, alongside his views on Jewish voters and Iran. Critics shared clips accusing him of prioritizing Israel over U.S.\n\ninterests, with one post saying he 'doesn't even try to hide it anymore.' Supporters pointed to his actions like moving the U.S. embassy and recognizing the Golan Heights, while others reminded people he is 'a human being, too.' The exchange highlights tensions around U.S.-Israel ties amid Middle East conflicts and Trump's endorsement of Netanyahu.", "body_zh": "在接受CNBC采访时，唐纳德·特朗普宣称自己是“以色列历史上最好的总统” ，这一言论很快在网上引起了分歧。\n\n该评论是在一次独家静坐中发表的，背景是金融股票，以及他对犹太选民和伊朗的看法。批评人士分享了指责他将以色列置于美国利益之上的剪辑，其中一篇文章称他“甚至不再试图隐瞒它。\n\n“支持者指出了他的行动，比如推动美国 并承认戈兰高地，而其他人提醒人们，他也是一个“人”。“这次交流凸显了在中东冲突和特朗普支持内塔尼亚胡的情况下，围绕美以关系的紧张关系。"}, {"id": "2112384299999850805", "domain": "国际", "url": "https://x.com/i/trending/2112384299999850805", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:20:55.000Z", "title_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally", "title_zh": "特朗普在堪萨斯集会警告或退出北约", "hook_en": "Thousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.", "hook_zh": "数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。", "summary_en": "At a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate. He criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "summary_zh": "在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "body_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally.\n\nThousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.\n\nAt a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate.\n\nHe criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "body_zh": "特朗普在堪萨斯集会警告或退出北约。\n\n数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。\n\n在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。\n\n他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。"}, {"id": "2112623559877042588", "domain": "体育", "url": "https://x.com/i/trending/2112623559877042588", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T19:58:24.000Z", "title_en": "USL Launches 'United for Soccer' Brand and Promotion-Relegation Pyramid", "title_zh": "USL推出“United for Soccer”品牌和晋级金字塔", "hook_en": "Imagine soccer matches where every goal could send your team up a division. The USL is making that real with a fresh unified look and America's first merit-based pro pyramid.", "hook_zh": "想象一下，足球比赛中，每个进球都可以将您的团队划分为一个部门。USL正在以全新的统一外观和美国第一个以绩效为基础的亲金字塔来实现这一目标。", "summary_en": "The United Soccer League unveiled its 'United for Soccer' rebrand on October 20, featuring a shared USL Blue palette, goal-net inspired marks, and a stair-step 'S' logo symbolizing progress. It unites eight leagues across youth academies to pro men's and women's divisions, with USL Premier launching as Division I in 2028 above Championship (II) and League One (III), introducing promotion and relegation that year. Fans show enthusiasm for the European-style stakes and community growth, though some miss the old distinct colors, as the league spans over 200 U.S. communities.", "summary_zh": "10月20日，联合足球联盟（ United Soccer League ）推出了“United for Soccer”品牌重塑，其中包括共享的USL蓝色调色板、受球门网启发的标志和象征进步的阶梯标志。它将青年学院的八个联赛结合到职业男女联赛中， USL Premier于2028年在锦标赛（ II ）和一级联赛（ III ）之上作为一级联赛推出，当年引入了晋升和降级。 球迷们对欧洲风格的赌注和社区增长表现出热情，尽管有些人错过了旧的不同颜色，因为联盟跨越了200多个美国社区。", "body_en": "USL Launches 'United for Soccer' Brand and Promotion-Relegation Pyramid.\n\nImagine soccer matches where every goal could send your team up a division. The USL is making that real with a fresh unified look and America's first merit-based pro pyramid.\n\nThe United Soccer League unveiled its 'United for Soccer' rebrand on October 20, featuring a shared USL Blue palette, goal-net inspired marks, and a stair-step 'S' logo symbolizing progress. It unites eight leagues across youth academies to pro men's and women's divisions, with USL Premier launching as Division I in 2028 above Championship (II) and League One (III), introducing promotion and relegation that year.\n\nFans show enthusiasm for the European-style stakes and community growth, though some miss the old distinct colors, as the league spans over 200 U.S. communities.", "body_zh": "想象一下，足球比赛中，每个进球都可以将您的团队划分为一个部门。USL正在以全新的统一外观和美国第一个以绩效为基础的亲金字塔来实现这一目标。\n\n10月20日，联合足球联盟（ United Soccer League ）推出了“United for Soccer”品牌重塑，其中包括共享的USL蓝色调色板、受球门网启发的标志和象征进步的阶梯标志。\n\n它将青年学院的八个联赛结合到职业男女联赛中， USL Premier于2028年在锦标赛（ II ）和一级联赛（ III ）之上作为一级联赛推出，当年引入了晋升和降级。球迷们对欧洲风格的赌注和社区增长表现出热情，尽管有些人错过了旧的不同颜色，因为联盟跨越了200多个美国社区。"}, {"id": "2112650194173022254", "domain": "体育", "url": "https://x.com/i/trending/2112650194173022254", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T19:57:53.000Z", "title_en": "Chelsea's Clean-Sheet Wins Over PSG and Barcelona Resurface After Latest Clash", "title_zh": "在最近的冲突之后，切尔西的干净表格赢得了巴黎圣日耳曼和巴塞罗那的重新浮出水面", "hook_en": "Chelsea fans are reliving two unforgettable 3-0 triumphs from 2025, the only clean-sheet double over PSG and Barcelona in a single season.", "hook_zh": "切尔西球迷正在重温2025年的两次令人难忘的3-0胜利，这是巴黎圣日耳曼和巴塞罗那在一个赛季中唯一的干净比赛。", "summary_en": "Last year, Chelsea dominated PSG 3-0 in the FIFA Club World Cup final on July 13 at MetLife Stadium, with Cole Palmer scoring twice and assisting the third before a late red card left PSG with 10 men. Five months later on November 25 at Stamford Bridge in the Champions League, they beat Barcelona 3-0 via an own goal, Estêvão's stunner, and Liam Delap's finish, after another red card to Barcelona's captain. These feats are lighting up discussions following PSG's recent 4-2 win over Barcelona, with fans boasting Chelsea showed both rivals true levels while some recall an earlier 8-2 aggregate loss to PSG.", "summary_zh": "去年，切尔西在7月13日在大都会体育场举行的FIFA俱乐部世界杯决赛中以3-0领先PSG ，科尔·帕尔默两次得分，第三次助攻，之后红牌以10名男子离开PSG。五个月后的11月25日，在欧洲冠军联赛的斯坦福桥，他们以3比0击败巴塞罗那，以自己的进球、埃斯特旺的惊人成绩和利亚姆·德拉普的完赛，再次获得巴塞罗那队长的红牌。 在巴黎圣日耳曼队最近4-2战胜巴塞罗那后，这些壮举点燃了讨论，球迷吹嘘切尔西展示了两个对手的真实水平，而一些人回忆起早些时候8-2输给巴黎圣日耳曼队的情况。", "body_en": "Chelsea fans are reliving two unforgettable 3-0 triumphs from 2025, the only clean-sheet double over PSG and Barcelona in a single season.\n\nLast year, Chelsea dominated PSG 3-0 in the FIFA Club World Cup final on July 13 at MetLife Stadium, with Cole Palmer scoring twice and assisting the third before a late red card left PSG with 10 men.\n\nFive months later on November 25 at Stamford Bridge in the Champions League, they beat Barcelona 3-0 via an own goal, Estêvão's stunner, and Liam Delap's finish, after another red card to Barcelona's captain. These feats are lighting up discussions following PSG's recent 4-2 win over Barcelona, with fans boasting Chelsea showed both rivals true levels while some recall an earlier 8-2 aggregate loss to PSG.", "body_zh": "切尔西球迷正在重温2025年的两次令人难忘的3-0胜利，这是巴黎圣日耳曼和巴塞罗那在一个赛季中唯一的干净比赛。\n\n去年，切尔西在7月13日在大都会体育场举行的FIFA俱乐部世界杯决赛中以3-0领先PSG ，科尔·帕尔默两次得分，第三次助攻，之后红牌以10名男子离开PSG。\n\n五个月后的11月25日，在欧洲冠军联赛的斯坦福桥，他们以3比0击败巴塞罗那，以自己的进球、埃斯特旺的惊人成绩和利亚姆·德拉普的完赛，再次获得巴塞罗那队长的红牌。在巴黎圣日耳曼队最近4-2战胜巴塞罗那后，这些壮举点燃了讨论，球迷吹嘘切尔西展示了两个对手的真实水平，而一些人回忆起早些时候8-2输给巴黎圣日耳曼队的情况。"}, {"id": "2112984440074846322", "domain": "体育", "url": "https://x.com/i/trending/2112984440074846322", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T19:57:47.000Z", "title_en": "Manchester United Women Lead 3-0 at Halftime Against Liverpool in Cup Clash", "title_zh": "曼联女子队在半场对阵利物浦的比赛中以3-0领先", "hook_en": "Lea Schuller struck first in the 11th minute, then Mared Griffiths unleashed a brace right before the break, sending United fans into raptures.", "hook_zh": "Lea Schuller在第11分钟先发制人，然后Mared Griffiths在休息前释放了一个支架，让曼联球迷欣喜若狂。", "summary_en": "In their Subway Players Cup league-phase match on October 21, 2026, Manchester United Women dominated the first half against Liverpool Women. Schuller's fine first-time finish opened the scoring, followed by Griffiths doubling the lead in the 41st minute and adding a third three minutes later for a 3-0 halftime advantage. The visitors controlled the game with clinical finishing and quick transitions, while Liverpool posted a simple 'Half-time' update as the teams headed to the dressing rooms.", "summary_zh": "在2026年10月21日的赛道球员杯联赛阶段比赛中，曼联女子队主宰了上半场对阵利物浦女队的比赛。舒勒精彩的首次完赛打开了得分，随后格里菲斯在第41分钟将领先优势翻了一番，并在三分钟后增加了第三名，以获得3-0的半场优势。 游客通过临床整理和快速过渡控制了比赛，而利物浦则在球队前往更衣室时发布了一个简单的“半场”更新。", "body_en": "Manchester United Women Lead 3-0 at Halftime Against Liverpool in Cup Clash.\n\nLea Schuller struck first in the 11th minute, then Mared Griffiths unleashed a brace right before the break, sending United fans into raptures.\n\nIn their Subway Players Cup league-phase match on October 21, 2026, Manchester United Women dominated the first half against Liverpool Women.\n\nSchuller's fine first-time finish opened the scoring, followed by Griffiths doubling the lead in the 41st minute and adding a third three minutes later for a 3-0 halftime advantage. The visitors controlled the game with clinical finishing and quick transitions, while Liverpool posted a simple 'Half-time' update as the teams headed to the dressing rooms.", "body_zh": "Lea Schuller在第11分钟先发制人，然后Mared Griffiths在休息前释放了一个支架，让曼联球迷欣喜若狂。\n\n在2026年10月21日的赛道球员杯联赛阶段比赛中，曼联女子队主宰了上半场对阵利物浦女队的比赛。\n\n舒勒精彩的首次完赛打开了得分，随后格里菲斯在第41分钟将领先优势翻了一番，并在三分钟后增加了第三名，以获得3-0的半场优势。游客通过临床整理和快速过渡控制了比赛，而利物浦则在球队前往更衣室时发布了一个简单的“半场”更新。"}, {"id": "2112918027859554811", "domain": "体育", "url": "https://x.com/i/trending/2112918027859554811", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T19:43:37.000Z", "title_en": "Warriors-Lakers Tip Off 2026-27 NBA Season in California Clash", "title_zh": "勇士队-湖人队2026-27赛季加利福尼亚交锋", "hook_en": "Stephen Curry's 'Lock in #dubnation #year18' post captures the buzz as he heads into his 18th season, facing the Lakers in a packed Crypto.com Arena.", "hook_zh": "斯蒂芬·库里的“锁定# dubnation # year18”帖子捕捉到了嗡嗡声，因为他进入了第18个赛季，在拥挤的Crypto.com竞技场中面对湖人队。", "summary_en": "The Golden State Warriors visit the Los Angeles Lakers on Wednesday night to launch the 2026-27 NBA season, with tipoff at 7 pm PT on ESPN. Curry, probable despite a recent ankle tweak, leads a shorthanded Warriors squad missing Jimmy Butler and Moses Moody until January, while Lakers fans hype their home favorites. Both sides share excitement online, from Warriors' 'WE’RE BAAAACK' to Lakers' 'LAKERS BASKETBALL IS BACK,' marking Curry's longevity at age 38 in this classic rivalry opener.", "summary_zh": "金州勇士队于周三晚上访问洛杉矶湖人队，启动2026-27赛季的NBA赛季，并于太平洋时间晚上7点在ESPN上发布消息。咖喱，可能尽管最近脚踝调整，领导一个人手不足的勇士队失踪吉米·巴特勒和摩西·穆迪，直到一月，而湖人队的球迷炒作他们最喜欢的主场。 从勇士队的“WE 'RE BAAAACK”到湖人队的“湖人篮球回归” ，双方都在网上分享了兴奋，这标志着库里在这场经典的竞争揭幕战中38岁的长寿。", "body_en": "Warriors-Lakers Tip Off 2026-27 NBA Season in California Clash.\n\nStephen Curry's 'Lock in #dubnation #year18' post captures the buzz as he heads into his 18th season, facing the Lakers in a packed Crypto.com Arena.\n\nThe Golden State Warriors visit the Los Angeles Lakers on Wednesday night to launch the 2026-27 NBA season, with tipoff at 7 pm PT on ESPN.\n\nCurry, probable despite a recent ankle tweak, leads a shorthanded Warriors squad missing Jimmy Butler and Moses Moody until January, while Lakers fans hype their home favorites. Both sides share excitement online, from Warriors' 'WE’RE BAAAACK' to Lakers' 'LAKERS BASKETBALL IS BACK,' marking Curry's longevity at age 38 in this classic rivalry opener.", "body_zh": "斯蒂芬·库里的“锁定# dubnation # year18”帖子捕捉到了嗡嗡声，因为他进入了第18个赛季，在拥挤的Crypto.com竞技场中面对湖人队。\n\n金州勇士队于周三晚上访问洛杉矶湖人队，启动2026-27赛季的NBA赛季，并于太平洋时间晚上7点在ESPN上发布消息。\n\n咖喱，可能尽管最近脚踝调整，领导一个人手不足的勇士队失踪吉米·巴特勒和摩西·穆迪，直到一月，而湖人队的球迷炒作他们最喜欢的主场。从勇士队的“WE 'RE BAAAACK”到湖人队的“湖人篮球回归” ，双方都在网上分享了兴奋，这标志着库里在这场经典的竞争揭幕战中38岁的长寿。"}, {"id": "2112984435729576320", "domain": "体育", "url": "https://x.com/i/trending/2112984435729576320", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T19:16:37.000Z", "title_en": "NFL Sticks with France Game Amid Paris Riots", "title_zh": "NFL在巴黎骚乱中与法国队比赛", "hook_en": "As riots grip Paris with clashes, looting, and arrests, the NFL readies its first regular-season game there, drawing sharp questions from players' families and critics.", "hook_zh": "随着骚乱笼罩着巴黎的冲突、抢劫和逮捕， NFL准备在那里进行第一场常规赛，引起了球员家属和评论家的尖锐质疑。", "summary_en": "The Pittsburgh Steelers face the New Orleans Saints at Stade de France on October 25, despite unrest from protests over living costs, school conditions, and public services that led to thousands of arrests and injuries. NFL Commissioner Roger Goodell insists the protests are mostly peaceful and players face no danger, with ramped-up stadium security coordinated with French authorities and the U.S. State Department. Dani Watt, wife of Steelers star T.J. Watt, publicly asked how sending players and families into the turmoil makes sense, while the league presses ahead with preparations unchanged.", "summary_zh": "匹兹堡钢人队于10月25日在法兰西体育场面对新奥尔良圣徒，尽管抗议生活费用，学校条件和公共服务导致数千人被捕和受伤。美国国家橄榄球联盟（ NFL ）专员罗杰·古德尔（ Roger Goodell ）坚称，抗议活动大多是和平的，球员们没有面临危险，体育场的安全措施得到了法国当局和美国国务院的协调。 钢人队明星T.J.瓦特的妻子丹尼·瓦特（ Dani Watt ）公开询问如何让球员和家人陷入混乱，而联盟则继续推进准备工作。", "body_en": "NFL Sticks with France Game Amid Paris Riots.\n\nAs riots grip Paris with clashes, looting, and arrests, the NFL readies its first regular-season game there, drawing sharp questions from players' families and critics.\n\nThe Pittsburgh Steelers face the New Orleans Saints at Stade de France on October 25, despite unrest from protests over living costs, school conditions, and public services that led to thousands of arrests and injuries. NFL Commissioner Roger Goodell insists the protests are mostly peaceful and players face no danger, with ramped-up stadium security coordinated with French authorities and the U.S.\n\nState Department. Dani Watt, wife of Steelers star T.J. Watt, publicly asked how sending players and families into the turmoil makes sense, while the league presses ahead with preparations unchanged.", "body_zh": "随着骚乱笼罩着巴黎的冲突、抢劫和逮捕， NFL准备在那里进行第一场常规赛，引起了球员家属和评论家的尖锐质疑。\n\n匹兹堡钢人队于10月25日在法兰西体育场面对新奥尔良圣徒，尽管抗议生活费用，学校条件和公共服务导致数千人被捕和受伤。\n\n美国国家橄榄球联盟（ NFL ）专员罗杰·古德尔（ Roger Goodell ）坚称，抗议活动大多是和平的，球员们没有面临危险，体育场的安全措施得到了法国当局和美国国务院的协调。钢人队明星T.J.瓦特的妻子丹尼·瓦特（ Dani Watt ）公开询问如何让球员和家人陷入混乱，而联盟则继续推进准备工作。"}, {"id": "2112913094968000571", "domain": "体育", "url": "https://x.com/i/trending/2112913094968000571", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T18:36:47.000Z", "title_en": "Giannis Debuts for Heat Against Timberwolves in Season Opener", "title_zh": "字母哥热火首秀对阵森林狼，揭幕战开启", "hook_en": "Giannis Antetokounmpo steps onto the Kaseya Center court for the first time as a Miami Heat player, teaming up with Bam Adebayo in a matchup full of fresh energy.", "hook_zh": "扬尼斯·阿德托昆博首次以迈阿密热火球员身份踏上卡塞亚中心球场，与巴姆·阿德巴约并肩，充满新鲜感。", "summary_en": "The Heat host the Timberwolves tonight at 7:30 p.m. ET on ESPN, marking Giannis's debut after his blockbuster trade from Milwaukee that sent Tyler Herro, Jaime Jaquez Jr., Kel'el Ware, Kasparas Jakucionis, and picks to the Bucks in exchange for the two-time MVP and Bobby Portis. Minnesota counters with new backcourt duo LaMelo Ball and Anthony Edwards following their multi-team deal. Giannis shared his excitement about playing with Bam, noting their matching birthdays and brotherly vibe, while both teams hype the night with game-day posts and fans anticipate a thrilling start to the 2026-27 season.", "summary_zh": "热火今晚美东时间 7:30 在 ESPN 主场迎战森林狼，标志着字母哥重磅交易后的首秀——密尔沃基雄鹿用这位两届 MVP 与鲍比·波蒂斯换来泰勒·希罗、海梅·哈克兹二世、凯勒尔·韦尔、卡斯帕拉斯·亚库乔尼斯及选秀权。明尼苏达则以拉梅洛·鲍尔与安东尼·爱德华兹组成新后场双核。扬尼斯表达与巴姆搭档的兴奋，提到两人同生日与兄弟般默契；双方用比赛日动态造势，球迷期待 2026-27 赛季精彩开局。", "body_en": "Giannis Debuts for Heat Against Timberwolves in Season Opener.\n\nGiannis Antetokounmpo steps onto the Kaseya Center court for the first time as a Miami Heat player, teaming up with Bam Adebayo in a matchup full of fresh energy.\n\nThe Heat host the Timberwolves tonight at 7:30 p.m. ET on ESPN, marking Giannis's debut after his blockbuster trade from Milwaukee that sent Tyler Herro, Jaime Jaquez Jr., Kel'el Ware, Kasparas Jakucionis, and picks to the Bucks in exchange for the two-time MVP and Bobby Portis.\n\nMinnesota counters with new backcourt duo LaMelo Ball and Anthony Edwards following their multi-team deal. Giannis shared his excitement about playing with Bam, noting their matching birthdays and brotherly vibe, while both teams hype the night with game-day posts and fans anticipate a thrilling start to the 2026-27 season.", "body_zh": "字母哥热火首秀对阵森林狼，揭幕战开启。\n\n扬尼斯·阿德托昆博首次以迈阿密热火球员身份踏上卡塞亚中心球场，与巴姆·阿德巴约并肩，充满新鲜感。\n\n热火今晚美东时间 7:30 在 ESPN 主场迎战森林狼，标志着字母哥重磅交易后的首秀——密尔沃基雄鹿用这位两届 MVP 与鲍比·波蒂斯换来泰勒·希罗、海梅·哈克兹二世、凯勒尔·韦尔、卡斯帕拉斯·亚库乔尼斯及选秀权。\n\n明尼苏达则以拉梅洛·鲍尔与安东尼·爱德华兹组成新后场双核。扬尼斯表达与巴姆搭档的兴奋，提到两人同生日与兄弟般默契；双方用比赛日动态造势，球迷期待 2026-27 赛季精彩开局。"}, {"id": "2112595598553608689", "domain": "体育", "url": "https://x.com/i/trending/2112595598553608689", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T18:11:17.000Z", "title_en": "Magic Host Hawks in 2026-27 NBA Season Opener Tonight", "title_zh": "2026-27赛季NBA魔术老鹰揭幕战今晚", "hook_en": "Both teams are buzzing with energy as the Orlando Magic welcome the Atlanta Hawks to the Kia Center for the 2026-27 NBA season tip-off at 7 p.m. ET.", "hook_zh": "两支球队都充满活力，奥兰多魔术队在美国东部时间晚上7点欢迎亚特兰大老鹰队来到起亚中心参加2026-27赛季的NBA比赛。", "summary_en": "The Magic face injury hurdles with Anthony Black, Jonathan Isaac, Noah Penda, and Izaiyah Nelson ruled out, but Franz Wagner is good to go after shoulder soreness. Anthony Black stays focused despite no contract extension, calling team success more important. The Hawks miss Mouhamed Gueye and Henri Veesaar, leaning on Jalen Johnson and Nickeil Alexander-Walker, while coach Sean Sweeney makes his regular-season debut with stars Paolo Banchero and Desmond Bane leading Orlando.", "summary_zh": "魔术面部受伤的障碍， Anthony Black、Jonathan Isaac、Noah Penda和Izaiyah Nelson排除了，但Franz Wagner很适合治疗肩膀酸痛。安东尼·布莱克（ Anthony Black ）尽管没有续约，但仍然保持专注，他认为团队的成功更为重要。 老鹰队错过了Mouhamed Gueye和Henri Veesaar ，他们依靠Jalen Johnson和Nickeil Alexander-Walker ，而教练Sean Sweeney与明星Paolo Banchero和Desmond Bane领先奥兰多进行了常规赛首秀。", "body_en": "Magic Host Hawks in 2026-27 NBA Season Opener Tonight.\n\nBoth teams are buzzing with energy as the Orlando Magic welcome the Atlanta Hawks to the Kia Center for the 2026-27 NBA season tip-off at 7 p.m. ET.\n\nThe Magic face injury hurdles with Anthony Black, Jonathan Isaac, Noah Penda, and Izaiyah Nelson ruled out, but Franz Wagner is good to go after shoulder soreness.\n\nAnthony Black stays focused despite no contract extension, calling team success more important. The Hawks miss Mouhamed Gueye and Henri Veesaar, leaning on Jalen Johnson and Nickeil Alexander-Walker, while coach Sean Sweeney makes his regular-season debut with stars Paolo Banchero and Desmond Bane leading Orlando.", "body_zh": "两支球队都充满活力，奥兰多魔术队在美国东部时间晚上7点欢迎亚特兰大老鹰队来到起亚中心参加2026-27赛季的NBA比赛。\n\n魔术面部受伤的障碍， Anthony Black、Jonathan Isaac、Noah Penda和Izaiyah Nelson排除了，但Franz Wagner很适合治疗肩膀酸痛。\n\n安东尼·布莱克（ Anthony Black ）尽管没有续约，但仍然保持专注，他认为团队的成功更为重要。老鹰队错过了Mouhamed Gueye和Henri Veesaar ，他们依靠Jalen Johnson和Nickeil Alexander-Walker ，而教练Sean Sweeney与明星Paolo Banchero和Desmond Bane领先奥兰多进行了常规赛首秀。"}, {"id": "2112468485569695755", "domain": "体育", "url": "https://x.com/i/trending/2112468485569695755", "category": "Sports", "topics": ["UEFA Champions League"], "updated_at": "2026-10-21T17:32:28.000Z", "title_en": "Foden Hat-Trick Powers Man City to 5-1 Champions League Win Over AEK Athens", "title_zh": "Foden帽子戏法使曼城队以5-1战胜AEK雅典队", "hook_en": "Phil Foden broke a 10-month goal drought with three strikes in a dominant night at the Etihad, grinning as fans lit up with joy.", "hook_zh": "菲尔·福登（ Phil Foden ）在阿提哈德的一个占主导地位的夜晚打破了为期10个月的进球干旱，三次罢工，球迷们高兴得笑了起来。", "summary_en": "Manchester City cruised to a 5-1 victory over AEK Athens in the Champions League, with Elliot Anderson opening the scoring, Foden netting twice before halftime and once more late on, and Rayan Cherki adding a classy finish after AEK's reply. Foden earned Player of the Match honors under manager Enzo Maresca, who rested Erling Haaland while praising the team's depth and calling Foden one of England's best. Foden shared 'Loved that' post-match, noting he's heading in the right direction after his long barren spell.", "summary_zh": "曼城队在欧洲冠军联赛中以5比1战胜AEK雅典队，埃利奥特·安德森（ Elliot Anderson ）开场得分，福登（ Foden ）在中场休息前两次入网，后来又一次入网，雷恩·切尔基（ Rayan Cherki ）在AEK的回复后增加了一个优雅的结局。福登在经理恩佐·马雷斯卡（ Enzo Maresca ）的带领下赢得了比赛中的球员荣誉，他让埃尔林·哈兰德（ Erling Haaland ）休息，同时赞扬了球队的深度，并称福登是英格兰最好的球员之一。 Foden在赛后分享了“喜欢那个” ，并指出他在漫长的荒芜咒语之后正朝着正确的方向前进。", "body_en": "Foden Hat-Trick Powers Man City to 5-1 Champions League Win Over AEK Athens.\n\nPhil Foden broke a 10-month goal drought with three strikes in a dominant night at the Etihad, grinning as fans lit up with joy.\n\nManchester City cruised to a 5-1 victory over AEK Athens in the Champions League, with Elliot Anderson opening the scoring, Foden netting twice before halftime and once more late on, and Rayan Cherki adding a classy finish after AEK's reply.\n\nFoden earned Player of the Match honors under manager Enzo Maresca, who rested Erling Haaland while praising the team's depth and calling Foden one of England's best. Foden shared 'Loved that' post-match, noting he's heading in the right direction after his long barren spell.", "body_zh": "菲尔·福登（ Phil Foden ）在阿提哈德的一个占主导地位的夜晚打破了为期10个月的进球干旱，三次罢工，球迷们高兴得笑了起来。\n\n曼城队在欧洲冠军联赛中以5比1战胜AEK雅典队，埃利奥特·安德森（ Elliot Anderson ）开场得分，福登（ Foden ）在中场休息前两次入网，后来又一次入网，雷恩·切尔基（ Rayan Cherki ）在AEK的回复后增加了一个优雅的结局。\n\n福登在经理恩佐·马雷斯卡（ Enzo Maresca ）的带领下赢得了比赛中的球员荣誉，他让埃尔林·哈兰德（ Erling Haaland ）休息，同时赞扬了球队的深度，并称福登是英格兰最好的球员之一。Foden在赛后分享了“喜欢那个” ，并指出他在漫长的荒芜咒语之后正朝着正确的方向前进。"}, {"id": "2112952170798805319", "domain": "体育", "url": "https://x.com/i/trending/2112952170798805319", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:07:39.000Z", "title_en": "Officials Probe Foreign Influence in French Riots Disinformation", "title_zh": "官员调查法国骚乱虚假信息中的外部势力影响", "hook_en": "Amid burning barricades and clashing crowds in Paris, videos of masked protesters waving antifascist banners spread fast—now officials suspect pro-Russian and far-right accounts amplified them to stir chaos.", "hook_zh": "巴黎街垒燃烧、人群冲突之际，蒙面抗议者挥舞反法西斯旗帜的视频迅速传播——官员怀疑亲俄与极右账号放大内容、煽动混乱。", "summary_en": "European security officials are investigating how pro-Russian, far-right social media accounts, along with suspected Iranian and Algerian operations, spread violent riot videos during France's recent unrest over education and living costs. The clashes escalated into arson and looting in Paris and other cities over the October 17 weekend, with regulators examining platform algorithms for boosting disinformation and hate speech. While President Macron sees no foreign hand in the events themselves, critics like Michael Shellenberger call the focus partisan deflection from real domestic issues, as probes continue into whether footage was real or fabricated.", "summary_zh": "欧洲安全官员正在调查亲俄、极右社交媒体账号，以及疑似伊朗、阿尔及利亚相关运作，如何在法国因教育与生活成本引发的近期动荡中传播暴力骚乱视频。冲突于 10 月 17 日周末在巴黎等地升级为纵火与抢劫，监管机构审视平台算法是否助推虚假信息与仇恨言论。马克龙总统认为事件本身未见外部黑手，但批评者如迈克尔·谢伦伯格称聚焦外部是对本国问题的党派式转移；调查仍在核实画面真伪。", "body_en": "Officials Probe Foreign Influence in French Riots Disinformation.\n\nAmid burning barricades and clashing crowds in Paris, videos of masked protesters waving antifascist banners spread fast—now officials suspect pro-Russian and far-right accounts amplified them to stir chaos.\n\nEuropean security officials are investigating how pro-Russian, far-right social media accounts, along with suspected Iranian and Algerian operations, spread violent riot videos during France's recent unrest over education and living costs.\n\nThe clashes escalated into arson and looting in Paris and other cities over the October 17 weekend, with regulators examining platform algorithms for boosting disinformation and hate speech. While President Macron sees no foreign hand in the events themselves, critics like Michael Shellenberger call the focus partisan deflection from real domestic issues, as probes continue into whether footage was real or fabricated.", "body_zh": "官员调查法国骚乱虚假信息中的外部势力影响。\n\n巴黎街垒燃烧、人群冲突之际，蒙面抗议者挥舞反法西斯旗帜的视频迅速传播——官员怀疑亲俄与极右账号放大内容、煽动混乱。\n\n欧洲安全官员正在调查亲俄、极右社交媒体账号，以及疑似伊朗、阿尔及利亚相关运作，如何在法国因教育与生活成本引发的近期动荡中传播暴力骚乱视频。\n\n冲突于 10 月 17 日周末在巴黎等地升级为纵火与抢劫，监管机构审视平台算法是否助推虚假信息与仇恨言论。马克龙总统认为事件本身未见外部黑手，但批评者如迈克尔·谢伦伯格称聚焦外部是对本国问题的党派式转移；调查仍在核实画面真伪。"}, {"id": "2112889351361139036", "domain": "体育", "url": "https://x.com/i/trending/2112889351361139036", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T16:42:49.000Z", "title_en": "EA FC 27 Teases New FUT Gallery Sets for MLS, NWSL, and Saudi League", "title_zh": "EA FC 27为MLS、NWSL和沙特联赛推出全新FUT画廊套装", "hook_en": "Community accounts lit up with Halloween-themed artwork showing glowing league logos and 'NEW SETS COMING' banners, getting players hyped for fresh collectibles.", "hook_zh": "社区账户上点缀着万圣节主题的艺术品，上面显示着闪闪发光的联赛徽标和“新套装即将推出”的横幅，让玩家大肆宣传新的收藏品。", "summary_en": "Popular FUT accounts shared promotional images and in-game screenshots revealing upcoming Gallery sets for Major League Soccer, the National Women’s Soccer League, and the Roshn Saudi League. These sets let players collect and grade items from the fully licensed leagues—MLS with 30 clubs, NWSL's full women's roster, and Saudi's 18 teams—to earn custom crests, kits, Gallery Tokens, and higher levels. Players are buzzing about pack strategies, market price shifts, and how owned cards will count toward progress, seeing it as a fun way to keep rewards flowing without endless grinding.", "summary_zh": "热门FUT账号分享了宣传图片和游戏内截图，展示了美国职业足球大联盟、全国女子足球联赛和罗森沙特联赛即将推出的画廊套装。这些套装可让玩家从完全授权的联赛（拥有30个俱乐部的MLS、NWSL的完整女子名单和沙特的18支球队）中收集物品并进行评级，以获得定制徽章、套件、画廊代币和更高等级。 玩家们正在喋喋不休地讨论卡包策略、市场价格变动以及拥有的卡牌将如何计入进度，认为这是一种有趣的方式，可以在没有无休止磨练的情况下保持奖励的流畅。", "body_en": "EA FC 27 Teases New FUT Gallery Sets for MLS, NWSL, and Saudi League.\n\nCommunity accounts lit up with Halloween-themed artwork showing glowing league logos and 'NEW SETS COMING' banners, getting players hyped for fresh collectibles.\n\nPopular FUT accounts shared promotional images and in-game screenshots revealing upcoming Gallery sets for Major League Soccer, the National Women’s Soccer League, and the Roshn Saudi League.\n\nThese sets let players collect and grade items from the fully licensed leagues—MLS with 30 clubs, NWSL's full women's roster, and Saudi's 18 teams—to earn custom crests, kits, Gallery Tokens, and higher levels. Players are buzzing about pack strategies, market price shifts, and how owned cards will count toward progress, seeing it as a fun way to keep rewards flowing without endless grinding.", "body_zh": "社区账户上点缀着万圣节主题的艺术品，上面显示着闪闪发光的联赛徽标和“新套装即将推出”的横幅，让玩家大肆宣传新的收藏品。\n\n热门FUT账号分享了宣传图片和游戏内截图，展示了美国职业足球大联盟、全国女子足球联赛和罗森沙特联赛即将推出的画廊套装。\n\n这些套装可让玩家从完全授权的联赛（拥有30个俱乐部的MLS、NWSL的完整女子名单和沙特的18支球队）中收集物品并进行评级，以获得定制徽章、套件、画廊代币和更高等级。玩家们正在喋喋不休地讨论卡包策略、市场价格变动以及拥有的卡牌将如何计入进度，认为这是一种有趣的方式，可以在没有无休止磨练的情况下保持奖励的流畅。"}, {"id": "2112933585816781110", "domain": "体育", "url": "https://x.com/i/trending/2112933585816781110", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T15:54:19.000Z", "title_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash", "title_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹", "hook_en": "Charles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.", "hook_zh": "Charles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。", "summary_en": "On the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth. Godongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "summary_zh": "在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。Godongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "body_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash.\n\nCharles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.\n\nOn the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth.\n\nGodongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "body_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹。\n\nCharles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。\n\n在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。\n\nGodongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。"}, {"id": "2112930908437426481", "domain": "体育", "url": "https://x.com/i/trending/2112930908437426481", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T15:43:54.000Z", "title_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment", "title_zh": "勒布朗热麦吐槽尼克斯「冠军哨」", "hook_en": "As the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.", "hook_zh": "尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。", "summary_en": "During the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists. His remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "summary_zh": "尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "body_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment.\n\nAs the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.\n\nDuring the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists.\n\nHis remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "body_zh": "勒布朗热麦吐槽尼克斯「冠军哨」。\n\n尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。\n\n尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。\n\n他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。"}, {"id": "2112248559555002819", "domain": "体育", "url": "https://x.com/i/trending/2112248559555002819", "category": "Sports", "topics": ["Soccer"], "updated_at": "2026-10-21T14:22:36.000Z", "title_en": "Ngumoha's Two Assists Fuel Liverpool's 4-3 Comeback Win Over Villarreal", "title_zh": "Ngumoha的两次助攻助力利物浦4-3复出战胜比利亚雷亚尔", "hook_en": "Eighteen-year-old Rio Ngumoha lit up Anfield with two assists, turning a two-goal deficit into a thrilling 4-3 victory and earning player of the match honors.", "hook_zh": "18岁的里奥·恩古莫哈（ Rio Ngumoha ）以两次助攻点燃了安菲尔德，将两球逆差变成了激动人心的4-3胜利，并赢得了比赛荣誉球员。", "summary_en": "Liverpool trailed early after goals from Villarreal's Georges Mikautadze and Sergi Cardona, but Alexis Mac Allister headed one back before halftime, and Ronald Araujo nodded in Ngumoha's cross to level it. In the second half, Ngumoha assisted Mac Allister's second, and Florian Wirtz added a fourth, with Villarreal's late reply not enough to spoil the comeback. Ngumoha became Liverpool's youngest ever to assist in the Champions League, telling TNT Sports that breaking records at 'the biggest club in the world' feels special as fans gave him a standing ovation.", "summary_zh": "利物浦在比利亚雷亚尔的乔治·米考塔泽（ Georges Mikautadze ）和塞尔吉·卡尔多纳（ Sergi Cardona ）进球后早早落后，但亚历克西斯·麦克·阿利斯特（ Alexis Mac Allister ）在中场休息前一回，罗纳德·阿劳霍（ Ronald Araujo ）在恩古莫哈在下半场， Ngumoha协助Mac Allister的第二名， Florian Wirtz增加了第四名， Villarreal迟到的回复不足以破坏复出。 Ngumoha成为利物浦有史以来最年轻的欧洲冠军联赛助攻，他告诉TNT Sports ，在“世界上最大的俱乐部”打破纪录感觉很特别，因为球迷们为他起立鼓掌。", "body_en": "Ngumoha's Two Assists Fuel Liverpool's 4-3 Comeback Win Over Villarreal.\n\nEighteen-year-old Rio Ngumoha lit up Anfield with two assists, turning a two-goal deficit into a thrilling 4-3 victory and earning player of the match honors.\n\nLiverpool trailed early after goals from Villarreal's Georges Mikautadze and Sergi Cardona, but Alexis Mac Allister headed one back before halftime, and Ronald Araujo nodded in Ngumoha's cross to level it.\n\nIn the second half, Ngumoha assisted Mac Allister's second, and Florian Wirtz added a fourth, with Villarreal's late reply not enough to spoil the comeback. Ngumoha became Liverpool's youngest ever to assist in the Champions League, telling TNT Sports that breaking records at 'the biggest club in the world' feels special as fans gave him a standing ovation.", "body_zh": "18岁的里奥·恩古莫哈（ Rio Ngumoha ）以两次助攻点燃了安菲尔德，将两球逆差变成了激动人心的4-3胜利，并赢得了比赛荣誉球员。\n\n利物浦在比利亚雷亚尔的乔治·米考塔泽（ Georges Mikautadze ）和塞尔吉·卡尔多纳（ Sergi Cardona ）进球后早早落后，但亚历克西斯·麦克·阿利斯特（ Alexis Mac Allister ）在中场休息前一回，罗纳德·阿劳霍（ Ronald Araujo ）在恩古莫哈在下半场， Ngumoha协助Mac Allister的第二名， Florian Wirtz增加了第四名， Villarreal迟到的回复不足以破坏复出。 Ngumoha成为利物浦有史以来最年轻的欧洲冠军联赛助攻，他告诉TNT Sports ，在“世界上最大的俱乐部”打破纪录感觉很特别，因为球迷们为他起立鼓掌。"}, {"id": "2112637290933789168", "domain": "娱乐", "url": "https://x.com/i/trending/2112637290933789168", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T19:44:00.000Z", "title_en": "Netflix Shares Drop After Soft Guidance Despite Solid Quarter", "title_zh": "奈飞三季度营收达标但指引逊色，股价盘后下跌", "hook_en": "Netflix hit revenue targets and boosted margins, but a cautious outlook sent shares tumbling over 5 percent in after-hours trading.", "hook_zh": "营收达到目标，前瞻指引不及预期，盘后股价跌约 5%–6%。", "summary_en": "The company reported $12.87 billion in third-quarter revenue, up 12 percent year over year, with earnings per share of 87 cents beating estimates and operating margins at 34.6 percent. Still, fourth-quarter revenue guidance of $13.44 billion fell slightly short of Wall Street expectations, and the 2026 ad revenue forecast was cut to $2.7 billion. Investor Chamath Palihapitiya shared he's shifted to daily YouTube viewing, calling Netflix a dormant subscription, amid data showing YouTube's U.S. TV share rising to 14 percent while Netflix holds steady near 8 percent. Shares extended losses over 6 percent, trading near $65 and down 52 percent from all-time highs.", "summary_zh": "奈飞营收 128.7 亿美元，同比增长 12%，为三年来最慢；每股收益 0.87 美元超预期，营业利润率达 34.6%。四季度营收 134.4 亿美元、EPS 0.67 美元的展望令华尔街失望，2026 年广告收入目标亦下调至 27 亿美元。叠加裁员约 1000 人及 YouTube 抢占美国电视份额，投资者对原创内容与广告扩张看法分化。", "body_en": "Netflix Stock Plunges on Weak Ad Guidance and YouTube Competition.\n\nNetflix's latest earnings hit Wall Street like a plot twist nobody saw coming, with shares dropping over 5% and erasing massive market value overnight.\n\nThe company reported third-quarter revenue of $12.87 billion in line with expectations and earnings per share of 87 cents that beat estimates, alongside record 34.6% operating margins and 44% net income growth to $3.66 billion. But investors sold off after Netflix cut its full-year ad revenue forecast to $2.7 billion from near $3 billion, trimmed 2026 revenue guidance to $51.1 billion, and signaled softer Q4 results.\n\nAmid YouTube's rising U.S. viewing share near 14% compared to Netflix's flat 8%, one investor noted daily YouTube watches versus a dormant Netflix subscription, fueling concerns over engagement and competition as shares hit 2024 lows around $65.", "body_zh": "奈飞三季度营收达标但指引逊色，股价盘后下跌。\n\n营收达到目标，前瞻指引不及预期，盘后股价跌约 5%–6%。\n\n奈飞营收 128.7 亿美元，同比增长 12%，为三年来最慢；每股收益 0.87 美元超预期，营业利润率达 34.6%。\n\n四季度营收 134.4 亿美元、EPS 0.67 美元的展望令华尔街失望，2026 年广告收入目标亦下调至 27 亿美元。叠加裁员约 1000 人及 YouTube 抢占美国电视份额，投资者对原创内容与广告扩张看法分化。"}, {"id": "2112698384712704400", "domain": "娱乐", "url": "https://x.com/i/trending/2112698384712704400", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T19:43:31.000Z", "title_en": "Midnights Turns Four with Fan Tributes and Record Reflections", "title_zh": "午夜四转，粉丝致敬和录音反思", "hook_en": "Four years ago today, Taylor Swift dropped Midnights at midnight, surprising fans hours later with extra tracks that reset pop music expectations.", "hook_zh": "四年前的今天，泰勒·斯威夫特（ Taylor Swift ）在午夜放弃了《午夜》（ Midnights ） ，几个小时后，歌迷们惊讶地发现了额外的曲目", "summary_en": "The 2022 album shattered records, including 184.7 million Spotify streams in its first day and the biggest U.S. opening week in years at No. 1 on the Billboard 200. Ten tracks hit the Hot 100 top 10 at once, with Anti-Hero leading, and it later won Album of the Year at the 2024 Grammys—Swift's fourth in the category. Fans are sharing memories of the rollout, praising moody synth-pop and deep cuts like Maroon, while noting its role in boosting women's achievements and launching 'Taylormania.'", "summary_zh": "2022年的专辑打破了记录，包括第一天的1.847亿个Spotify流媒体，以及Billboard 200上多年来最大的美国开幕周。十首歌曲同时进入Hot 100前十名，反英雄领先，后来在2024年格莱美-斯威夫特的第四张同类专辑中获得年度专辑奖。 粉丝们正在分享推出的回忆，称赞喜怒无常的合成流行音乐和像Maroon这样的深度剪辑，同时注意到它在提升女性成就和推出“Taylormania”方面的作用。", "body_en": "Midnights Turns Four with Fan Tributes and Record Reflections.\n\nFour years ago today, Taylor Swift dropped Midnights at midnight, surprising fans hours later with extra tracks that reset pop music expectations.\n\nThe 2022 album shattered records, including 184.7 million Spotify streams in its first day and the biggest U.S. opening week in years at No.\n\n1 on the Billboard 200. Ten tracks hit the Hot 100 top 10 at once, with Anti-Hero leading, and it later won Album of the Year at the 2024 Grammys—Swift's fourth in the category. Fans are sharing memories of the rollout, praising moody synth-pop and deep cuts like Maroon, while noting its role in boosting women's achievements and launching 'Taylormania.'", "body_zh": "四年前的今天，泰勒·斯威夫特（ Taylor Swift ）在午夜放弃了《午夜》（ Midnights ） ，几个小时后，歌迷们惊讶地发现了额外的曲目\n\n2022年的专辑打破了记录，包括第一天的1.847亿个Spotify流媒体，以及Billboard 200上多年来最大的美国开幕周。\n\n十首歌曲同时进入Hot 100前十名，反英雄领先，后来在2024年格莱美-斯威夫特的第四张同类专辑中获得年度专辑奖。粉丝们正在分享推出的回忆，称赞喜怒无常的合成流行音乐和像Maroon这样的深度剪辑，同时注意到它在提升女性成就和推出“Taylormania”方面的作用。"}, {"id": "2112946152933089721", "domain": "娱乐", "url": "https://x.com/i/trending/2112946152933089721", "category": "Entertainment", "topics": ["Music", "Country"], "updated_at": "2026-10-21T19:29:57.000Z", "title_en": "CMA Tribute Special Honors Dolly Parton Tonight on ABC", "title_zh": "CMA致敬特别荣誉Dolly Parton今晚在ABC", "hook_en": "Country music lovers are gathering their tissues for an emotional night celebrating Dolly Parton's incredible life and legacy.", "hook_zh": "乡村音乐爱好者正在聚集他们的组织，庆祝多莉·帕顿（ Dolly Parton ）令人难以置信的生活和遗产。", "summary_en": "The Country Music Association airs 'CMA Presents I Will Always Love You: A Celebration of Dolly Parton' live at 9 p.m. ET on ABC and Disney+, nearly two months after her passing on August 25 at age 80 from cancer. Stars like Carrie Underwood, Reba McEntire, Kelsea Ballerini, and even Bono will perform her classics at Belmont University in Nashville, with special guests including Oprah Winfrey and Julia Roberts sharing stories. Proceeds support her Imagination Library, delivering free books to kids, making it a heartfelt nod to her music, rise from the Smoky Mountains, and philanthropy.", "summary_zh": "乡村音乐协会于美国东部时间晚上9点在美国广播公司和迪士尼+直播“CMA Presents I Will Always Love You: A Celebration of Dolly Parton” ，距离她于8月25日因癌症去世将近两个月。Carrie Underwood、Reba McEntire、Kelsea Ballerini甚至Bono等明星将在纳什维尔的贝尔蒙特大学演出她的经典作品，特别嘉宾包括Oprah Winfrey和Julia Roberts将分享她的故事。 收益支持她的Imagination Library ，为孩子们提供免费书籍，使其成为对她的音乐、从烟雾山脉崛起和慈善事业的衷心致意。", "body_en": "CMA Tribute Special Honors Dolly Parton Tonight on ABC.\n\nCountry music lovers are gathering their tissues for an emotional night celebrating Dolly Parton's incredible life and legacy.\n\nThe Country Music Association airs 'CMA Presents I Will Always Love You: A Celebration of Dolly Parton' live at 9 p.m. ET on ABC and Disney+, nearly two months after her passing on August 25 at age 80 from cancer.\n\nStars like Carrie Underwood, Reba McEntire, Kelsea Ballerini, and even Bono will perform her classics at Belmont University in Nashville, with special guests including Oprah Winfrey and Julia Roberts sharing stories. Proceeds support her Imagination Library, delivering free books to kids, making it a heartfelt nod to her music, rise from the Smoky Mountains, and philanthropy.", "body_zh": "乡村音乐爱好者正在聚集他们的组织，庆祝多莉·帕顿（ Dolly Parton ）令人难以置信的生活和遗产。\n\n乡村音乐协会于美国东部时间晚上9点在美国广播公司和迪士尼+直播“CMA Presents I Will Always Love You: A Celebration of Dolly Parton” ，距离她于8月25日因癌症去世将近两个月。\n\nCarrie Underwood、Reba McEntire、Kelsea Ballerini甚至Bono等明星将在纳什维尔的贝尔蒙特大学演出她的经典作品，特别嘉宾包括Oprah Winfrey和Julia Roberts将分享她的故事。收益支持她的Imagination Library ，为孩子们提供免费书籍，使其成为对她的音乐、从烟雾山脉崛起和慈善事业的衷心致意。"}, {"id": "2112846851909239030", "domain": "娱乐", "url": "https://x.com/i/trending/2112846851909239030", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T19:29:19.000Z", "title_en": "Jeff Satur Signs with Universal Music Southeast Asia", "title_zh": "Jeff Satur与东南亚环球音乐签约", "hook_en": "Jeff Satur's simple 'Hello Universe' post captured the thrill of joining a global music powerhouse, kicking off a cosmic new era for the Thai star.", "hook_zh": "Jeff Satur的简单“Hello Universe”帖子捕捉到了加入全球音乐巨头的快感，开启了泰国明星的宇宙新时代。", "summary_en": "Universal Music Southeast Asia welcomed Jeff Satur with the tagline 'SATURN HAS ENTERED THE UNIVERSE,' announcing his signing on October 21 to boost T-Pop worldwide. The deal brings a new single on October 29, a second studio album in 2027, a stadium concert in Bangkok, and a world tour from late 2027 to 2028, backed by full global support. Satur, with over 2 billion streams and hits like 'Fade' and 'Ghost,' expressed excitement about a partner that matches his vision, while executives hail him as poised to become T-Pop's first global superstar.", "summary_zh": "东南亚环球音乐以“土星已经进入宇宙”的标语迎接杰夫·萨特，并于10月21日宣布签约，在全球范围内推广T-Pop。这笔交易带来了10月29日的新单曲， 2027年的第二张录音室专辑，曼谷的体育场音乐会，以及2027年底至2028年的世界巡回演唱会，并得到了全球的全力支持。 周六，拥有超过20亿条流媒体和“Fade”和“Ghost”等热门歌曲，表达了对与他的愿景相匹配的合作伙伴的兴奋，而高管们则称赞他有望成为T-Pop的第一位全球超级巨星。", "body_en": "Jeff Satur Signs with Universal Music Southeast Asia.\n\nJeff Satur's simple 'Hello Universe' post captured the thrill of joining a global music powerhouse, kicking off a cosmic new era for the Thai star.\n\nUniversal Music Southeast Asia welcomed Jeff Satur with the tagline 'SATURN HAS ENTERED THE UNIVERSE,' announcing his signing on October 21 to boost T-Pop worldwide.\n\nThe deal brings a new single on October 29, a second studio album in 2027, a stadium concert in Bangkok, and a world tour from late 2027 to 2028, backed by full global support. Satur, with over 2 billion streams and hits like 'Fade' and 'Ghost,' expressed excitement about a partner that matches his vision, while executives hail him as poised to become T-Pop's first global superstar.", "body_zh": "Jeff Satur的简单“Hello Universe”帖子捕捉到了加入全球音乐巨头的快感，开启了泰国明星的宇宙新时代。\n\n东南亚环球音乐以“土星已经进入宇宙”的标语迎接杰夫·萨特，并于10月21日宣布签约，在全球范围内推广T-Pop。\n\n这笔交易带来了10月29日的新单曲， 2027年的第二张录音室专辑，曼谷的体育场音乐会，以及2027年底至2028年的世界巡回演唱会，并得到了全球的全力支持。周六，拥有超过20亿条流媒体和“Fade”和“Ghost”等热门歌曲，表达了对与他的愿景相匹配的合作伙伴的兴奋，而高管们则称赞他有望成为T-Pop的第一位全球超级巨星。"}, {"id": "2112977632723607782", "domain": "娱乐", "url": "https://x.com/i/trending/2112977632723607782", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T18:51:48.000Z", "title_en": "Netflix Adds First Three Seasons of 'From' Ahead of Halloween", "title_zh": "Netflix在万圣节前增加了“From”的前三季", "hook_en": "Strangers trapped in a town they can't escape, with monsters lurking every night—that's the grip of 'From,' now streaming on Netflix for a new crowd.", "hook_zh": "陌生人被困在一个他们无法逃脱的小镇上，每天晚上都有怪物潜伏在这里--这就是《From》的魅力所在，现在Netflix上正在为新的观众提供流媒体服务。", "summary_en": "Netflix brought seasons one through three of the sci-fi horror series 'From' to its U.S. library on October 19, letting viewers dive into the mystery of a inescapable town and its nightly terrors. Harold Perrineau plays Boyd Stevens, the leader keeping the community together amid the chaos. Fans are thrilled for newcomers to join, sharing stories of past binge struggles, though season four stays on MGM+ and the final season arrives there in 2027. The timing fits perfectly with Halloween, drawing fresh enthusiasm for the slow-burn puzzle that premiered in 2022.", "summary_zh": "10月19日， Netflix将科幻恐怖系列“From”的第一季至第三季带到了其美国图书馆，让观众深入了解一个不可避免的小镇的奥秘及其夜间恐怖。Harold Perrineau扮演博伊德·史蒂文斯（ Boyd Stevens ） ，在混乱中保持社区团结的领导者。粉丝们很高兴新人加入，分享过去狂欢挣扎的故事，尽管第四季在MGM +上停留，最后一季将在2027年到达那里。 这个时机与万圣节完美契合，为2022年首次亮相的慢火拼图带来了新的热情。", "body_en": "Netflix Adds First Three Seasons of 'From' Ahead of Halloween.\n\nStrangers trapped in a town they can't escape, with monsters lurking every night—that's the grip of 'From,' now streaming on Netflix for a new crowd.\n\nNetflix brought seasons one through three of the sci-fi horror series 'From' to its U.S. library on October 19, letting viewers dive into the mystery of a inescapable town and its nightly terrors.\n\nHarold Perrineau plays Boyd Stevens, the leader keeping the community together amid the chaos. Fans are thrilled for newcomers to join, sharing stories of past binge struggles, though season four stays on MGM+ and the final season arrives there in 2027. The timing fits perfectly with Halloween, drawing fresh enthusiasm for the slow-burn puzzle that premiered in 2022.", "body_zh": "陌生人被困在一个他们无法逃脱的小镇上，每天晚上都有怪物潜伏在这里--这就是《From》的魅力所在，现在Netflix上正在为新的观众提供流媒体服务。\n\n10月19日， Netflix将科幻恐怖系列“From”的第一季至第三季带到了其美国图书馆，让观众深入了解一个不可避免的小镇的奥秘及其夜间恐怖。Harold Perrineau扮演博伊德·史蒂文斯（ Boyd Stevens ） ，在混乱中保持社区团结的领导者。\n\n粉丝们很高兴新人加入，分享过去狂欢挣扎的故事，尽管第四季在MGM +上停留，最后一季将在2027年到达那里。这个时机与万圣节完美契合，为2022年首次亮相的慢火拼图带来了新的热情。"}, {"id": "2112840787054743961", "domain": "娱乐", "url": "https://x.com/i/trending/2112840787054743961", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T18:23:24.000Z", "title_en": "Moonlight Marks 10 Years Since U.S. Debut and Oscar Glory", "title_zh": "Moonlight标志着美国首次亮相和奥斯卡辉煌10周年", "hook_en": "Ten years ago today, Barry Jenkins' Moonlight quietly arrived in U.S. theaters, forever changing conversations about identity and love through its tender gaze on a young man's life in Miami.", "hook_zh": "十年前的今天，巴里·詹金斯（ Barry Jenkins ）的《月光》（ Moonlight ）悄然抵达美国影院，通过它对迈阿密一个年轻人生活的温柔注视，永远改变了有关身份和爱的对话。", "summary_en": "Released on October 21, 2016, by A24, the film follows Chiron from childhood to adulthood across three chapters, earning three Oscars including Best Picture as the first with an all-Black cast and LGBT theme. Standout performances by Mahershala Ali, Naomie Harris, Trevante Rhodes, Ashton Sanders, and Jharrel Jerome, paired with luminous cinematography and Nicholas Britell's score, turned its $1.5 million budget into $67 million worldwide and lasting praise. This week, Netflix added it to its U.S. library while a 4K remaster returned to theaters, as fans share personal stories of its themes of vulnerability and self-acceptance.", "summary_zh": "这部电影于2016年10月21日由A24发行，讲述了凯龙星从童年到成年的三个章节，获得了三项奥斯卡奖，其中包括第一部全黑演员和LGBT主题的最佳影片。 Mahershala Ali、Naomie Harris、Trevante Rhodes、Ashton Sanders和Jharrel Jerome的杰出表演，加上明亮的电影摄影和Nicholas Britell的配乐，使其150万美元的预算在全球范围内获得了6700万美元的持久赞誉。本周， Netflix将其添加到其美国图书馆，同时4K重制版重返影院，因为粉丝们分享了其脆弱性和自我接受主题的个人故事。", "body_en": "Ten years ago today, Barry Jenkins' Moonlight quietly arrived in U.S. theaters, forever changing conversations about identity and love through its tender gaze on a young man's life in Miami.\n\nReleased on October 21, 2016, by A24, the film follows Chiron from childhood to adulthood across three chapters, earning three Oscars including Best Picture as the first with an all-Black cast and LGBT theme. Standout performances by Mahershala Ali, Naomie Harris, Trevante Rhodes, Ashton Sanders, and Jharrel Jerome, paired with luminous cinematography and Nicholas Britell's score, turned its $1.5 million budget into $67 million worldwide and lasting praise.\n\nThis week, Netflix added it to its U.S. library while a 4K remaster returned to theaters, as fans share personal stories of its themes of vulnerability and self-acceptance.", "body_zh": "十年前的今天，巴里·詹金斯（ Barry Jenkins ）的《月光》（ Moonlight ）悄然抵达美国影院，通过它对迈阿密一个年轻人生活的温柔注视，永远改变了有关身份和爱的对话。\n\n这部电影于2016年10月21日由A24发行，讲述了凯龙星从童年到成年的三个章节，获得了三项奥斯卡奖，其中包括第一部全黑演员和LGBT主题的最佳影片。\n\nMahershala Ali、Naomie Harris、Trevante Rhodes、Ashton Sanders和Jharrel Jerome的杰出表演，加上明亮的电影摄影和Nicholas Britell的配乐，使其150万美元的预算在全球范围内获得了6700万美元的持久赞誉。本周， Netflix将其添加到其美国图书馆，同时4K重制版重返影院，因为粉丝们分享了其脆弱性和自我接受主题的个人故事。"}, {"id": "2112928295297921465", "domain": "娱乐", "url": "https://x.com/i/trending/2112928295297921465", "category": "Entertainment", "topics": ["K-pop"], "updated_at": "2026-10-21T17:59:48.000Z", "title_en": "Jungkook Shares Intimate Black-and-White Photos of Taehyung on Instagram", "title_zh": "Jungkook在Instagram上分享Taehyung的亲密黑白照片", "hook_en": "Jungkook captured his BTS bandmate Taehyung in relaxed, artistic black-and-white shots, lounging on a wooden table with tousled hair and an expressive gaze.", "hook_zh": "Jungkook以轻松、艺术的黑白镜头捕捉了他的BTS乐队成员Taehyung ，躺在木桌上，头发乱糟糟，目光敏锐。", "summary_en": "The photos, set to Taehyung’s song “Love Me Again,” feature him in a dark sweatshirt and jeans, holding a bottle in some frames for a personal, cinematic vibe. Jungkook captioned them “🐰: cherished model” or “애착 모델” in Korean, a tender term evoking deep emotional attachment like a child's favorite toy. Taehyung liked the post and shared it to his Instagram story, while fans praised the genuine tribute to their close bond. This fits Jungkook’s habit of photographing candid moments of those near him.", "summary_zh": "这些照片以Taehyung的歌曲“Love Me Again”为背景，他穿着深色运动衫和牛仔裤，在一些镜框中拿着一个瓶子，营造出个人的电影氛围。Jungkook用韩语为它们加上了“🐰: cherished model”或“애착 모델”的字幕，这是一个温柔的术语，唤起了深刻的情感依恋，就像孩子最喜欢的玩具一样。Taehyung喜欢这个帖子，并将其分享到他的Instagram故事中，而粉丝们则赞扬了他们对亲密关系的真诚致敬。 这符合Jungkook拍摄身边人的坦诚时刻的习惯。", "body_en": "Jungkook Shares Intimate Black-and-White Photos of Taehyung on Instagram.\n\nJungkook captured his BTS bandmate Taehyung in relaxed, artistic black-and-white shots, lounging on a wooden table with tousled hair and an expressive gaze.\n\nThe photos, set to Taehyung’s song “Love Me Again,” feature him in a dark sweatshirt and jeans, holding a bottle in some frames for a personal, cinematic vibe. Jungkook captioned them “🐰: cherished model” or “애착 모델” in Korean, a tender term evoking deep emotional attachment like a child's favorite toy.\n\nTaehyung liked the post and shared it to his Instagram story, while fans praised the genuine tribute to their close bond. This fits Jungkook’s habit of photographing candid moments of those near him.", "body_zh": "Jungkook以轻松、艺术的黑白镜头捕捉了他的BTS乐队成员Taehyung ，躺在木桌上，头发乱糟糟，目光敏锐。\n\n这些照片以Taehyung的歌曲“Love Me Again”为背景，他穿着深色运动衫和牛仔裤，在一些镜框中拿着一个瓶子，营造出个人的电影氛围。Jungkook用韩语为它们加上了“🐰: cherished model”或“애착 모델”的字幕，这是一个温柔的术语，唤起了深刻的情感依恋，就像孩子最喜欢的玩具一样。\n\nTaehyung喜欢这个帖子，并将其分享到他的Instagram故事中，而粉丝们则赞扬了他们对亲密关系的真诚致敬。这符合Jungkook拍摄身边人的坦诚时刻的习惯。"}, {"id": "2112531871284298135", "domain": "娱乐", "url": "https://x.com/i/trending/2112531871284298135", "category": "Entertainment", "topics": ["Music", "K-pop"], "updated_at": "2026-10-21T17:58:41.000Z", "title_en": "P1Harmony Unveils Spy-Themed Photos for 'BLOW UP' Mini Album", "title_zh": "P1Harmony推出“BLOW UP”迷你专辑的间谍主题照片", "hook_en": "P1Harmony's members strike sleek poses in black suits, channeling a hero-agency vibe that has fans eagerly awaiting their November 6 comeback.", "hook_zh": "P1Harmony的成员穿着黑色西装摆出时尚的姿势，营造出英雄机构的氛围，让粉丝们热切期待11月6日的复出。", "summary_en": "The group released striking concept photos for their 10th mini album 'BLOW UP,' showing Jongseob with pink hair and a laptop, Soul in sunglasses on a starry blue backdrop, and others with badges, bubblegum, or red gloves. The 'FINAL MISSION COMPLETE' trailer and images tie into a 'hero society' theme about growing bigger with fans, with Keeho composing a track and Intak and Jongseob writing lyrics. A packed schedule includes daily jacket drops, a concept film, music video teaser, and a 'HERO SOCIETY INFO SESSION' on November 4, building hype for the 2 p.m. KST release with photobook and wallet editions available for pre-order.", "summary_zh": "该乐队为他们的第10张迷你专辑“BLOW UP”发布了引人注目的概念照片，展示了Jongseob的粉红色头发和笔记本电脑， Soul在星光熠熠的蓝色背景上戴着太阳镜，以及其他戴着徽章，泡泡糖或红色手套的人。“最终任务完成”的预告片和图像与“英雄社会”主题联系在一起，即与粉丝一起成长壮大， Keeho创作了一首曲目， Intak和Jongseob写了歌词。 包装好的时间表包括每日外套、概念电影、音乐视频预告片和11月4日的“英雄社会信息会” ，为下午2点韩国标准时间发布会打造炒作，并提供摄影书和钱包版本可供预订。", "body_en": "P1Harmony's members strike sleek poses in black suits, channeling a hero-agency vibe that has fans eagerly awaiting their November 6 comeback.\n\nThe group released striking concept photos for their 10th mini album 'BLOW UP,' showing Jongseob with pink hair and a laptop, Soul in sunglasses on a starry blue backdrop, and others with badges, bubblegum, or red gloves. The 'FINAL MISSION COMPLETE' trailer and images tie into a 'hero society' theme about growing bigger with fans, with Keeho composing a track and Intak and Jongseob writing lyrics.\n\nA packed schedule includes daily jacket drops, a concept film, music video teaser, and a 'HERO SOCIETY INFO SESSION' on November 4, building hype for the 2 p.m. KST release with photobook and wallet editions available for pre-order.", "body_zh": "P1Harmony的成员穿着黑色西装摆出时尚的姿势，营造出英雄机构的氛围，让粉丝们热切期待11月6日的复出。\n\n该乐队为他们的第10张迷你专辑“BLOW UP”发布了引人注目的概念照片，展示了Jongseob的粉红色头发和笔记本电脑， Soul在星光熠熠的蓝色背景上戴着太阳镜，以及其他戴着徽章，泡泡糖或红色手套的人。\n\n“最终任务完成”的预告片和图像与“英雄社会”主题联系在一起，即与粉丝一起成长壮大， Keeho创作了一首曲目， Intak和Jongseob写了歌词。包装好的时间表包括每日外套、概念电影、音乐视频预告片和11月4日的“英雄社会信息会” ，为下午2点韩国标准时间发布会打造炒作，并提供摄影书和钱包版本可供预订。"}, {"id": "2112630069361570032", "domain": "娱乐", "url": "https://x.com/i/trending/2112630069361570032", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:48:00.000Z", "title_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories", "title_zh": "金球奖将迈克尔·杰克逊的传记片列入戏剧类", "hook_en": "Jaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.", "hook_zh": "贾法尔·杰克逊（ Jaafar Jackson ）在迈克尔·杰克逊（ Michael Jackson ）的传记片中扮演叔叔的角色，但金球奖刚刚将其颁奖之路转向了更艰难的戏剧领域。", "summary_en": "Lionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot. Fans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "summary_zh": "Lionsgate希望在2027年金球奖的喜剧或音乐类别中加入“Michael” ，但组织者裁定它适合戏剧，让Jaafar Jackson与Christopher Nolan的“The Odyssey”和“La Bola Negra”中的明星对抗。这一决定遵循了“猫王”和“波西米亚狂想曲”等音乐传记片的严格规则，除非歌曲驱动情节，否则这些传记片不再符合音乐剧的资格。 球迷们对这一呼吁进行了辩论，泰姬·杰克逊（ Taj Jackson ）对这一逻辑提出质疑，而贾法尔（ Jaafar ）备受赞誉的表现则密切关注他的戏剧演员机会；狮门（ Lionsgate ）可能会在10月31日之前提出上诉，", "body_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories.\n\nJaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.\n\nLionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot.\n\nFans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "body_zh": "贾法尔·杰克逊（ Jaafar Jackson ）在迈克尔·杰克逊（ Michael Jackson ）的传记片中扮演叔叔的角色，但金球奖刚刚将其颁奖之路转向了更艰难的戏剧领域。\n\nLionsgate希望在2027年金球奖的喜剧或音乐类别中加入“Michael” ，但组织者裁定它适合戏剧，让Jaafar Jackson与Christopher Nolan的“The Odyssey”和“La Bola Negra”中的明星对抗。\n\n这一决定遵循了“猫王”和“波西米亚狂想曲”等音乐传记片的严格规则，除非歌曲驱动情节，否则这些传记片不再符合音乐剧的资格。球迷们对这一呼吁进行了辩论，泰姬·杰克逊（ Taj Jackson ）对这一逻辑提出质疑，而贾法尔（ Jaafar ）备受赞誉的表现则密切关注他的戏剧演员机会；狮门（ Lionsgate ）可能会在10月31日之前提出上诉，"}, {"id": "2112961308597338219", "domain": "娱乐", "url": "https://x.com/i/trending/2112961308597338219", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:47:24.000Z", "title_en": "Kid Cudi to Write, Direct and Star in Jean-Michel Basquiat Biopic", "title_zh": "Kid Cudi将在Jean-Michel Basquiat传记片中撰写、导演和主演", "hook_en": "Kid Cudi grabbed the pen after years of others pitching him as Jean-Michel Basquiat. Now he's making 'JEAN' his own way, with filming set for 2027.", "hook_zh": "多年来，其他人一直把他称为让-米歇尔·巴斯奎特（ Jean-Michel Basquiat ） ，库迪小子抓住了笔。现在，他正在按照自己的方式拍摄《吉恩》，拍摄时间定在2027年。", "summary_en": "The musician explained he took charge because no one else followed through: 'This year, I finally said f*ck it, ima write it myself.' Promotional images show Cudi channeling Basquiat's dramatic style in tailored suits, earning praise from fans who see a natural fit from their shared creative journeys. Cudi calls the film a love letter to Basquiat, 1980s New York, building on his directing experience with projects like 'Doe.' While some wonder about capturing Basquiat's essence after the 1996 film, many welcome this personal take.", "summary_zh": "这位音乐家解释说，他负责是因为没有其他人跟进： “今年，我终于说他妈的， ima自己写的。“宣传图片显示， Cudi穿着量身定制的西装，演绎巴斯奎特的戏剧风格，赢得了粉丝们的赞誉，他们从共同的创意之旅中看到了自然契合。 库迪称这部电影是20世纪80年代纽约巴斯奎特的情书，借鉴了他在“Doe”等项目中的导演经验。“虽然有些人想知道在1996年的电影后如何捕捉巴斯奎特的精髓，但许多人对这种个人摄影表示欢迎。", "body_en": "Kid Cudi to Write, Direct and Star in Jean-Michel Basquiat Biopic.\n\nKid Cudi grabbed the pen after years of others pitching him as Jean-Michel Basquiat. Now he's making 'JEAN' his own way, with filming set for 2027.\n\nThe musician explained he took charge because no one else followed through: 'This year, I finally said f*ck it, ima write it myself.' Promotional images show Cudi channeling Basquiat's dramatic style in tailored suits, earning praise from fans who see a natural fit from their shared creative journeys.\n\nCudi calls the film a love letter to Basquiat, 1980s New York, building on his directing experience with projects like 'Doe.' While some wonder about capturing Basquiat's essence after the 1996 film, many welcome this personal take.", "body_zh": "多年来，其他人一直把他称为让-米歇尔·巴斯奎特（ Jean-Michel Basquiat ） ，库迪小子抓住了笔。现在，他正在按照自己的方式拍摄《吉恩》，拍摄时间定在2027年。\n\n这位音乐家解释说，他负责是因为没有其他人跟进： “今年，我终于说他妈的， ima自己写的。“宣传图片显示， Cudi穿着量身定制的西装，演绎巴斯奎特的戏剧风格，赢得了粉丝们的赞誉，他们从共同的创意之旅中看到了自然契合。\n\n库迪称这部电影是20世纪80年代纽约巴斯奎特的情书，借鉴了他在“Doe”等项目中的导演经验。“虽然有些人想知道在1996年的电影后如何捕捉巴斯奎特的精髓，但许多人对这种个人摄影表示欢迎。"}, {"id": "2112954859318329545", "domain": "娱乐", "url": "https://x.com/i/trending/2112954859318329545", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T17:22:57.000Z", "title_en": "Vijay Antony Music Secures AppaKutty Audio Rights Ahead of Diwali", "title_zh": "Vijay Antony Music在排灯节前保护AppaKutty音频权利", "hook_en": "A father and daughter share headphones at sunset in the film's warm posters, capturing the heartfelt bond at the center of this family entertainer.", "hook_zh": "在日落时分，一位父亲和女儿在电影温暖的海报上分享耳机，捕捉到这位家庭艺人中心的衷心纽带。", "summary_en": "Vijay Antony stars with Preethi Asrani in the action-family drama AppaKutty, directed by Mu Maran, with Antony also composing the music and editing under his Vijay Antony Film Corporation. The audio rights went to Vijay Antony Music, confirmed across industry channels on October 21, as the movie gears up for a worldwide theatrical release on November 6 during Diwali. Promotional posters highlight the emotional father-daughter story, and theatrical rights in key markets like Tamil Nadu are already with distributor 5 Star Senthil, positioning it as a major festive release in South Indian cinema.", "summary_zh": "Vijay Antony在Mu Maran执导的动作家庭剧《AppaKutty》中饰演Preethi Asrani ， Antony还在他的Vijay Antony电影公司下创作音乐和编辑。音频版权归维贾伊·安东尼音乐公司（ Vijay Antony Music ）所有，该公司于10月21日通过行业频道确认，因为这部电影将于11月6日在排灯节期间在全球上映。 宣传海报突出了情感的父女故事，泰米尔纳德邦等主要市场的戏剧版权已经与经销商5 Star Senthil合作，将其定位为南印度电影的主要节日发行。", "body_en": "Vijay Antony Music Secures AppaKutty Audio Rights Ahead of Diwali.\n\nA father and daughter share headphones at sunset in the film's warm posters, capturing the heartfelt bond at the center of this family entertainer.\n\nVijay Antony stars with Preethi Asrani in the action-family drama AppaKutty, directed by Mu Maran, with Antony also composing the music and editing under his Vijay Antony Film Corporation.\n\nThe audio rights went to Vijay Antony Music, confirmed across industry channels on October 21, as the movie gears up for a worldwide theatrical release on November 6 during Diwali. Promotional posters highlight the emotional father-daughter story, and theatrical rights in key markets like Tamil Nadu are already with distributor 5 Star Senthil, positioning it as a major festive release in South Indian cinema.", "body_zh": "在日落时分，一位父亲和女儿在电影温暖的海报上分享耳机，捕捉到这位家庭艺人中心的衷心纽带。\n\nVijay Antony在Mu Maran执导的动作家庭剧《AppaKutty》中饰演Preethi Asrani ， Antony还在他的Vijay Antony电影公司下创作音乐和编辑。\n\n音频版权归维贾伊·安东尼音乐公司（ Vijay Antony Music ）所有，该公司于10月21日通过行业频道确认，因为这部电影将于11月6日在排灯节期间在全球上映。宣传海报突出了情感的父女故事，泰米尔纳德邦等主要市场的戏剧版权已经与经销商5 Star Senthil合作，将其定位为南印度电影的主要节日发行。"}, {"id": "2112352804241285515", "domain": "娱乐", "url": "https://x.com/i/trending/2112352804241285515", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:07:08.000Z", "title_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music", "title_zh": "德维恩·约翰逊（ Dwayne Johnson ）变身为蜥蜴音乐的老鸡人", "hook_en": "Dwayne Johnson strolls New York streets with gray hair, a bushy beard, and a bucket hat, pizza in hand beside a child actor and giant lizard puppet. At 54, he's unrecognizable as the eccentric 70-year-old Chicken Man.", "hook_zh": "德维恩·约翰逊（ Dwayne Johnson ）在纽约街头漫步，头发灰白，蓄着浓密的胡须，戴着渔夫帽，手里拿着披萨，旁边是儿童演员和巨型蜥蜴木偶。54岁时，他无法辨认出这位古怪的70岁鸡人。", "summary_en": "Johnson stars in Lizard Music, Benny Safdie's adaptation of Daniel Pinkwater’s 1976 children’s book, playing a septuagenarian who joins a boy on a whimsical adventure after discovering lizards on late-night TV. Set photos capture him in full prosthetics with young co-star Theo Clark Leber, amid a stacked cast including Rachel McAdams, Jeff Goldblum, and Colman Domingo. The Amazon MGM Studios film wraps principal photography for a Christmas 2027 release, following Johnson's physical overhaul and prior work with Safdie on The Smashing Machine.", "summary_zh": "约翰逊主演了蜥蜴音乐，本尼·萨夫迪改编了丹尼尔·平克沃特（ Daniel Pinkwater ） 1976年的儿童书籍，扮演一名七十岁的老人，在深夜电视上发现蜥蜴后，他和一个男孩一起进行了一次异想天开的冒险。在雷切尔·麦克亚当斯（ Rachel McAdams ）、杰夫·戈德布鲁姆（ Jeff Goldblum ）和科尔曼·多明戈（ Colman Domingo ）等演员阵容中，与年轻的联合主演西奥·克拉克·莱伯（ Theo Clark Leber ）一起拍摄全假肢照片 Amazon MGM Studios电影在约翰逊的物理检修和之前与Safdie在The Smashing Machine上的合作之后，包装了2027年圣诞节的主要摄影作品。", "body_en": "Dwayne Johnson Transforms into Elderly Chicken Man for Lizard Music.\n\nDwayne Johnson strolls New York streets with gray hair, a bushy beard, and a bucket hat, pizza in hand beside a child actor and giant lizard puppet. At 54, he's unrecognizable as the eccentric 70-year-old Chicken Man.\n\nJohnson stars in Lizard Music, Benny Safdie's adaptation of Daniel Pinkwater’s 1976 children’s book, playing a septuagenarian who joins a boy on a whimsical adventure after discovering lizards on late-night TV.\n\nSet photos capture him in full prosthetics with young co-star Theo Clark Leber, amid a stacked cast including Rachel McAdams, Jeff Goldblum, and Colman Domingo. The Amazon MGM Studios film wraps principal photography for a Christmas 2027 release, following Johnson's physical overhaul and prior work with Safdie on The Smashing Machine.", "body_zh": "德维恩·约翰逊（ Dwayne Johnson ）在纽约街头漫步，头发灰白，蓄着浓密的胡须，戴着渔夫帽，手里拿着披萨，旁边是儿童演员和巨型蜥蜴木偶。54岁时，他无法辨认出这位古怪的70岁鸡人。\n\n约翰逊主演了蜥蜴音乐，本尼·萨夫迪改编了丹尼尔·平克沃特（ Daniel Pinkwater ） 1976年的儿童书籍，扮演一名七十岁的老人，在深夜电视上发现蜥蜴后，他和一个男孩一起进行了一次异想天开的冒险。在雷切尔·麦克亚当斯（ Rachel McAdams ）、杰夫·戈德布鲁姆（ Jeff Goldblum ）和科尔曼·多明戈（ Colman Domingo ）等演员阵容中，与年轻的联合主演西奥·克拉克·莱伯（ Theo Clark Leber ）一起拍摄全假肢照片 Amazon MGM Studios电影在约翰逊的物理检修和之前与Safdie在The Smashing Machine上的合作之后，包装了2027年圣诞节的主要摄影作品。"}, {"id": "2112874538631401605", "domain": "娱乐", "url": "https://x.com/i/trending/2112874538631401605", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T17:06:32.000Z", "title_en": "Bright Vachirawit Joins Luxury Leaders at Bangkok Summit", "title_zh": "Bright Vachirawit与奢侈品领袖一起参加曼谷峰会", "hook_en": "Bright Vachirawit stepped onto the stage in a black leather jacket, sharing heartfelt thoughts on style, music, and personal freedom amid global luxury talks.", "hook_zh": "Bright Vachirawit穿着黑色皮夹克走上舞台，在全球奢侈品谈话中分享关于风格、音乐和个人自由的衷心想法。", "summary_en": "At the Financial Times Business of Luxury Summit in Bangkok from October 19-20, Thai actor and singer Bright Vachirawit discussed Asia's growing role in luxury and culture alongside world leaders. He highlighted his favorite leather jacket, his upcoming album, and the importance of love and freedom in his life during the 'The Luxury Edit' session. Fans praised his sincere responses, while his presence spotlighted how Thai talents like him are influencing global trends in Thailand's expanding $4.4 billion luxury market.", "summary_zh": "在10月19日至20日在曼谷举行的《金融时报》奢侈品商业峰会上，泰国演员兼歌手Bright Vachirawit与世界领袖一起讨论了亚洲在奢侈品和文化方面日益重要的作用。在“The Luxury Edit”活动中，他强调了自己最喜欢的皮夹克、即将发行的专辑，以及爱和自由在他生活中的重要性。 球迷们称赞了他的真诚回应，而他的出席也凸显了像他这样的泰国人才如何影响泰国不断扩大的44 $十亿奢侈品市场的全球趋势。", "body_en": "Bright Vachirawit Joins Luxury Leaders at Bangkok Summit.\n\nBright Vachirawit stepped onto the stage in a black leather jacket, sharing heartfelt thoughts on style, music, and personal freedom amid global luxury talks.\n\nAt the Financial Times Business of Luxury Summit in Bangkok from October 19-20, Thai actor and singer Bright Vachirawit discussed Asia's growing role in luxury and culture alongside world leaders.\n\nHe highlighted his favorite leather jacket, his upcoming album, and the importance of love and freedom in his life during the 'The Luxury Edit' session. Fans praised his sincere responses, while his presence spotlighted how Thai talents like him are influencing global trends in Thailand's expanding $4.4 billion luxury market.", "body_zh": "Bright Vachirawit穿着黑色皮夹克走上舞台，在全球奢侈品谈话中分享关于风格、音乐和个人自由的衷心想法。\n\n在10月19日至20日在曼谷举行的《金融时报》奢侈品商业峰会上，泰国演员兼歌手Bright Vachirawit与世界领袖一起讨论了亚洲在奢侈品和文化方面日益重要的作用。\n\n在“The Luxury Edit”活动中，他强调了自己最喜欢的皮夹克、即将发行的专辑，以及爱和自由在他生活中的重要性。球迷们称赞了他的真诚回应，而他的出席也凸显了像他这样的泰国人才如何影响泰国不断扩大的44 $十亿奢侈品市场的全球趋势。"}, {"id": "2112946155130904714", "domain": "科学", "url": "https://x.com/i/trending/2112946155130904714", "category": "News", "topics": ["Business & Finance", "Technology", "Biotech"], "updated_at": "2026-10-21T19:57:20.000Z", "title_en": "Coherence Neuro Raises $45M for Adaptive Brain Cancer Implant", "title_zh": "Coherence Neuro为适应性脑癌植入物筹集了4500万美元$", "hook_en": "Co-founders Ben Woodington and Elise Jenkins are turning brain-computer tech into a smart implant that tracks and fights glioblastoma in real time. Jenkins celebrated the news simply: 'We did a thing!'", "hook_zh": "联合创始人本·伍丁顿（ Ben Woodington ）和伊丽莎白·詹金斯（ Elise Jenkins ）正在将脑机技术转变为一种智能植入物，可以实时跟踪和抗击胶质母细胞瘤。詹金斯只是简单地庆祝这个消息： “我们做了一件事！”", "summary_en": "The San Francisco startup raised $45 million in Series A funding, co-led by Founders Fund and OpenAI Startup Fund, to build the SOMA platform—a coin-sized skull implant that records tumor electrical signals, delivers targeted stimulation to disrupt growth, and adjusts via an app and wearable. It builds on early prototype tests in three patients at Royal Melbourne Hospital, confirming basic performance, with plans for longer-term trials in glioblastoma cases. Investors praised the team's rigorous approach to bioelectronic cancer therapy, which offers live disease tracking, while the company hires to expand in San Francisco and Cambridge, UK.", "summary_zh": "这家旧金山初创公司在Founders Fund和OpenAI Startup Fund的共同领导下筹集了4500万美元的A轮融资，用于构建SOMA平台，这是一个硬币大小的头骨植入物，可记录肿瘤电信号，提供有针对性的刺激以破坏增长，并通过应用程序和可穿戴设备进行调整。 它建立在皇家墨尔本医院三名患者的早期原型测试的基础上，确认了基本性能，并计划在胶质母细胞瘤病例中进行长期试验。投资者赞扬该团队对生物电子癌症治疗的严格方法，该方法提供实时疾病跟踪，而该公司则在旧金山和英国剑桥进行扩张。", "body_en": "Co-founders Ben Woodington and Elise Jenkins are turning brain-computer tech into a smart implant that tracks and fights glioblastoma in real time. Jenkins celebrated the news simply: 'We did a thing!'\n\nThe San Francisco startup raised $45 million in Series A funding, co-led by Founders Fund and OpenAI Startup Fund, to build the SOMA platform—a coin-sized skull implant that records tumor electrical signals, delivers targeted stimulation to disrupt growth, and adjusts via an app and wearable.\n\nIt builds on early prototype tests in three patients at Royal Melbourne Hospital, confirming basic performance, with plans for longer-term trials in glioblastoma cases. Investors praised the team's rigorous approach to bioelectronic cancer therapy, which offers live disease tracking, while the company hires to expand in San Francisco and Cambridge, UK.", "body_zh": "联合创始人本·伍丁顿（ Ben Woodington ）和伊丽莎白·詹金斯（ Elise Jenkins ）正在将脑机技术转变为一种智能植入物，可以实时跟踪和抗击胶质母细胞瘤。詹金斯只是简单地庆祝这个消息： “我们做了一件事！”\n\n这家旧金山初创公司在Founders Fund和OpenAI Startup Fund的共同领导下筹集了4500万美元的A轮融资，用于构建SOMA平台，这是一个硬币大小的头骨植入物，可记录肿瘤电信号，提供有针对性的刺激以破坏增长，并通过应用程序和可穿戴设备进行调整。\n\n它建立在皇家墨尔本医院三名患者的早期原型测试的基础上，确认了基本性能，并计划在胶质母细胞瘤病例中进行长期试验。投资者赞扬该团队对生物电子癌症治疗的严格方法，该方法提供实时疾病跟踪，而该公司则在旧金山和英国剑桥进行扩张。"}, {"id": "2112974495564865717", "domain": "科学", "url": "https://x.com/i/trending/2112974495564865717", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "Space"], "updated_at": "2026-10-21T19:43:52.000Z", "title_en": "SpaceX Shares Surge 15% on Record Q3 Profits and AI Boom", "title_zh": "SpaceX第三季度利润和人工智能热潮创纪录，股价飙升15%", "hook_en": "SpaceX just posted blockbuster third-quarter numbers, flipping a loss into $4.4 billion in net income and sending shares soaring over 15% to $163.", "hook_zh": "SpaceX刚刚公布了轰动一时的第三季度数据，亏损达到44亿美元的净收入，股价飙升超过15% ，至163美元。", "summary_en": "Revenue hit $14.6 billion, up 161% from last year, driven by $7.6 billion from its Super Intelligence AI segment, $5.2 billion from Starlink's 13.6 million subscribers, and $1.8 billion from launches. Wall Street responded fast, with JPMorgan doubling its price target to $500 and others like Cantor Fitzgerald and Barclays lifting theirs too. The strong results fueled merger talk with Tesla, as Elon Musk noted special committees are reviewing a potential combination for AI synergies, though he is recused and no deal is set.", "summary_zh": "收入达到146亿美元，比去年增长161% ，其中超级智能AI部门收入76亿美元， Starlink的1360万用户收入52亿美元，发布收入18亿美元。华尔街反应迅速，摩根大通将目标价翻了一番，达到500美元，康托尔·菲茨杰拉德(Cantor Fitzgerald)和巴克莱(Barclays)等其他公司也提高了目标价。 强劲的结果推动了与特斯拉的合并谈判，正如埃隆·马斯克（ Elon Musk ）指出的那样，特别委员会正在审查人工智能协同作用的潜在组合，尽管他被回避并且没有达成协议。", "body_en": "SpaceX Shares Surge 15% on Record Q3 Profits and AI Boom.\n\nSpaceX just posted blockbuster third-quarter numbers, flipping a loss into $4.4 billion in net income and sending shares soaring over 15% to $163.\n\nRevenue hit $14.6 billion, up 161% from last year, driven by $7.6 billion from its Super Intelligence AI segment, $5.2 billion from Starlink's 13.6 million subscribers, and $1.8 billion from launches.\n\nWall Street responded fast, with JPMorgan doubling its price target to $500 and others like Cantor Fitzgerald and Barclays lifting theirs too. The strong results fueled merger talk with Tesla, as Elon Musk noted special committees are reviewing a potential combination for AI synergies, though he is recused and no deal is set.", "body_zh": "SpaceX刚刚公布了轰动一时的第三季度数据，亏损达到44亿美元的净收入，股价飙升超过15% ，至163美元。\n\n收入达到146亿美元，比去年增长161% ，其中超级智能AI部门收入76亿美元， Starlink的1360万用户收入52亿美元，发布收入18亿美元。\n\n华尔街反应迅速，摩根大通将目标价翻了一番，达到500美元，康托尔·菲茨杰拉德(Cantor Fitzgerald)和巴克莱(Barclays)等其他公司也提高了目标价。强劲的结果推动了与特斯拉的合并谈判，正如埃隆·马斯克（ Elon Musk ）指出的那样，特别委员会正在审查人工智能协同作用的潜在组合，尽管他被回避并且没有达成协议。"}, {"id": "2112905930044317939", "domain": "科学", "url": "https://x.com/i/trending/2112905930044317939", "category": "News", "topics": ["Technology", "AI", "Biotech"], "updated_at": "2026-10-21T19:42:52.000Z", "title_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design", "title_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计", "hook_en": "Nobel laureate David Baker sees a new era: designing proteins from scratch, not just discovering nature's own. This tool makes it faster and more reliable than ever.", "hook_zh": "英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。", "summary_en": "NVIDIA and the University of Washington's Institute for Protein Design released RFD4-Proteina, an open model that generates proteins and biomolecules up to 13 times faster than prior tools like RFdiffusion3. Born from a year-long collaboration between Baker Lab and NVIDIA’s GenAIR team, it unifies amino acids, sugars, DNA, and RNA in one space, enabling designs for drug binders and enzymes—including one that helps synthesize the HIV drug lenacapavir. Fully open-source on GitHub and Hugging Face, with free GPU access for two weeks, it promises to boost fields from drug discovery to industrial enzymes and protein design competitions.", "summary_zh": "RFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "body_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design.\n\nScientists at NVIDIA and the University of Washington just dropped a powerful new AI tool that designs proteins quicker and better than before. It's already drawing cheers for speeding up drug discovery.\n\nRFD4-Proteina, born from a year-long collaboration between NVIDIA's GenAIR team and the Baker Lab at UW's Institute for Protein Design, co-designs protein sequences and structures in a shared latent space. It handles binder design, enzyme scaffolding, motif conditioning, and work with DNA, RNA, or small molecules, outperforming prior models in speed, quality, and wet-lab success rates.\n\nReleased open source on GitHub and Hugging Face at GTC Berlin, it's available as an NVIDIA NIM microservice and integrated with partners like Tamarind Bio for easy use. Researchers called the results 'astonishing' and a state-of-the-art leap for biology and medicine.", "body_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计。\n\n英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。\n\nRFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。\n\n该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。"}, {"id": "2112802744491000212", "domain": "科学", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T19:30:19.000Z", "title_en": "UN Report: 1.5°C Limit Unavoidable, But Overshoot Can Be Limited", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "The UN has delivered sobering news: the world will exceed the Paris Agreement's 1.5°C warming threshold. The focus now shifts to capping the rise and pulling temperatures back by century's end.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "A new UN Environment Programme report declares it impossible to stay below 1.5°C without overshoot, ahead of COP31 talks in Turkey. Current policies point to up to 2.8°C warming this century, while full national pledges would limit it to 2.6°C—worse than last year's outlook due to U.S. emissions rises and data revisions. To cap peak warming at 1.7–1.8°C mid-century with a fair shot at returning to 1.5°C by 2100, emissions must drop 18 percent by 2030 and 45 percent by 2035 from 2025 levels, plus massive carbon removal. UN leaders like António Guterres and Inger Andersen call for urgent cuts in coal, methane, and faster clean energy growth to avoid locking in worse impacts.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable.\n\nYears of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.\n\nThe UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal.\n\nCurrent pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。"}, {"id": "2112968032066920582", "domain": "科学", "url": "https://x.com/i/trending/2112968032066920582", "category": "News", "topics": ["News", "Science"], "updated_at": "2026-10-21T18:10:40.000Z", "title_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted", "title_zh": "回顾生物圈 2 号氧气危机与混乱任务", "hook_en": "Eight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.", "hook_zh": "八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。", "summary_en": "Biosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk. Pigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "summary_zh": "造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。", "body_en": "Biosphere 2's Oxygen Crisis and Chaotic Missions Recounted.\n\nEight people sealed themselves inside a massive glass world in Arizona, dreaming of self-sustaining life like on Mars. But falling oxygen and hungry goats turned their two-year stay into a survival test.\n\nBiosphere 2, a $150 million glass complex with rainforests, oceans, and farms, launched its first mission on September 26, 1991, with eight crew members facing sharp oxygen drops to 14% from soil microbes and food shortages that led to weight loss and reliance on goat milk.\n\nPigs were culled amid struggles, while the second 1994 mission achieved food self-sufficiency before bankers led by Steve Bannon took over, sparking a break-in by original crew and an early end. Today, the University of Arizona runs it as a research site, with the story's real dramas echoing the 1996 comedy Bio-Dome and lessons from the 2020 documentary Spaceship Earth.", "body_zh": "回顾生物圈 2 号氧气危机与混乱任务。\n\n八人把自己封进亚利桑那巨型玻璃世界，梦想如火星般自给自足；氧气下降与饥饿山羊却把两年驻留变成生存考验。\n\n造价约 1.5 亿美元、含雨林海洋与农场的生物圈 2 号，于 1991 年 9 月 26 日启动首次任务；八名乘员遭遇土壤微生物导致氧气骤降至 14%、食物短缺引发体重下降并依赖羊奶。\n\n猪只被扑杀，1994 年第二次任务曾实现食物自给，随后由史蒂夫·班农主导的银行方接管，原班成员破门而入，任务提前结束。如今由亚利桑那大学用作研究设施；真实波折呼应 1996 年喜剧《Bio-Dome》，也见于 2020 年纪录片《地球号飞船》的教训。"}, {"id": "2112930911151120733", "domain": "科学", "url": "https://x.com/i/trending/2112930911151120733", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T15:43:33.000Z", "title_en": "SpaceX Applies Rocket Casting to Speed Up Gas Turbines for AI Power", "title_zh": "SpaceX应用火箭铸造加速燃气轮机用于人工智能发电", "hook_en": "Elon Musk revealed a key industry bottleneck: turbine blades lag 12 to 18 months behind the rest of the machine. SpaceX's rocket engine expertise lets them leap ahead.", "hook_zh": "埃隆·马斯克（ Elon Musk ）揭示了一个关键的行业瓶颈：涡轮叶片落后于机器的其余部分12至18个月。SpaceX的火箭发动机专业知识让他们跃居前列。", "summary_en": "During the Q3 2026 earnings call, Musk explained how suppliers face casting delays for critical hot-section blades and vanes, slowing turbine production. SpaceX is using its advanced casting technology—originally for rocket engines—to build these parts in-house, enabling power capacity online 12 to 18 months faster than competitors. This supports rapid AI compute growth, with current 1.7 gigawatts scaling to 2.5-3 gigawatts by year-end and 10 more in 2027, including a new foundry in Bastrop, Texas.", "summary_zh": "在2026年第三季度的财报电话会议上，马斯克解释了供应商如何面临关键热型叶片和叶片的铸造延迟，从而减缓了涡轮机的生产。SpaceX正在使用其先进的铸造技术（最初用于火箭发动机）在内部制造这些零件，使在线功率容量比竞争对手快12至18个月。 这支持了人工智能计算的快速增长，目前的1.7千兆瓦到年底将扩展到2.5-3千兆瓦，到2027年将增加10千兆瓦，其中包括德克萨斯州巴斯特罗普的一家新铸造厂。", "body_en": "SpaceX Applies Rocket Casting to Speed Up Gas Turbines for AI Power.\n\nElon Musk revealed a key industry bottleneck: turbine blades lag 12 to 18 months behind the rest of the machine. SpaceX's rocket engine expertise lets them leap ahead.\n\nDuring the Q3 2026 earnings call, Musk explained how suppliers face casting delays for critical hot-section blades and vanes, slowing turbine production.\n\nSpaceX is using its advanced casting technology—originally for rocket engines—to build these parts in-house, enabling power capacity online 12 to 18 months faster than competitors. This supports rapid AI compute growth, with current 1.7 gigawatts scaling to 2.5-3 gigawatts by year-end and 10 more in 2027, including a new foundry in Bastrop, Texas.", "body_zh": "埃隆·马斯克（ Elon Musk ）揭示了一个关键的行业瓶颈：涡轮叶片落后于机器的其余部分12至18个月。SpaceX的火箭发动机专业知识让他们跃居前列。\n\n在2026年第三季度的财报电话会议上，马斯克解释了供应商如何面临关键热型叶片和叶片的铸造延迟，从而减缓了涡轮机的生产。\n\nSpaceX正在使用其先进的铸造技术（最初用于火箭发动机）在内部制造这些零件，使在线功率容量比竞争对手快12至18个月。这支持了人工智能计算的快速增长，目前的1.7千兆瓦到年底将扩展到2.5-3千兆瓦，到2027年将增加10千兆瓦，其中包括德克萨斯州巴斯特罗普的一家新铸造厂。"}, {"id": "2112613033243721837", "domain": "科学", "url": "https://x.com/i/trending/2112613033243721837", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T12:34:03.000Z", "title_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development", "title_zh": "OpenAI收购Orchestra Bio以加快药物开发", "hook_en": "OpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.", "hook_zh": "OpenAI刚刚引入了一个团队，致力于解决药物开发的混乱局面，将他们的专业知识整合到人工智能工具中，从而更快地为患者提供治疗。", "summary_en": "On October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk. Founder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "summary_zh": "2026年10月20日， OpenAI宣布收购Orchestra Bio ，这是一家成立四年的初创公司，帮助生物制药团队跟踪研究、时间表和失败的生产批次等挫折。该交易将Orchestra的平台整合到OpenAI的Rosalind套件中，该套件为Moderna和Novo Nordisk等客户的生物和化学推理提供支持。 创始人Ashoka Rajendra庆祝了公司成立周年的里程碑，很高兴能与OpenAI的人工智能代理一起扩大他们的使命。总裁格雷格·布罗克曼（ Greg Brockman ）称之为加速发现真正治疗方法的关键一步。", "body_en": "OpenAI Acquires Orchestra Bio to Speed Drug Development.\n\nOpenAI just brought in a team that's all about wrangling the chaos of drug development, folding their know-how into AI tools that could get treatments to patients faster.\n\nOn October 20, 2026, OpenAI announced it acquired Orchestra Bio, a four-year-old startup that helps biopharma teams track studies, timelines, and setbacks like failed manufacturing batches. The deal integrates Orchestra's platform into OpenAI's Rosalind suite, which powers biology and chemistry reasoning for customers including Moderna and Novo Nordisk.\n\nFounder Ashoka Rajendra celebrated the milestone on the company's anniversary, excited to scale their mission with OpenAI's AI agents. President Greg Brockman called it a key step in accelerating discoveries into real treatments.", "body_zh": "OpenAI刚刚引入了一个团队，致力于解决药物开发的混乱局面，将他们的专业知识整合到人工智能工具中，从而更快地为患者提供治疗。\n\n2026年10月20日， OpenAI宣布收购Orchestra Bio ，这是一家成立四年的初创公司，帮助生物制药团队跟踪研究、时间表和失败的生产批次等挫折。该交易将Orchestra的平台整合到OpenAI的Rosalind套件中，该套件为Moderna和Novo Nordisk等客户的生物和化学推理提供支持。\n\n创始人Ashoka Rajendra庆祝了公司成立周年的里程碑，很高兴能与OpenAI的人工智能代理一起扩大他们的使命。总裁格雷格·布罗克曼（ Greg Brockman ）称之为加速发现真正治疗方法的关键一步。"}, {"id": "2112826878222610489", "domain": "科学", "url": "https://x.com/i/trending/2112826878222610489", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T08:48:08.000Z", "title_en": "Biosphere 2's 1991 Experiment Relived Through Viral Account", "title_zh": "Biosphere 2 1991年通过病毒账户重现的实验", "hook_en": "Eight people sealed themselves in a massive glass dome in the Arizona desert, aiming to live off their own farm for two years. Two years in, just a handful of goats kept them reliably fed.", "hook_zh": "八人在亚利桑那州沙漠中的一个巨大的玻璃穹顶中将自己封闭起来，目标是靠自己的农场生活两年。两年后，只有少数山羊能够可靠地喂养它们。", "summary_en": "The $150 million Biosphere 2 project created a sealed world with rainforest, ocean, and farmland to test human self-sufficiency. Crew grew 80 percent of their calories from crops like sweet potatoes and bananas, supplemented by goats' milk, chickens' eggs, and pigs, but oxygen plunged to high-altitude levels from hungry soil microbes, forcing outside help. They lost 15-25 pounds each adapting to a lean diet that boosted some health markers, completing the mission with key lessons on closed ecosystems now studied at the University of Arizona.", "summary_zh": "耗资1.5亿美元的Biosphere 2项目创造了一个拥有热带雨林、海洋和农田的封闭世界，以测试人类的自给自足能力。船员80%的卡路里来自红薯和香蕉等作物，再加上山羊奶、鸡蛋和猪，但氧气从饥饿的土壤微生物中骤降到高海拔水平，迫使外界提供帮助。 他们每人减掉15-25磅，以适应瘦肉饮食，这增加了一些健康指标，完成了现在在亚利桑那大学学习的关于封闭生态系统的关键课程的使命。", "body_en": "Eight people sealed themselves in a massive glass dome in the Arizona desert, aiming to live off their own farm for two years. Two years in, just a handful of goats kept them reliably fed.\n\nThe $150 million Biosphere 2 project created a sealed world with rainforest, ocean, and farmland to test human self-sufficiency.\n\nCrew grew 80 percent of their calories from crops like sweet potatoes and bananas, supplemented by goats' milk, chickens' eggs, and pigs, but oxygen plunged to high-altitude levels from hungry soil microbes, forcing outside help. They lost 15-25 pounds each adapting to a lean diet that boosted some health markers, completing the mission with key lessons on closed ecosystems now studied at the University of Arizona.", "body_zh": "八人在亚利桑那州沙漠中的一个巨大的玻璃穹顶中将自己封闭起来，目标是靠自己的农场生活两年。两年后，只有少数山羊能够可靠地喂养它们。\n\n耗资1.5亿美元的Biosphere 2项目创造了一个拥有热带雨林、海洋和农田的封闭世界，以测试人类的自给自足能力。\n\n船员80%的卡路里来自红薯和香蕉等作物，再加上山羊奶、鸡蛋和猪，但氧气从饥饿的土壤微生物中骤降到高海拔水平，迫使外界提供帮助。他们每人减掉15-25磅，以适应瘦肉饮食，这增加了一些健康指标，完成了现在在亚利桑那大学学习的关于封闭生态系统的关键课程的使命。"}, {"id": "2112633707806724247", "domain": "科学", "url": "https://x.com/i/trending/2112633707806724247", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T07:23:23.000Z", "title_en": "Musk Proposes Hotter AI Chips for Space Data Centers", "title_zh": "马斯克为太空数据中心提出更热门的AI芯片", "hook_en": "Elon Musk envisions AI chips in orbit running hotter to shed radiator weight, making space computing lighter and cheaper.", "hook_zh": "埃隆·马斯克（ Elon Musk ）设想在轨道上运行更热的人工智能芯片，以减轻散热器的重量，从而使空间计算更轻、更便宜。", "summary_en": "In a video clip, Musk explained that boosting chip operating temperature by 20% in Kelvin could halve radiator mass, relying on the Stefan-Boltzmann law where radiated power scales with temperature to the fourth power. He noted neural networks tolerate radiation bit flips better than traditional programs, reducing shielding needs for SpaceX's orbital AI plans like AI1 satellites. Online views split between critics questioning his expertise and supporters praising the physics-backed logic, highlighting space AI's engineering challenges.", "summary_zh": "在一段视频中，马斯克解释说，根据斯特凡-玻尔兹曼定律，将开尔文芯片的工作温度提高20 ％可以将散热器质量减半，其中辐射功率随温度升至第四功率。他指出，神经网络比传统程序更能容忍辐射位翻转，从而减少了SpaceX的AI1卫星等轨道AI计划的屏蔽需求。 在线观点分为质疑他的专业知识的批评者和赞扬物理学支持的逻辑的支持者，突出了太空人工智能的工程挑战。", "body_en": "Musk Proposes Hotter AI Chips for Space Data Centers.\n\nElon Musk envisions AI chips in orbit running hotter to shed radiator weight, making space computing lighter and cheaper.\n\nIn a video clip, Musk explained that boosting chip operating temperature by 20% in Kelvin could halve radiator mass, relying on the Stefan-Boltzmann law where radiated power scales with temperature to the fourth power.\n\nHe noted neural networks tolerate radiation bit flips better than traditional programs, reducing shielding needs for SpaceX's orbital AI plans like AI1 satellites. Online views split between critics questioning his expertise and supporters praising the physics-backed logic, highlighting space AI's engineering challenges.", "body_zh": "埃隆·马斯克（ Elon Musk ）设想在轨道上运行更热的人工智能芯片，以减轻散热器的重量，从而使空间计算更轻、更便宜。\n\n在一段视频中，马斯克解释说，根据斯特凡-玻尔兹曼定律，将开尔文芯片的工作温度提高20 ％可以将散热器质量减半，其中辐射功率随温度升至第四功率。\n\n他指出，神经网络比传统程序更能容忍辐射位翻转，从而减少了SpaceX的AI1卫星等轨道AI计划的屏蔽需求。在线观点分为质疑他的专业知识的批评者和赞扬物理学支持的逻辑的支持者，突出了太空人工智能的工程挑战。"}, {"id": "2112453611825377473", "domain": "科学", "url": "https://x.com/i/trending/2112453611825377473", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T02:12:34.000Z", "title_en": "Japan Launches MMX Spacecraft for First Phobos Sample Return", "title_zh": "日本发射MMX航天器实现首次火卫一样品返回", "hook_en": "Mission controllers in Japan cheered as the MMX probe separated from its rocket, kicking off a decade-long quest to grab samples from Mars' potato-shaped moon Phobos.", "hook_zh": "随着MMX探测器与火箭分离，日本的任务控制器欢呼雀跃，开始了长达十年的从火星马铃薯形状的卫星火卫一中获取样品的探索。", "summary_en": "Japan's uncrewed MMX spacecraft lifted off Tuesday from Tanegashima Space Center aboard an H3 rocket, embarking on a 10-month trip to Mars to study Phobos and return at least 10 grams of its surface material by 2031. The mission will orbit Mars starting in 2027, deploy a rover from France and Germany around 2029, and attempt up to two landings, with NASA providing key instruments like the P-Sampler for quick sample collection. Scientists aim to learn if Phobos is a captured asteroid or impact debris, shedding light on solar system origins and future Mars exploration.", "summary_zh": "日本无人MMX航天器周二从种子岛航天中心乘坐H3火箭升空，开始为期10个月的火星之旅，研究火卫一，并在2031年之前返回至少10克的表面材料。该任务将从2027年开始绕火星运行，在2029年左右部署来自法国和德国的火星车，并尝试多达两次着陆，美国宇航局将提供P-Sampler等关键仪器用于快速采样。 科学家的目标是了解火卫一是被捕获的小行星还是撞击碎片，从而揭示太阳系的起源和未来的火星探索。", "body_en": "Mission controllers in Japan cheered as the MMX probe separated from its rocket, kicking off a decade-long quest to grab samples from Mars' potato-shaped moon Phobos.\n\nJapan's uncrewed MMX spacecraft lifted off Tuesday from Tanegashima Space Center aboard an H3 rocket, embarking on a 10-month trip to Mars to study Phobos and return at least 10 grams of its surface material by 2031.\n\nThe mission will orbit Mars starting in 2027, deploy a rover from France and Germany around 2029, and attempt up to two landings, with NASA providing key instruments like the P-Sampler for quick sample collection. Scientists aim to learn if Phobos is a captured asteroid or impact debris, shedding light on solar system origins and future Mars exploration.", "body_zh": "随着MMX探测器与火箭分离，日本的任务控制器欢呼雀跃，开始了长达十年的从火星马铃薯形状的卫星火卫一中获取样品的探索。\n\n日本无人MMX航天器周二从种子岛航天中心乘坐H3火箭升空，开始为期10个月的火星之旅，研究火卫一，并在2031年之前返回至少10克的表面材料。\n\n该任务将从2027年开始绕火星运行，在2029年左右部署来自法国和德国的火星车，并尝试多达两次着陆，美国宇航局将提供P-Sampler等关键仪器用于快速采样。科学家的目标是了解火卫一是被捕获的小行星还是撞击碎片，从而揭示太阳系的起源和未来的火星探索。"}, {"id": "2112623559876952326", "domain": "科学", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州模拟轨道阳光", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州模拟轨道阳光。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\n10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。\n\n演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。"}, {"id": "2112490177113244105", "domain": "科学", "url": "https://x.com/i/trending/2112490177113244105", "category": "News", "topics": ["Space"], "updated_at": "2026-10-20T22:35:39.000Z", "title_en": "SpaceX Falcon 9 Launch Creates Stunning Space Jellyfish Over Florida", "title_zh": "SpaceX猎鹰9号在佛罗里达州上空发射令人惊叹的太空水母", "hook_en": "Early Tuesday morning, a SpaceX rocket lit up Florida's pre-dawn sky with a glowing, bulb-shaped plume that looked just like a space jellyfish. Onlookers across the state shared photos, one calling it the perfect way to start the day.", "hook_zh": "周二凌晨，一枚SpaceX火箭点亮了佛罗里达州黎明前的天空，闪闪发光的灯泡状羽毛看起来就像一只太空水母。全州的围观者分享了照片，有人称这是开始一天的完美方式。", "summary_en": "The Bandwagon-5 rideshare mission lifted off at 7:04 a.m. ET from Cape Canaveral, carrying 32 payloads including SpaceX’s second Starfall capsule for returning microgravity-manufactured materials to Earth. The rocket's exhaust plume caught sunrise light high above while the ground stayed dark, creating the captivating jellyfish effect that drew widespread photos and videos. Nine minutes after launch, the first-stage booster nailed its 19th landing on the droneship A Shortfall of Gravitas, and all payloads reached their orbits successfully.", "summary_zh": "Bandwagon-5拼车任务于美国东部时间上午7:04从卡纳维拉尔角起飞，携带32个有效载荷，包括SpaceX的第二个Starfall太空舱，用于将微重力制造的材料返回地球。火箭的排气羽流在高空捕捉到日出，而地面保持黑暗，创造了迷人的水母效果，吸引了广泛的照片和视频。 发射九分钟后，第一级助推器在无人机“重力不足”号上完成了第19次着陆，所有有效载荷都成功抵达了轨道。", "body_en": "SpaceX Falcon 9 Launch Creates Stunning Space Jellyfish Over Florida.\n\nEarly Tuesday morning, a SpaceX rocket lit up Florida's pre-dawn sky with a glowing, bulb-shaped plume that looked just like a space jellyfish. Onlookers across the state shared photos, one calling it the perfect way to start the day.\n\nThe Bandwagon-5 rideshare mission lifted off at 7:04 a.m. ET from Cape Canaveral, carrying 32 payloads including SpaceX’s second Starfall capsule for returning microgravity-manufactured materials to Earth.\n\nThe rocket's exhaust plume caught sunrise light high above while the ground stayed dark, creating the captivating jellyfish effect that drew widespread photos and videos. Nine minutes after launch, the first-stage booster nailed its 19th landing on the droneship A Shortfall of Gravitas, and all payloads reached their orbits successfully.", "body_zh": "周二凌晨，一枚SpaceX火箭点亮了佛罗里达州黎明前的天空，闪闪发光的灯泡状羽毛看起来就像一只太空水母。全州的围观者分享了照片，有人称这是开始一天的完美方式。\n\nBandwagon-5拼车任务于美国东部时间上午7:04从卡纳维拉尔角起飞，携带32个有效载荷，包括SpaceX的第二个Starfall太空舱，用于将微重力制造的材料返回地球。\n\n火箭的排气羽流在高空捕捉到日出，而地面保持黑暗，创造了迷人的水母效果，吸引了广泛的照片和视频。发射九分钟后，第一级助推器在无人机“重力不足”号上完成了第19次着陆，所有有效载荷都成功抵达了轨道。"}, {"id": "2112514540671730138", "domain": "科学", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。"}]};
